"""Гейты ЕДИНСТВЕННОСТИ РЕШЕНИЯ о форме ответа (G-1/G-2) и БЕЗОПАСНОСТИ записи
заголовков ответа (G-13).

ЧТО ЗДЕСЬ УТВЕРЖДАЕТСЯ ОДНОЙ ФРАЗОЙ. Форма ответа — редирект человеку без
JavaScript либо фрагмент слою письма — решается в проекте ровно в одном месте,
`app/pages/htmx.py`, и обработчика, решающего это МИМО слоя, не существует.

⚠️ ГЕЙТ НЕ МОЖЕТ УДОВЛЕТВОРИТЬ СОБСТВЕННЫЙ ПОИСК, И ЭТО СВОЙСТВО СТРУКТУРНОЕ, А
НЕ СЛОВЕСНОЕ. Файл живёт в `tests/`, а ищет в `app/**/*.py` и — с планом 10-03 —
в `app/templates/**/*.html`: области поиска и области существования гейта не
пересекаются НИ ОДНОЙ из двух, поэтому литералы, которые он вынужден выписать
(имя заголовка признака, приставка `HX-`, признак смещённого курсора), в его
собственный счёт не попадают ни одним путём. Фаза 8 уже ловила обратное: гейт,
искавший в области, где лежал сам, краснел на собственных комментариях, и его
«чинили» переписыванием комментариев вместо исходника. ⚠️ ПЕРЕНОСИТЬ ЭТОТ ФАЙЛ В
`app/` ЗАПРЕЩЕНО ПО ЭТОЙ ПРИЧИНЕ, А НЕ ПО СОГЛАШЕНИЮ О РАСКЛАДКЕ КАТАЛОГОВ: там
он начнёт считать сам себя, и первое же «упрощение» будет сделано не над
приложением, а над текстом гейта.

ЧЕТЫРЕ СВОЙСТВА ГЕЙТА ПРОЕКТА, КОТОРЫЕ ЭТОТ ФАЙЛ НЕСЁТ (форма взята у
`tests/test_pages/test_impersonation_gate.py` и `tests/test_pages/test_access_gate.py`):

1. ЧИТАЕТ ИСХОДНИК, А НЕ СОБРАННОЕ ПРИЛОЖЕНИЕ. Цель — поймать обработчик,
   добавленный БУДУЩЕЙ фазой без похода через слой ответа. В объекте приложения
   такой обработчик выглядит совершенно обычно, и отличить «забыли путь
   деградации» от «его тут и не надо» там нечем. В исходнике решение записано
   явным вызовом, и множество вызовов замкнуто. Из того же свойства следует
   независимость от порядка исполнения сюиты и от параллельного прогона: гейт
   не поднимает приложения и не зависит ни от одного его импорта
   (`test_the_gate_imports_no_application_module`).
2. РАЗБИРАЕТ ДЕРЕВО, А НЕ ТЕКСТ. Обоснования в этой кодовой базе объёмны и
   обязательны, а имена заголовков в них называются словами; текстовый поиск
   краснел бы на правку ДОКУМЕНТАЦИИ и молчал бы на переезд значения в
   переменную.
3. ЗАМЫКАЕТ МНОЖЕСТВО. Объединение трёх множеств обязано РАВНЯТЬСЯ множеству
   найденных обработчиков: обработчик будущей фазы не попадёт ни в одно и уронит
   тест вместо того, чтобы оказаться разрешённым по умолчанию.
4. ДОКАЗЫВАЕТ СВОИ ЗУБЫ. Группа `-k control` в конце файла подаёт разборщику
   ИЗМЕНЁННЫЕ копии исходника и утверждает, что каждый гейт краснеет на
   нарушении и зеленеет на настоящем дереве. Обход тридцати шести обработчиков,
   зелёный ПО ПОСТРОЕНИЮ, создаёт уверенность вместо проверки, и обнаруживается
   это в тот единственный день, когда он пропускает настоящий пропуск.

ПОЧЕМУ БУКВАЛЬНОЕ РАВЕНСТВО КРИТЕРИЯ 1 ЗАМЕНЕНО НА ТРОЙКУ УТВЕРЖДЕНИЙ. Критерий
1 фазы просит машинно утвердить, что множество обработчиков с редиректом
СОВПАДАЕТ с множеством, читающим признак htmx. Буквальное равенство утверждать
нельзя, и не потому, что это трудно, а потому, что оно ПРОТИВОРЕЧИТ соседнему
требованию той же фазы: FOUND-04 требует, чтобы признак читался на весь проект
РОВНО ОДИН РАЗ. Значит правое множество по построению состоит из одного элемента
и с множеством из тридцати шести обработчиков не совпадёт ни в одной реализации,
удовлетворяющей FOUND-04. Смысл критерия сохранён контрапозицией и разложен на
три машинных утверждения, которые ВМЕСТЕ дают то же свойство:

| Утверждение | Гейт | Что оно даёт от критерия 1 |
|---|---|---|
| признак htmx читается ровно в одном месте, и это `app/pages/htmx.py` | `test_the_header_is_read_in_exactly_one_place` (`HX_HEADER_READS == 1`) | «читающих признак» ровно один — правая часть равенства сведена в точку |
| каждый POST-обработчик либо идёт через `respond()`, либо стоит в одном из двух объявленных перечней | G-1 `test_every_post_handler_is_classified` | обработчика, решающего форму ответа МИМО слоя, не существует |
| обработчик, уже переведённый на слой ответа, не строит редирект сам | G-2 `test_no_converted_handler_builds_its_own_redirect` | у переведённого не остаётся ВТОРОГО решения о форме ответа |

Прочитанные вместе, три утверждения означают ровно то, чего просит критерий:
каждый обработчик, у которого есть форма ответа, получает её из единственного
места, а второго места, где эта форма решается, в проекте нет.

⚠️ G-2 ПРОХОДИЛ ВАКУУМНО ДО ФАЗЫ 9 — СЕГОДНЯ У НЕГО ДВА ПРЕДМЕТА. Множество
переведённых БЫЛО пусто, и утверждение БЫЛО истинно ни на чём; с планами 09-01 и
09-02 предметов стало ДВА — оба обработчика изменения состояния экрана групп
аккаунта. Число взято ИСПОЛНЕНИЕМ обхода, а не переписано из ревизии:
комментарий, назвавший неверное число, — тот же дефект в другую сторону.
Летопись `NOT_YET_CONVERTED_COUNT` ниже (36 → 35 → 34) говорит о том же
движении, и расходиться этим двум записям права нет.

Гейтом на пустоту G-2 не был и тогда, когда предметов у него не было: его
предмет собирается ТЕМ ЖЕ обходом, который даёт тридцать шесть, обход
проверяется собственным счётчиком (сломанный разбор даёт красный, а не зелёный
ноль), а зубы G-2 доказаны контролем
`test_control_negative_a_converted_handler_with_its_own_redirect_reddens_g2` —
он подаёт разборщику ровно тот исходник, который Фаза 9 и написала.

⚠️ ЧЕГО ГЕЙТ НЕ ВИДИТ — ВЫПИСАНО ЗДЕСЬ, А НЕ ОСТАВЛЕНО НА ДОГАДКУ. Гейт есть
несущий контроль, и ненаписанная граница через один рефакторинг становится
границей НЕИЗВЕСТНОЙ:

1. ОБРАБОТЧИК ВНЕ `app/pages/` — ПРИНЯТАЯ ГРАНИЦА, А НЕ ПРОПУСК. Машинные
   приёмники живут в `app/routes/` (среди них приёмник платёжной системы,
   `@router.post("/webhook")`), и формы ответа человеку у них нет вовсе:
   редирект клиенту-машине бессмыслен, а признак htmx она не присылает. Втянув
   их в перечни, гейт заменил бы осмысленный список шумом, в котором настоящий
   пропуск снова стал бы незаметен.
2. ОБРАБОТЧИК, СОБРАННЫЙ ФАБРИКОЙ, разборщику не виден: декоратор в таком
   исходнике навешивается на возвращённое значение, и связать его с телом по
   дереву нечем. Родственная форма — объявление ВЫЗОВОМ (`add_api_route`) —
   поэтому ЗАПРЕЩЕНА отдельным утверждением: гейт, который чего-то не видит,
   обязан требовать, чтобы этого и не было.
3. ВЫЗОВ `respond(` ЧЕРЕЗ ПСЕВДОНИМ ИМПОРТА (`from app.pages.htmx import respond
   as reply`) считается НЕ переведённым: узнаётся имя вызова, а не связывание
   импорта. Ошибка здесь безопасна по направлению — обработчик окажется в
   перечне отставания, а не «разрешённым по умолчанию».
4. СТОЛКНОВЕНИЕ КЛЮЧЕЙ (два POST-обработчика с одним именем в одном модуле)
   схлопнуло бы две записи в одну — и было бы поймано счётчиком
   `POST_HANDLERS`: число упало бы до тридцати пяти и уронило первый же тест.
"""
