#   выхода, дословно: `мест записи заголовка HX-* в app/ стало 3, а объявлено 2`
#   / `app/pages/htmx.py:365 (redirect_external, HX-Redirect)` / `assert 3 == 2`
#   (номер строки — дерева ДО поколений докстрингов того же плана).
#   Тем же прогоном `test_every_header_write_has_a_safe_right_operand` назвал
#   место `app/pages/htmx.py:365 (redirect_external, HX-Redirect)`.
#
#   3 → 4, Фаза 12, план 12-04. ЧЕТВЁРТАЯ ЗАПИСЬ — СБОРЩИК ФРАГМЕНТА ПОЛОСЫ
#   ВЛОЖЕНИЙ в `app/pages/ads.py`: заголовок события ПОСЛЕ ПОДМЕНЫ, которым
#   ответ удачной загрузки просит форму объявления сохраниться. Без него
#   удачная загрузка перестала бы создавать черновик на `/ads/new` — сегодня
#   это делает снимаемый клиентский код, и смена поведения прошла бы молча
#   (G-5 разведки, решение владельца по Open Question 1).
#   ⚠️ ПОИМЁННОГО ИСКЛЮЧЕНИЯ ЭТА ЗАПИСЬ НЕ ТРЕБУЕТ, и отсутствие записи в
#   `SAFE_BY_NAME` — не пропуск: операнд там ASCII-ЛИТЕРАЛ, то есть принадлежит
#   разрешённому множеству форм ПО ПОСТРОЕНИЮ. Читателю, который придёт сюда за
#   отсутствующей записью, сказано прямо, чтобы он её не искал.
#   ⚠️ НАПРАВЛЕНИЕ ПРОГОНА ЗДЕСЬ ОБРАТНОЕ ПРЕДЫДУЩИМ ДВУМ, И ЭТО ЗАПИСЫВАЕТСЯ,
#   А НЕ СГЛАЖИВАЕТСЯ. Записи 2 → 3 ставились ПОСЛЕ появления места: правило
#   краснело словами «стало больше, чем объявлено». Здесь число объявлено
#   РАНЬШЕ места — того требует порядок RED→GREEN плана, — и правило покраснело
#   с другой стороны, дословно: `мест записи заголовка HX-* в app/ стало 3, а
#   объявлено 4` со списком трёх прежних мест и `assert 3 == 4`. Прогон был, и
#   число взято из него, а не из вычитания в уме.
#
#   4 → 5, Фаза 12, план 12-09. ПЯТАЯ ЗАПИСЬ — СБОРЩИК ОТВЕТА НА ОТКАЗ РАЗБОРА
#   составного запроса в `app/pages/ads.py` (`_parts_refusal_fragment`):
#   заголовок СПОСОБА подмены со значением «дописать в конец». Разбор запроса не
#   состоялся, текущих ключей вложений сервер не знает, и подмена содержимого
#   цели отцепила бы законные вложения (находка CR-02, план 12-06). Это ПЕРВОЕ в
#   проекте применение точечного заголовка, и объявлено оно ВТОРОЙ РАЗ — в
#   перечне `RETARGET_RESWAP_USES` ниже, с обоснованием (D-16). Два объявления
#   на одно место здесь не дублирование: это число отвечает за безопасность
#   ОПЕРАНДА, перечень — за читаемость ПОВЕДЕНИЯ ФОРМЫ по её разметке.
#   ⚠️ ПОИМЁННОГО ИСКЛЮЧЕНИЯ ЭТА ЗАПИСЬ НЕ ТРЕБУЕТ по тому же основанию, что и
#   четвёртая: операнд — ASCII-ЛИТЕРАЛ, то есть принадлежит разрешённому
#   множеству форм ПО ПОСТРОЕНИЮ.
#   ⚠️ ЧИСЛО ПОСТАВЛЕНО ПРОГОНОМ ПОКРАСНЕВШЕГО ПРАВИЛА. Вывод
#   `test_the_number_of_header_writes_is_the_declared_one`, дословно: `мест
#   записи заголовка HX-* в app/ стало 5, а объявлено 4` / `app/pages/ads.py:932
#   (_parts_refusal_fragment, HX-Reswap)` / `assert 5 == 4`.
#
#   5 → 6, Фаза 14, план 14-01. ШЕСТАЯ ЗАПИСЬ — `redirect_internal` (D-11):
#   заголовок полной перезагрузки на ЛОКАЛЬНЫЙ адрес — успех, меняющий личность
#   или шелл, уходит навигацией браузера, а не XHR-подменой. Решение о
#   безопасности операнда принято ТЕМ ЖЕ планом — записью `SAFE_BY_NAME` ниже.
#   ⚠️ ЧИСЛО ПОСТАВЛЕНО ПРОГОНОМ ПОКРАСНЕВШЕГО ПРАВИЛА. Вывод
#   `test_the_number_of_header_writes_is_the_declared_one`, дословно: `мест
#   записи заголовка HX-* в app/ стало 6, а объявлено 5` /
#   `app/pages/htmx.py:441 (redirect_internal, HX-Redirect)` / `assert 6 == 5`.
#   Тем же прогоном `test_every_header_write_has_a_safe_right_operand` назвал
#   место `app/pages/htmx.py:441 (redirect_internal, HX-Redirect)`.
HX_HEADER_WRITES = 6


