# Множество 2: ОБРАБОТЧИКИ, КОТОРЫЕ НЕ ПОЙДУТ ЧЕРЕЗ СЛОЙ ОТВЕТА НИКОГДА
# =============================================================================

# ⚠️ ПЕРЕЧЕНЬ ОБЪЯВЛЕН ПУСТЫМ, А НЕ СНЯТ, И РАЗНИЦА ЗДЕСЬ СМЫСЛОВАЯ. Пустой
# объявленный перечень означает «вопрос задан, и сегодня в нём никого нет»;
# отсутствующий перечень означал бы, что вопроса никто не задавал, — а через
# одну фазу второе неотличимо от первого.
#
# ПОЧЕМУ ОН СЕГОДНЯ ПУСТ. Единственный кандидат, о котором думали при
# планировании, — машинный приёмник платёжной системы; он живёт в
# `app/routes/billing.py`, то есть ВНЕ периметра `app/pages/`, и в обход не
# попадает вовсе. Все тридцать шесть найденных обработчиков отвечают ЧЕЛОВЕКУ,
# то есть у каждого форма ответа есть, и «никогда» про них сказать нельзя.
#
# ⚠️ ЭТО ПЕРЕЧЕНЬ «НИКОГДА НЕ ПОЙДЁТ», А НЕ «ЕЩЁ НЕ ПОШЁЛ», И ОН НАМЕРЕННО
# ОТДЕЛЁН ОТ `NOT_YET_CONVERTED`. Смешав их в один список, проект потерял бы
# способность отличить принятое решение от невыполненной работы: счётчик
# отставания перестал бы убывать до нуля, и никто не заметил бы, что убывать он
# перестал по другой причине.
#
# Форма записи — с обоснованием НА КАЖДЫЙ элемент (взята у
# `tests/test_pages/test_access_gate.py`): перечень, у которого не написано,
# почему кто-то в него входит, через фазу превращается в «наверное, так надо».
NEVER_RESPONDS: dict[str, str] = {}


