# ⚠️ ФАЗОВАЯ СЦЕПКА ЗАКРЫТА: НИ ОДНОЙ ЗАПИСИ ВЫШЕ БОЛЬШЕ НЕ СТОИТ ЗА ПАНЕЛЬЮ
# ПОДТВЕРЖДЕНИЯ, И ЭТО ПРОВЕРЯЕМОЕ УТВЕРЖДЕНИЕ, А НЕ ОБЕЩАНИЕ.
#
# План 10-01 сделал атрибуты отправки панели подтверждения БЕЗУСЛОВНЫМИ, то есть
# все места подтверждения начали слать запрос через слой письма ОДНОМОМЕНТНО, а
# семь обработчиков за ними ещё отвечали перенаправлением. Промежуточное
# состояние снято планом 10-03: задача 1 перевела удаление аккаунта мессенджера
# и удаление объявления, задача 2 — повтор отправки из журнала, перезапуск
# контейнера воркера, снятие задачи из очереди отправки и удаление пользователя
# из его карточки, задача 3 — вход администратора под личностью пользователя.
#
# ⚠️ КРАСНОГО ПРАВИЛА НА ПРОМЕЖУТОЧНОЕ СОСТОЯНИЕ НЕ ЗАВОДИЛОСЬ СОЗНАТЕЛЬНО:
# правило, красное по замыслу, в дереве запрещено — красный цвет обязан означать
# дефект, а не расписание работ. Стражем стал параметризованный обход
# `tests/test_pages/test_confirm_delete_transport.py`: он краснеет на любом из
# восьми маршрутов подтверждения, не отвечающем ОБЕИМ половинам пары
# транспортов, и приземлился в той же волне.

# То же число константой. Утверждений на него ДВА, и они про РАЗНЫЕ события:
# рост означает регрессию, падение означает прогресс вехи.
#
# ЛЕТОПИСЬ ЧИСЛА (каждое движение — запись, а не молчаливая правка):
#   36 → 35, Фаза 9, план 09-01: снят обработчик ПЕРЕКЛЮЧЕНИЯ ГРУППЫ из
#   `app/pages/account_groups.py` — первый обработчик вехи, переведённый на слой
#   ответа. ⚠️ Имя обработчика набрано здесь СЛОВАМИ, а не ключом перечня:
#   снятие ключа проверяется грепом по этому файлу, и запись летописи,
#   набравшая ключ дословно, удовлетворила бы греп сама — проверка зеленела бы
#   на комментарии о снятии вместо самого снятия. ⚠️ ЭТО ДВИЖЕНИЕ СЧЁТЧИКА
#   ПРОГРЕССА ВЕХИ, А НЕ ПРАВКА ТЕСТА ПОД РЕАЛИЗАЦИЮ: текст отказа
#   `test_the_backlog_matches_the_declared_count` написан заранее и прямо
#   требует опустить число и снять переведённый обработчик из перечня. Вместе с
#   этим движением у G-2 (`test_no_converted_handler_builds_its_own_redirect`)
#   ВПЕРВЫЕ появляется предмет: до Фазы 9 множество переведённых было пусто.
#
#   35 → 34, Фаза 9, план 09-02: снят обработчик УДАЛЕНИЯ ГРУППЫ из того же
#   модуля — второй обработчик вехи, переведённый на слой ответа. ⚠️ Имя
#   обработчика здесь снова набрано СЛОВАМИ, а не ключом перечня, и по той же
#   причине: снятие ключа проверяется грепом по этому файлу, и запись летописи,
#   набравшая ключ дословно, удовлетворила бы греп сама. ⚠️ ЭТО ДВИЖЕНИЕ
#   СЧЁТЧИКА ПРОГРЕССА ВЕХИ, А НЕ ПРАВКА ТЕСТА ПОД РЕАЛИЗАЦИЮ. После него оба
#   входа изменения состояния экрана групп аккаунта идут одним слоем ответа, и
#   G-2 проверяет уже два обработчика, а не один.
#
#   34 → 34 (ДВИЖЕНИЯ НЕТ), Фаза 9, план 09-15: маршрут ПОРЦИИ ПРОКРУТКИ того же
#   модуля переведён на слой ответа — обе его ветки отказа перестали строить
#   собственное перенаправление, потому что запрос слоя письма следует за ним
#   прозрачно и вклеивает целую страницу входа в середину списка (WR-04). ЧИСЛО
#   ПРИ ЭТОМ НЕ ДВИНУЛОСЬ, и запись стоит здесь ИМЕННО ПОЭТОМУ: план ожидал
#   падения на единицу, и отсутствие строки оставило бы читателя думать, что
#   перевод не состоялся.
#   ⚠️ ПРИЧИНА ИЗМЕРЕНА, А НЕ ВЫВЕДЕНА. Предмет всех трёх множеств собирает
#   `_post_handlers`, а он отбирает входы ПО ОБЪЯВЛЕНИЮ POST (`_declares_post`);
#   маршрут порции объявлен GET. Прогон дал `len(_backlog(...)) == 34` и
#   `POST_HANDLERS == 36` и ДО перевода, и ПОСЛЕ, а множество переведённых
#   по-прежнему содержит ровно два ключа — тумблер и удаление.
#   ⚠️ ЭТО НАЗВАННАЯ ГРАНИЦА ГЕЙТА, А НЕ ЕГО ОШИБКА, И ОНА ЗАПИСЫВАЕТСЯ, ЧТОБЫ
#   НЕ ОБНАРУЖИТЬСЯ ЧЕРЕЗ ФАЗУ. Счётчик отставания и G-2 видят ТОЛЬКО
#   POST-обработчиков. Фрагментный GET-вход, переведённый на слой ответа, им
#   невидим — как невидимо и обратное: такой вход, вернувший себе собственное
#   перенаправление, гейт не поймает. Фазы 10-15 переводят на слой ответа и
#   GET-входы (порции, статусы, блоки опроса), поэтому расширение области обхода
#   есть решение, которое веха обязана ПРИНЯТЬ, а не унаследовать молча. Здесь
#   оно не принимается: план 09-15 гейт не расширяет — он его границу НАЗЫВАЕТ.
#   ⚠️ Фаза 15, план 15-11 (`DEF-09-04`): граница по-прежнему НЕ расширена —
#   расширение принадлежит вехе, — и у неё появился СТОРОЖ:
#   `test_push_url_g2_universe_holds_only_changing_methods` краснеет, если во
#   вселенную G-2 придёт GET-маршрут (группа запрета D-13 в конце файла).
#
#   34 → 33, Фаза 10, план 10-01. ИСТОЧНИК ДВИЖЕНИЯ: УДАЛЕНИЕ РАСПИСАНИЯ ИЗ
#   РЕДАКТОРА ОБЪЯВЛЕНИЯ переведено на слой ответа — единственный ФРАГМЕНТНЫЙ
#   путь фазы (D-09). ⚠️ Имя обработчика здесь снова набрано СЛОВАМИ, а не
#   ключом перечня, и по той же причине, что двумя записями выше: снятие ключа
#   проверяется грепом по этому файлу, и летопись, набравшая ключ дословно,
#   удовлетворила бы греп сама.
#   ⚠️ ЭТО ДВИЖЕНИЕ СЧЁТЧИКА ПРОГРЕССА ВЕХИ, А НЕ СЛУЖЕБНАЯ КОНСТАНТА. Число
#   УБЫВАЮЩЕЕ: рост означает регрессию, падение — проделанную работу. Фаза 10
#   опускает его до 26 (D-18), и семь оставшихся шагов делает план 10-03
#   следующей волной — см. запись фазовой сцепки у самого перечня.
#   ⚠️ ЧИСЛО ПОСТАВЛЕНО ПРОГОНОМ ПОКРАСНЕВШЕГО ПРАВИЛА. Вывод
#   `test_the_backlog_matches_the_declared_count` на дереве после задачи 1,
#   дословно: `AssertionError: счётчик отставания краснеет на неизменённом
#   дереве / assert 33 == 34`.
#
#   33 → 31, Фаза 10, план 10-03, задача 1. ИСТОЧНИК ДВИЖЕНИЯ: УДАЛЕНИЕ АККАУНТА
#   МЕССЕНДЖЕРА и УДАЛЕНИЕ ОБЪЯВЛЕНИЯ переведены на слой ответа — оба ушли в
#   ветку перехода (204 и заголовок перехода), и оба уходят туда ПО ОБЪЯВЛЕННОМУ
#   ИЗЪЯТИЮ, а не по классу действия: см. `OFFSET_CURSOR_EXCEPTIONS` ниже.
#   ⚠️ Имена обработчиков набраны СЛОВАМИ, а не ключами перечня, и по той же
#   причине, что у записей выше: снятие ключа проверяется грепом по этому файлу.
#   ⚠️ ЧИСЛО ПОСТАВЛЕНО ПРОГОНОМ ПОКРАСНЕВШЕГО ПРАВИЛА — правило было написано
#   ДО перевода обработчиков и назвало в отказе и найденное, и объявленное.
#
#   31 → 27, Фаза 10, план 10-03, задача 2. ИСТОЧНИК ДВИЖЕНИЯ: ПОВТОР ОТПРАВКИ
