#   перевода, дословно: `обработчиков, отдающих фрагмент, найдено 25,
#   объявлено 23` / `assert 25 == 23`.
FRAGMENT_RESPONSE_HANDLERS_DECLARED = 25


def _hands_a_fragment(function: ast.AST) -> bool:
    """Передаёт ли обработчик слою ответа ФРАГМЕНТ — по дереву разбора.

    Признак — ИМЕНОВАННЫЙ АРГУМЕНТ фрагмента у вызова слоя ответа. Узнаются обе
    формы вызова, что и у `_calls_response_layer`: голая (`respond(...)`) и через
    модуль (`htmx.respond(...)`).

    ⚠️ ГРАНИЦА УНАСЛЕДОВАНА У СОСЕДНИХ РАЗБОРЩИКОВ И БЕЗОПАСНА ПО НАПРАВЛЕНИЮ.
    Псевдоним импорта не узнаётся — ровно как у `_calls_response_layer` и
    `_builds_own_redirect`, — и ошибка здесь даёт обработчика, НЕ объявленного
    фрагментным, а не «разрешённого по умолчанию»: он не попадёт в найденное,
    число разойдётся с объявленным, и правило покраснеет.

    ⚠️ ФАЗА 14, ПЛАН 14-02: ПЕРЕДАЧА ФРАГМЕНТА ЗАСЧИТЫВАЕТСЯ И У ВЫХОДА СМЕНЫ
    ЭКРАНА `respond_screen`, И ПРЕЖНЯЯ РЕДАКЦИЯ НЕ СТЁРТА, А ПЕРЕЖИТА: «признак —
    аргумент фрагмента у вызова ГЛАВНОГО выхода» верно для дерева, на котором
    выход, отдающий 200 фрагментом, был один. Ответ смены экрана и есть
    фрагмент в постоянный якорь шага — ровно как шаг мастеров MAX и Telegram, —
    и обработчик, отвечающий им, числился бы ветвью перехода, которой он не
    является. Выход ошибки поля сюда НЕ входит: его фрагмент — та же форма с
    ошибкой, а не смена экрана, и решение о нём этим планом не принималось.
    ЧЕМ ИЗМЕРЕНО: до расширения контроль
    `test_control_a_handler_answering_only_by_a_screen_change_is_converted_and_hands_a_fragment`
    краснел дословно: `передача фрагмента выходу смены экрана не засчитана`.
    """
    fragment_exits = (RESPONSE_CALL, SCREEN_CHANGE_CALL)
    for node in ast.walk(function):
        if not isinstance(node, ast.Call):
            continue
        func = node.func
        is_response_call = (isinstance(func, ast.Name) and func.id in fragment_exits) or (
            isinstance(func, ast.Attribute) and func.attr in fragment_exits
        )
        if not is_response_call:
            continue
        for keyword in node.keywords:
            if keyword.arg == FRAGMENT_ARGUMENT:
                return True
    return False


def _fragment_response_handlers(sources: dict[str, str]) -> set[str]:
    """Обработчики, отдающие фрагмент, — СОБРАНЫ ОБХОДОМ, а не выписаны руками.

    То же свойство, что у `_converted`: множество есть ФАКТ исходника. Перечень
    выше — ОБЪЯВЛЕНИЕ, и расхождение объявления с фактом есть предмет правил
    ниже; собери оба одним обходом — и правило проверяло бы себя.
    """
    found: set[str] = set()
    for module, text in sources.items():
        tree = _parse(module, text)
        for node in ast.walk(tree):
            if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue
            if not any(_declares_post(decorator) for decorator in node.decorator_list):
                continue
            if _hands_a_fragment(node):
                found.add(f"{module}::{node.name}")
    return found


def test_every_fragment_response_handler_is_actually_on_the_response_layer():
    """НЕСУЩЕЕ: каждый объявленный обработчик есть, идёт слоем и отдаёт фрагмент.

    Три утверждения на запись, и ни одно не выводится из остальных:
    обработчик может существовать и не идти слоем ответа; может идти слоем и не
    передавать фрагмента (ветка перехода — ровно так отвечают семеро из восьми
    маршрутов Фазы 10). Отказ обязан назвать обработчика ПОИМЁННО и то, чего у
    него не нашлось: общий отказ «перечень разошёлся» не сказал бы, где искать.
    """
    handlers = _post_handlers(_pages_sources())

    for key in sorted(FRAGMENT_RESPONSE_HANDLERS):
        handler = handlers.get(key)
        assert handler is not None, (
            f"{key}: объявлен отдающим фрагмент, но POST-обработчика с таким "
            "ключом в страничном слое НЕТ. Либо обработчик переименован и "
            "запись устарела, либо ключ набран с опечаткой — и во втором случае "
            "перечень молча перестал накрывать живой фрагментный путь"
        )
        assert handler.calls_respond, (
            f"{key}: объявлен отдающим фрагмент, но слой ответа НЕ ЗОВЁТ вовсе. "
            "Фрагмент, собранный мимо слоя, означает второе решение о форме "
            "ответа в проекте — ровно то, от чего стоят G-1 и G-2"
        )

    found = _fragment_response_handlers(_pages_sources())
    missing = set(FRAGMENT_RESPONSE_HANDLERS) - found
    assert not missing, (
        "объявлены отдающими фрагмент, но именованного аргумента фрагмента у "
        f"вызова слоя ответа НЕ НАЙДЕНО: {sorted(missing)}. Обработчик, "
        "потерявший фрагмент, отвечает переходом там, где экран обязан остаться "
        "на месте, — человек получает перезагрузку вместо подмены строки"
    )


def test_the_number_of_fragment_response_handlers_is_the_declared_one():
    """Число найденных обработчиков с фрагментом равно объявленному.

    ⚠️ ЧИСЛО СТАВИТСЯ ПРОГОНОМ ЭТОГО ОТКАЗА, А НЕ СЛОЖЕНИЕМ В УМЕ — поэтому
    отказ называет и найденное, и объявленное, и перечисляет найденных
    поимённо. Правило существует ровно затем, чтобы фрагментный путь, заведённый
    будущей фазой без записи, не прошёл молча: пустое множество здесь вакуумно
    зелено, и объявленное число — единственное, что делает его непустым.
    """
    found = _fragment_response_handlers(_pages_sources())

    assert len(found) == FRAGMENT_RESPONSE_HANDLERS_DECLARED, (
        f"обработчиков, отдающих фрагмент, найдено {len(found)}, объявлено "
        f"{FRAGMENT_RESPONSE_HANDLERS_DECLARED}: {sorted(found)}.\n"
        "⚠️ ЭТО НЕ СЧЁТЧИК ОТСТАВАНИЯ: он считает ДРУГОЕ множество и УБЫВАЕТ, "
        "а этот РАСТЁТ. Приводить два числа к согласию правкой одного нельзя — "
        "поставьте это число ПРОГОНОМ настоящего отказа"
    )

    assert found == set(FRAGMENT_RESPONSE_HANDLERS), (
        "перечень отдающих фрагмент разошёлся с деревом.\n"
        f"  найдено, но не объявлено: {sorted(found - set(FRAGMENT_RESPONSE_HANDLERS))}\n"
        f"  объявлено, но не найдено: {sorted(set(FRAGMENT_RESPONSE_HANDLERS) - found)}"
    )


def test_no_fragment_response_handler_is_listed_as_not_yet_converted():
    """СОГЛАСОВАННОСТЬ двух счётов: пересечение двух множеств ПУСТО.

    Правило существует потому, что обработчик, стоящий на слое ответа и при этом
    числящийся непереведённым, есть РОВНО ТО расхождение двух множеств, от
    которого стоят гейты единственности решения о форме ответа. Два счёта
    связываются этим правилом, а НЕ приводятся к равенству: равными им быть не
    положено — семеро из восьми маршрутов Фазы 10 переведены и фрагмента не
    отдают.
    """
    overlap = set(FRAGMENT_RESPONSE_HANDLERS) & set(NOT_YET_CONVERTED)
    assert not overlap, (
        f"обработчик числится и отдающим фрагмент, и НЕПЕРЕВЕДЁННЫМ: "
        f"{sorted(overlap)}. Одно из двух неверно, и оба варианта — дефект: "
        "либо перевод состоялся, а ключ из перечня отставания не сняли (счётчик "
        "прогресса вехи лжёт в сторону недооценки), либо запись о фрагменте "
        "поставлена авансом и накрывает путь, которого нет"
    )


# =============================================================================
# ГЕЙТ G-13: БЕЗОПАСНОСТЬ ПРАВОГО ОПЕРАНДА ЗАПИСИ ЗАГОЛОВКА `HX-*`
#
# ЧТО ИМЕННО ЗАКРЫВАЕТ ЭТО ПРАВИЛО — ТРИ УГРОЗЫ ПОИМЁННО, А НЕ «БЕЗОПАСНОСТЬ
# ВООБЩЕ»:
#
#   1. ИНЪЕКЦИЯ ЗАГОЛОВКА (T-08-01). Перевод строки внутри значения дописывает в
#      ответ ЛЮБОЙ заголовок, в том числе `Set-Cookie`.
#   2. ПАДЕНИЕ НА КОДИРОВАНИИ (T-08-02). Значения заголовков кодируются в
#      latin-1; кириллица в них роняет ответ пятисоткой — и роняет его у ВСЕХ,
#      а не у того, кто её принёс.
#   3. ОТКРЫТЫЙ РЕДИРЕКТ (T-08-05). Заголовок перехода есть готовый примитив
#      увода с сайта: браузер уходит по нему молча.
#
# ⚠️ ВСЕ ТРИ ЗАКРЫВАЮТСЯ ОДНИМ СВОЙСТВОМ, И ИМЕННО ОНО ЗДЕСЬ УТВЕРЖДАЕТСЯ:
# значение заголовка не может прийти от клиента НИ ОДНИМ ПУТЁМ. Проверять
# отдельно перевод строки, отдельно кириллицу и отдельно чужой узел значило бы
# вести перечень известных написаний беды; запрет на ИСТОЧНИК закрывает и те
# написания, которых ещё не придумали.
#
# ⚠️ ЧЕГО ЭТО ПРАВИЛО НЕ ВИДИТ. Значение, собранное вспомогательной функцией
# СОСЕДНЕГО модуля, разбором дерева не прослеживается: в месте записи стоит
# вызов, а что внутри — вопрос к другому файлу и к другому дереву. Разрешить
# вызовы КЛАССОМ значило бы открыть ровно ту дыру, ради которой правило
# написано, — поэтому единственный сегодняшний вызов выписан ПОИМЁННО, одной
# записью с обоснованием (`SAFE_BY_NAME`), и безопасность его доказывается не
# разбором дерева, а рантайм-проверкой, у которой есть собственные тесты.
# Родственные невидимые формы — запись через `headers.update(переменная)` и
# ключ, собранный вычислением: обеих в проекте нет, и появление любой из них
# обязано сопровождаться обучением этого разборщика.
# =============================================================================

# Имена, которыми в этом проекте зовут объект входящего запроса. Присутствие
# любого из них в поддереве правого операнда означает, что значение заголовка
# ответа МОЖЕТ прийти от клиента.
REQUEST_OBJECT_NAMES = frozenset({"request", "req", "websocket"})

# Узлы, из которых имеет право состоять подстановка внутри f-строки. Вызов,
# индексация, арифметика и сравнение сюда НЕ входят: за каждым из них стоит
# вычисление, чей источник по этому дереву не прослеживается.
_INERT_NODES = (
    ast.JoinedStr,
    ast.FormattedValue,
    ast.Constant,
    ast.Name,
    ast.Attribute,
    ast.Load,
)


# ⚠️ ИСКЛЮЧЕНИЕ ВЫПИСАНО ЗАПИСЬЮ, А НЕ РАЗРЕШЕНО КЛАССОМ, И РАЗНИЦА ЗДЕСЬ
# НЕСУЩАЯ. «Разрешить вызовы» открыло бы дыру шириной в правило; «разрешить
# ЭТОТ вызов, потому что вот доказательство» оставляет дыру шириной в одну
# строку, и следующая такая строка потребует написать своё доказательство.
SAFE_BY_NAME: dict[str, str] = {
    "app/pages/htmx.py::location_response": (
        "значение приходит ПАРАМЕТРОМ, и безопасность его доказывается не "
        "разбором дерева, а рантайм-проверкой локального пути того же модуля "
        "(`_local_path`): она отвергает схему, протокол-относительный адрес, "
        "обратную косую черту, управляющий символ и любой символ вне ASCII — "
        "то есть все три угрозы разом, и у неё есть собственные тесты "
        "(план 08-01). Разбор дерева здесь бессилен по существу: в месте "
        "записи стоит имя параметра, а значения ему подают вызывающие"
    ),
    # ⚠️ ВТОРАЯ ЗАПИСЬ — ДЫРА В ОДНУ СТРОКУ, А НЕ РАЗРЕШЕНИЕ КЛАССУ (план 11-15).
    "app/pages/htmx.py::redirect_external": (
        "значение приходит ПАРАМЕТРОМ (адрес подтверждения оплаты из ответа "
        "SDK ЮKassa), и безопасность его доказывается не разбором дерева, а "
        "рантайм-проверкой того же модуля (`_confirmation_url`): схема только "
        "https; хост ТОЧНЫМ сравнением из закрытого множества "
        "`YOOKASSA_CONFIRMATION_HOSTS`, так что суффиксные и префиксные подделки "
        "не проходят; без порта; без данных пользователя (любой `@` в узле); без "
        "обратной косой черты; без управляющих символов и только ASCII — то есть "
        "открытый редирект, инъекция заголовка и падение на кодировании закрыты "
        "разом, и у проверки есть собственные тесты по случаю на каждое написание "
        "подделки (план 11-15, "
        "`test_a_confirmation_address_off_the_closed_host_set_never_reaches_the_header`). "
        "⚠️ АСИММЕТРИЯ НАЗВАНА: путь без htmx заголовка НЕ ПИШЕТ и проверки НЕ "
        "НЕСЁТ — он отвечает прежним перенаправлением 302 на тот же адрес. "
        "Основания: источник адреса — ответ SDK по TLS, а не ввод пользователя; "
        "правило границы фазы запрещает менять, ЧТО действие делает (Open "
        "Question 2 RESEARCH Фазы 11)"
    ),
    # ⚠️ ТРЕТЬЯ ЗАПИСЬ — ДЫРА В ОДНУ СТРОКУ, А НЕ РАЗРЕШЕНИЕ КЛАССУ (Фаза 14, план 14-01).
    "app/pages/htmx.py::redirect_internal": (
        "значение приходит ПАРАМЕТРОМ (адрес приземления успеха авторизации), и "
        "безопасность его доказывается не разбором дерева, а рантайм-проверкой "
        "того же модуля: адрес проходит `_with_notice` → `_local_path`, который "
        "отвергает схему, протокол-относительный адрес, обратную косую черту, "
        "управляющие символы и любой символ вне ASCII — открытый редирект, "
        "инъекция заголовка и падение на кодировании закрыты разом; код исхода "
        "берётся только из закрытого реестра (`_require_registered_notice`). У "
        "проверки есть собственные тесты (план 14-01, "
        "`test_an_internal_full_load_never_leaves_the_site_or_carries_unencodable_text`, "
        "`test_an_unregistered_outcome_code_is_refused_by_the_internal_full_load`). "
        "Путь без htmx заголовка не пишет — он отвечает 302 на тот же проверенный "
        "адрес"
    ),
}


@dataclass(eq=False)
class _HeaderWrite:
    """Одно место записи заголовка ответа с приставкой `HX-`."""

    module: str
    lineno: int
    function: str
    header: str
    operand: ast.AST

    @property
    def key(self) -> str:
        return f"{self.module}::{self.function}"

    @property
    def where(self) -> str:
        return f"{self.module}:{self.lineno} ({self.function}, {self.header})"


def _module_string_constants(tree: ast.Module) -> dict[str, str]:
    """Строковые константы УРОВНЯ МОДУЛЯ: имя → значение.

    Нужны затем, чтобы имя заголовка, объявленное константой, узнавалось
    наравне с литералом: `headers={HX_LOCATION_HEADER: ...}` есть та же запись,
    что и `headers={"HX-Location": ...}`, и разборщик, знающий только литерал,
    был бы слеп ровно к той форме, которую проект считает правильной.
    """
    constants: dict[str, str] = {}
    for node in tree.body:
        if not isinstance(node, ast.Assign) or len(node.targets) != 1:
            continue
        target = node.targets[0]
        if not isinstance(target, ast.Name):
            continue
        if isinstance(node.value, ast.Constant) and isinstance(node.value.value, str):
            constants[target.id] = node.value.value
    return constants


def _shared_header_constants(sources: dict[str, str]) -> dict[str, str]:
    """Константы имён заголовков `HX-*`, объявленные ГДЕ УГОДНО в приложении.

    Собираются по всему приложению, а не по одному модулю: константа, ввезённая
    из слоя ответа в соседний модуль, приезжает туда именем, и разбор «по
    текущему файлу» перестал бы узнавать её ровно в тот момент, когда запись
    заголовка переедет из слоя ответа наружу.
    """
    shared: dict[str, str] = {}
    for module, text in sources.items():
        for name, value in _module_string_constants(_parse(module, text)).items():
            if value.upper().startswith(HX_HEADER_PREFIX.upper()):
                shared[name] = value
    return shared


def _header_name(
    node: ast.AST, local: dict[str, str], shared: dict[str, str]
) -> str | None:
    """Имя заголовка, записанное этим узлом-ключом, — либо `None`.

    Узнаются три написания ключа: литерал, голое имя константы и обращение к
    ней через модуль. Ключ, собранный вычислением, не узнаётся — это названная
    граница правила (см. шапку группы).
    """
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return node.value
    if isinstance(node, ast.Name):
        return local.get(node.id) or shared.get(node.id)
    if isinstance(node, ast.Attribute):
        return local.get(node.attr) or shared.get(node.attr)
    return None


def _enclosing_function(tree: ast.Module, lineno: int) -> str:
    """Имя ближайшей объемлющей функции — или `<модуль>`, если её нет.

    Нужно для ключа исключения: `SAFE_BY_NAME` называет МЕСТО записи, а не
    модуль целиком, — иначе одна выписанная строчка разрешала бы всему файлу.
    """
    best: str | None = None
    best_span: int | None = None
    for node in ast.walk(tree):
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        end = getattr(node, "end_lineno", None)
        if end is None or not (node.lineno <= lineno <= end):
            continue
        span = end - node.lineno
        if best_span is None or span < best_span:
            best, best_span = node.name, span
    return best or "<модуль>"


def _header_writes(sources: dict[str, str]) -> list[_HeaderWrite]:
    """Каждое место, где значение присваивается заголовку ответа `HX-*`.

    Узнаются ОБЕ формы записи, и обе обязаны быть видны — закрыв одну, правка
    ушла бы второй:

      * подписка (`response.headers["HX-…"] = …`);
      * ключ в литерале словаря заголовков (`headers={"HX-…": …}`).

    Разбор по дереву, а не грепом: приставка заголовка называется словами в
    обоснованиях соседних модулей — в том числе в комментарии редактора
    объявлений, где записано, ПОЧЕМУ заголовок ставится только при создании, —
    и текстовый поиск посчитал бы эти строки местами записи.
    """
    writes: list[_HeaderWrite] = []
    shared = _shared_header_constants(sources)

    for module, text in sources.items():
        tree = _parse(module, text)
        local = _module_string_constants(tree)

        def _record(key_node: ast.AST, operand: ast.AST) -> None:
            name = _header_name(key_node, local, shared)
            if name is None:
                return
            if not name.upper().startswith(HX_HEADER_PREFIX.upper()):
                return
            writes.append(
                _HeaderWrite(
                    module=module,
                    lineno=key_node.lineno,
                    function=_enclosing_function(tree, key_node.lineno),
                    header=name,
                    operand=operand,
                )
            )

        for node in ast.walk(tree):
            if isinstance(node, ast.Assign):
                for target in node.targets:
                    if isinstance(target, ast.Subscript):
                        _record(target.slice, node.value)
            elif isinstance(node, ast.Dict):
                for key_node, value in zip(node.keys, node.values):
                    if key_node is not None:
                        _record(key_node, value)

    return sorted(writes, key=lambda write: (write.module, write.lineno))


def _operand_is_safe(write: _HeaderWrite, local: dict[str, str]) -> bool:
    """Принадлежит ли правый операнд разрешённому множеству ФОРМ.

    Разрешены ровно три формы, и каждая — по причине, а не по привычке:

      * СТРОКОВЫЙ ЛИТЕРАЛ — значение записано в исходнике целиком;
      * F-СТРОКА, все подстановки которой инертны (имена и обращения к
        атрибутам, без вызовов и без индексации) — значение собрано из объектов
        приложения, а не из строки запроса;
      * ИМЯ МОДУЛЬНОЙ КОНСТАНТЫ того же модуля — тот же литерал, названный.

    Всё остальное — вызов, конкатенация, индексация, тернарник — небезопасно ПО
    УМОЛЧАНИЮ: за каждым стоит вычисление, чей источник по этому дереву не
    прослеживается. Ошибаться такому правилу полагается именно в эту сторону.
    """
    operand = write.operand

    if isinstance(operand, ast.Constant) and isinstance(operand.value, str):
        return True
    if isinstance(operand, ast.Name) and operand.id in local:
        return True
    if isinstance(operand, ast.JoinedStr):
        return all(isinstance(node, _INERT_NODES) for node in ast.walk(operand))
    return False


def _unsafe_header_writes(sources: dict[str, str]) -> list[_HeaderWrite]:
    """Места записи, чей операнд не разрешён ни формой, ни поимённой записью."""
    unsafe: list[_HeaderWrite] = []
    for write in _header_writes(sources):
        local = _module_string_constants(_parse(write.module, sources[write.module]))
        if _operand_is_safe(write, local):
            continue
        if write.key in SAFE_BY_NAME:
            continue
        unsafe.append(write)
    return unsafe


def _writes_touching_the_request(sources: dict[str, str]) -> list[_HeaderWrite]:
    """Места записи, в поддереве операнда которых есть объект входящего запроса.

    ⚠️ ЭТО УТВЕРЖДЕНИЕ ДЕЙСТВУЕТ И НА ПОИМЁННОЕ ИСКЛЮЧЕНИЕ. Выписанная запись
    освобождает место от требования к ФОРМЕ операнда — но не от запрета на его
    ИСТОЧНИК: значение, пришедшее от клиента, остаётся запрещённым везде.
    """
    touching: list[_HeaderWrite] = []
    for write in _header_writes(sources):
        names = {
            node.id for node in ast.walk(write.operand) if isinstance(node, ast.Name)
        }
        if names & REQUEST_OBJECT_NAMES:
            touching.append(write)
    return touching


def test_the_number_of_header_writes_is_the_declared_one():
    """Число мест записи заголовка `HX-*` равно выписанному.

    ⚠️ БЕЗЗВУЧНО ВЫРОСШЕЕ ЧИСЛО ОЗНАЧАЕТ, ЧТО ПОЯВИЛОСЬ МЕСТО, ГДЕ ПРИЛОЖЕНИЕ
    ДИКТУЕТ БРАУЗЕРУ ПОВЕДЕНИЕ, а решения о безопасности его значения никто не
    принимал. Утверждения о форме операнда поймали бы это и сами, но по числу
    видно СРАЗУ, что именно произошло.
    """
    writes = _header_writes(_app_sources())
    listing = "\n".join(f"  {write.where}" for write in writes) or "  (нет)"

    assert len(writes) == HX_HEADER_WRITES, (
        f"мест записи заголовка {HX_HEADER_PREFIX}* в {APP_DIRECTORY}/ стало "
        f"{len(writes)}, а объявлено {HX_HEADER_WRITES}:\n{listing}\n"
        "Каждое такое место диктует браузеру поведение значением, которое "
        "уезжает клиенту. Обнови число ВМЕСТЕ с решением о безопасности "
        "операнда нового места"
    )


def test_every_header_write_has_a_safe_right_operand():
    """G-13: правый операнд каждой записи принадлежит разрешённому множеству форм.

    Разрешённых форм три (литерал, f-строка с инертными подстановками, имя
    модульной константы); всё прочее обязано быть выписано ПОИМЁННО с
    обоснованием. Второе утверждение снимает несвежие исключения: запись,
    пережившая своё место, разрешала бы что-то, чего уже нет, — и первое же
    совпадение имён вернуло бы разрешение к жизни молча.
    """
    sources = _app_sources()
    unsafe = _unsafe_header_writes(sources)

    assert not unsafe, (
        "правый операнд записи заголовка не принадлежит разрешённому множеству "
        "форм:\n  "
        + "\n  ".join(write.where for write in unsafe)
        + "\n\nЧТО ДЕЛАТЬ. Соберите значение литералом или f-строкой, все "
        "подстановки которой — имена и обращения к атрибутам приложения; либо "
        "выпишите место в SAFE_BY_NAME с ДОКАЗАТЕЛЬСТВОМ его безопасности "
        "(рантайм-проверка со своими тестами). Вызов, конкатенация и "
        "индексация небезопасны по умолчанию: их источник по дереву не "
        "прослеживается"
    )

    declared_places = {write.key for write in _header_writes(sources)}
    stale = set(SAFE_BY_NAME) - declared_places
    assert not stale, (
        f"поимённое исключение пережило своё место записи: {sorted(stale)}. "
        "Снимите запись — иначе она молча разрешит первое же место, которое "
        "совпадёт с ней именем"
    )

    unexplained = {key for key, reason in SAFE_BY_NAME.items() if not reason.strip()}
    assert not unexplained, (
        f"поимённое исключение не снабжено доказательством: {sorted(unexplained)}"
    )


def test_no_header_write_touches_the_incoming_request():
    """НАСТОЯЩЕЕ СВОЙСТВО БЕЗОПАСНОСТИ: значение заголовка не приходит от клиента.

    Этим утверждением закрываются РАЗОМ инъекция заголовка, падение ответа на
    кодировании кириллицы и открытый редирект (T-08-01, T-08-02, T-08-05) — не
    перечнем известных написаний беды, а запретом на её ИСТОЧНИК.
    """
    touching = _writes_touching_the_request(_app_sources())

    assert not touching, (
        "в поддереве правого операнда записи заголовка есть объект входящего "
        "запроса:\n  "
        + "\n  ".join(write.where for write in touching)
        + "\n\nЗначение заголовка ответа НЕ ИМЕЕТ ПРАВА приходить от клиента ни "
        "одним путём: перевод строки в нём дописывает в ответ чужие заголовки, "
        "кириллица роняет ответ пятисоткой, а адрес со схемой уводит человека "
        "с сайта молча"
    )


# =============================================================================
# КОНТРОЛИ: доказательство того, что гейты КРАСНЕЮТ (`-k control`)
#
# ⚠️ ЗАЧЕМ ОНИ, ЕСЛИ ВЫШЕ УЖЕ ТРИНАДЦАТЬ ТЕСТОВ. Обход тридцати шести
# обработчиков и девяноста с лишним модулей, зелёный ПО ПОСТРОЕНИЮ, создаёт
# уверенность вместо проверки, и обнаруживается это в тот единственный день,
# когда он пропускает настоящее нарушение. Тринадцать утверждений выше говорят
# «сегодня всё сходится»; контроли ниже говорят «а когда перестанет — я это
# увижу». Это разные высказывания, и второе не следует из первого (T-08-30).
#
# ⚠️ КАЖДЫЙ ОТРИЦАТЕЛЬНЫЙ КОНТРОЛЬ НЕСЁТ УТВЕРЖДЕНИЕ «ПОДМЕНА ЧТО-ТО ИЗМЕНИЛА».
# Контроль, чья подмена не приземлилась (промахнулась мимо якоря, попала не в
# тот модуль), выглядит точно так же, как контроль, доказавший зубы: он зелёный.
# Без этой пары утверждений доказательство доказывало бы само себя — фаза уже
# ловила ровно такой промах.
#
# НИ ОДИН КОНТРОЛЬ НЕ ТРОГАЕТ ФАЙЛОВ ПРОЕКТА. Изменённый исходник пишется во
# ВРЕМЕННЫЙ файл (`tmp_path`) и оттуда подаётся разборщику; боевое дерево
# читается только на чтение.
# =============================================================================

# Модуль, в который контроли кладут подмену. Выбран потому, что объявляет
# POST-обработчик и не объявляет ни одной записи заголовка: подмена в нём видна
# ОБЕИМ группам гейтов и ни одной из них не мешает.
SCRATCH_MODULE = "app/pages/profile.py"


def _sources_with(
    tmp_path, sources: dict[str, str], module: str, text: str
) -> dict[str, str]:
    """Копия поданных исходников, в которой ОДИН модуль подменён — через файл.

    Подмена идёт по-настоящему через файловую систему, а не строкой в памяти:
    так контроль проверяет тот же путь чтения, которым гейт ходит по боевому
    дереву, и не может разойтись с ним из-за кодировки или переносов строк.
    """
    scratch = tmp_path / module.replace("/", "_")
    scratch.write_text(text, encoding="utf-8")

    updated = dict(sources)
    updated[module] = scratch.read_text(encoding="utf-8")
    return updated


def test_control_positive_the_untouched_source_tree_keeps_every_gate_green():
    """ЧТО ДОКАЗЫВАЕТ: на НЕИЗМЕНЁННОМ дереве молчат ВСЕ гейты файла.

    ⚠️ БЕЗ ЭТОГО КОНТРОЛЯ ВСЕ ОТРИЦАТЕЛЬНЫЕ ПРОШЛИ БЫ И У ГЕЙТА, КОТОРЫЙ
    КРАСНЕЕТ ВСЕГДА. «Ловит нарушение» и «ловит ТОЛЬКО нарушение» — разные
    утверждения, и доказательство зубов состоит из обоих: гейт, роняющий сборку
    на любом дереве, был бы не строже, а просто сломан, и его сняли бы первым же
    коммитом.
    """
    pages = _pages_sources()
    app = _app_sources()

    assert _unclassified(pages) == set(), "G-1 краснеет на неизменённом дереве"
    assert _converted_with_own_redirect(pages) == set(), (
        "G-2 краснеет на неизменённом дереве"
    )
    assert len(_backlog(pages)) == NOT_YET_CONVERTED_COUNT, (
        "счётчик отставания краснеет на неизменённом дереве"
    )
    assert len(_header_read_sites(app)) == HX_HEADER_READS, (
        "счётчик чтений признака краснеет на неизменённом дереве"
    )
    assert len(_header_writes(app)) == HX_HEADER_WRITES, (
        "счётчик записей заголовка краснеет на неизменённом дереве"
    )
    assert _unsafe_header_writes(app) == [], (
        "G-13 краснеет на неизменённом дереве"
    )
    assert _writes_touching_the_request(app) == [], (
        "запрет на источник значения краснеет на неизменённом дереве"
    )
    assert _lists_on_an_offset_cursor(_template_sources()) == (
        _declared_offset_cursor_templates()
    ), "перечень изъятий по смещённому курсору краснеет на неизменённом дереве"

    # ⚠️ ПЕРЕЧЕНЬ ТОЧЕЧНЫХ ЗАГОЛОВКОВ ЧИТАЕТСЯ ЗДЕСЬ ПОИМЁННО (план 11-10), И ПО
    # ТОЙ ЖЕ ПРИЧИНЕ, ЧТО ОСТАЛЬНЫЕ: перечень, чьё число никто в круге контроля
    # не читает, можно молча подвинуть, и ни один контроль об этом не скажет.
    #
    # ⚠️ ПРЕЖНЯЯ РЕДАКЦИЯ ЭТИХ ДВУХ СТРОК НАЗЫВАЕТСЯ, А НЕ СТИРАЕТСЯ (Фаза 12,
    # план 12-09). Здесь стояло `_retarget_reswap_uses(app) == {}` с
    # обоснованием «перечень ПУСТ, и его правило полноты зелено при любом
    # состоянии сканера». Обоснование было верно ровно до первого применения:
    # с ним сравнение с пустым словарём перестало утверждать «гейт зелен» и
    # стало утверждать «перечень пуст» — то есть контроль ИСПРАВНОГО дерева
    # краснел бы на принятом решении. Сравнение возвращено к предмету: на
    # неизменённом дереве измеренное множество сходится с ОБЪЯВЛЕННЫМ, каким бы
    # оно ни было. Ослабления нет: при пустом перечне это ровно прежняя строка.
    # Сравниваются КЛЮЧИ, а не словари: обход отдаёт «место → имя заголовка», а
    # перечень — «место → обоснование», и равенство словарей сравнивало бы
    # обоснование с именем заголовка, то есть краснело бы всегда.
    assert len(RETARGET_RESWAP_USES) == RETARGET_RESWAP_USES_DECLARED
    assert set(_retarget_reswap_uses(app)) == set(RETARGET_RESWAP_USES), (
        "перечень применений точечных заголовков краснеет на неизменённом дереве"
    )
    assert _markup_naming_a_pointed_header(_template_sources()) == {}, (
        "имя точечного заголовка найдено в разметке неизменённого дерева"
    )


def test_control_negative_an_undeclared_new_post_handler_reddens_the_completeness(
    tmp_path,
):
    """ЧТО ДОКАЗЫВАЕТ: G-1 ловит обработчик, о котором не знает ни одно множество.

    Это случай, РАДИ КОТОРОГО гейт и существует: обработчик, добавленный будущей
    фазой. При чёрном списке он решал бы форму ответа мимо слоя ПО УМОЛЧАНИЮ, и
    человек без JavaScript узнал бы об этом пустым экраном.
    """
    original = _pages_sources()[SCRATCH_MODULE]
    addition = (
        '\n\n@router.post("/profile/a-route-some-future-phase-will-add")\n'
        "async def a_route_some_future_phase_will_add(request: Request):\n"
        "    return None\n"
    )
    sources = _sources_with(tmp_path, _pages_sources(), SCRATCH_MODULE, original + addition)

    key = f"{SCRATCH_MODULE}::a_route_some_future_phase_will_add"
    assert key in _post_handlers(sources), (
        "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ: разборщик не увидел добавленного обработчика, "
        "и утверждение ниже доказывало бы не зубы гейта, а промах контроля"
    )

    assert key in _unclassified(sources), (
        "ЗАМЫКАЮЩЕЕ УТВЕРЖДЕНИЕ ПОЛНОТЫ НЕ ЗАМЕТИЛО НОВЫЙ POST-ОБРАБОТЧИК — "
        "гейт выродился в чёрный список, и обработчик будущей фазы окажется "
        "решающим форму ответа мимо слоя по умолчанию"
    )


def test_control_negative_a_handler_that_left_the_response_layer_reddens_g1(tmp_path):
    """ЧТО ДОКАЗЫВАЕТ: G-1 ловит СНЯТУЮ зависимость обработчика от слоя ответа.

    Контроль двухшаговый, и оба шага нужны: сперва разборщику подаётся
    обработчик, ходящий через `respond()` (гейт молчит — так выглядит работа
    Фазы 9), затем ТОТ ЖЕ обработчик с той же подписью, но строящий редирект
    сам. Один шаг доказал бы только половину: «краснеет» без «зеленел до этого»
    неотличимо от гейта, который краснеет всегда.
    """
    original = _pages_sources()[SCRATCH_MODULE]
    key = f"{SCRATCH_MODULE}::a_route_phase_nine_converted"

    converted = (
        '\n\n@router.post("/profile/a-route-phase-nine-converted")\n'
        "async def a_route_phase_nine_converted(request: Request):\n"
        '    return await respond(request, redirect="/profile")\n'
    )
    with_layer = _sources_with(
        tmp_path, _pages_sources(), SCRATCH_MODULE, original + converted
    )

    assert key in _converted(with_layer), (
        "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ: обработчик, зовущий слой ответа, не признан "
        "переведённым — второй шаг доказывал бы промах контроля"
    )
    assert key not in _unclassified(with_layer), (
        "G-1 краснеет на обработчике, КОТОРЫЙ ИДЁТ через слой ответа, — значит "
        "он краснеет не на том"
    )

    stripped = (
        '\n\n@router.post("/profile/a-route-phase-nine-converted")\n'
        "async def a_route_phase_nine_converted(request: Request):\n"
        '    return RedirectResponse(url="/profile", status_code=302)\n'
    )
    without_layer = _sources_with(
        tmp_path, _pages_sources(), SCRATCH_MODULE, original + stripped
    )

    assert key not in _converted(without_layer), (
        "ВТОРАЯ ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ: обработчик без вызова слоя ответа всё "
        "ещё признан переведённым"
    )
    assert key in _unclassified(without_layer), (
        "ГЕЙТ НЕ ЗАМЕТИЛ СНЯТУЮ ЗАВИСИМОСТЬ ОТ СЛОЯ ОТВЕТА — обработчик, "
        "переставший ходить через `respond()`, прошёл мимо классификации, и "
        "путь деградации перестал быть обязательным молча"
    )


def _scratch_handler(tmp_path, name: str, body: str) -> tuple[dict[str, str], str]:
    """Синтетический POST-обработчик в модуле подмены — исходники и его ключ."""
    original = _pages_sources()[SCRATCH_MODULE]
    addition = (
        f'\n\n@router.post("/profile/{name.replace("_", "-")}")\n'
        f"async def {name}(request: Request):\n"
        f"    {body}\n"
    )
    sources = _sources_with(tmp_path, _pages_sources(), SCRATCH_MODULE, original + addition)
    return sources, f"{SCRATCH_MODULE}::{name}"


def test_control_a_handler_answering_only_by_a_full_load_is_converted(tmp_path):
    """ЧТО ДОКАЗЫВАЕТ: обработчик, зовущий ТОЛЬКО выход полной перезагрузки, переведён.

    Фаза 14, план 14-01 (RESEARCH Находка 2): вход и два других успеха
    авторизации отвечают выходом полной перезагрузки, а не главным выходом, —
    узнавание по одному имени оставило бы их в отставании навсегда, и ноль
    счётчика вехи был бы недостижим честно.
    """
    sources, key = _scratch_handler(
        tmp_path,
        "a_route_leaving_by_a_full_load",
        'return await redirect_internal(request, redirect="/profile")',
    )
    assert key in _post_handlers(sources), (
        "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ: разборщик не увидел синтетического обработчика"
    )
    assert key in _converted(sources), (
        "обработчик, отвечающий выходом полной перезагрузки, не признан "
        "переведённым — семейство выходов слоя узнаётся не целиком"
    )
    assert key not in _backlog(sources), (
        "обработчик на выходе слоя остался в отставании"
    )


def test_control_a_handler_answering_only_by_a_field_error_is_converted(tmp_path):
    """ЧТО ДОКАЗЫВАЕТ: обработчик, зовущий ТОЛЬКО выход ошибки поля, переведён.

    Фаза 14, план 14-01: у выхода ошибки поля путь деградации — страница, и он
    решает форму ответа так же, как главный выход; обработчик, у которого
    других выходов нет, обязан считаться переведённым.
    """
    sources, key = _scratch_handler(
        tmp_path,
        "a_route_answering_a_field_error",
        "return await respond_field_error(request, page=page, fragment=fragment)",
    )
    assert key in _post_handlers(sources), (
        "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ: разборщик не увидел синтетического обработчика"
    )
    assert key in _converted(sources), (
        "обработчик, отвечающий выходом ошибки поля, не признан переведённым"
    )
    assert key not in _backlog(sources), (
        "обработчик на выходе слоя остался в отставании"
    )


def test_control_a_handler_answering_only_by_a_screen_change_is_converted_and_hands_a_fragment(
    tmp_path,
):
    """ЧТО ДОКАЗЫВАЕТ: выход СМЕНЫ ЭКРАНА переводит обработчик и передаёт фрагмент.

    Фаза 14, план 14-02 (RESEARCH Находка 1). Контроль ДВУХШАГОВЫЙ, и шаги
    доказывают разное:

      1. обработчик, зовущий ТОЛЬКО `respond_screen`, признан переведённым,
         выпал из отставания и числится ОТДАЮЩИМ ФРАГМЕНТ — ответ смены экрана и
         есть фрагмент в постоянный якорь шага, как шаг мастеров MAX и Telegram;
      2. сборщики `page=`/`fragment=`, поданные этому выходу ИМЕНЕМ, не
         объявляются собственными выходами обработчика — та же граница сборщика,
         что у выхода ошибки поля (план 11-09).
    """
    sources, key = _scratch_handler(
        tmp_path,
        "a_route_changing_the_screen",
        "return await respond_screen(request, page=page, fragment=fragment)",
    )
    assert key in _post_handlers(sources), (
        "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ: разборщик не увидел синтетического обработчика"
    )
    assert key in _converted(sources), (
        "обработчик, отвечающий выходом смены экрана, не признан переведённым — "
        "семейство выходов слоя узнаётся не целиком"
    )
    assert key not in _backlog(sources), "обработчик на выходе слоя остался в отставании"
    assert key in _fragment_response_handlers(sources), (
        "передача фрагмента выходу смены экрана не засчитана — экран, "
        "подменяющий якорь шага, числился бы ветвью перехода"
    )

    sources, key = _scratch_handler(
        tmp_path,
        "a_route_changing_the_screen_with_builders",
        "\n    ".join(
            (
                "async def _page():",
                '    return HTMLResponse("<!DOCTYPE html>")',
                "async def _fragment():",
                '    return HTMLResponse("<p>шаг</p>")',
                "return await respond_screen(request, page=_page, fragment=_fragment)",
            )
        ),
    )
    assert key in _post_handlers(sources), (
        "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ: разборщик не увидел синтетического обработчика"
    )
    assert key not in _converted_with_own_response(sources), (
        "сборщики, поданные выходу смены экрана именем, объявлены собственными "
        f"выходами обработчика: {_converted_with_own_response(sources).get(key)}"
    )


def test_control_a_lookalike_exit_name_does_not_convert_a_handler(tmp_path):
    """ЧТО ДОКАЗЫВАЕТ: узнаётся ИМЯ выхода, а не приставка — похожее имя не переводит.

    Без этого контроля расширение узнавания до семейства зеленело бы и на
    сравнении по приставке: `respond_later(...)` выхода слоя не зовёт, пути
    деградации не несёт, и обработчик с ним обязан остаться неклассифицированным.
    """
    sources, key = _scratch_handler(
        tmp_path,
        "a_route_with_a_lookalike_exit",
        "return await respond_later(request)",
    )
    assert key in _post_handlers(sources), (
        "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ: разборщик не увидел синтетического обработчика"
    )
    assert key not in _converted(sources), (
        "похожее имя засчитано выходом слоя — узнавание идёт по приставке"
    )
    assert key in _backlog(sources), "обработчик без выхода слоя выпал из отставания"
    assert key in _unclassified(sources), (
        "обработчик без выхода слоя не виден замыкающему утверждению полноты"
    )


def test_control_negative_a_converted_handler_with_its_own_redirect_reddens_g2(
    tmp_path,
):
    """ЧТО ДОКАЗЫВАЕТ: G-2 краснеет на ВТОРОМ решении о форме ответа.

    ⚠️ ЭТОТ КОНТРОЛЬ ЕДИНСТВЕННЫЙ, КТО СЕГОДНЯ ДОКАЗЫВАЕТ ЗУБЫ G-2. Само
    утверждение проходит вакуумно: до Фазы 9 переведённых обработчиков нет, и
    отличить «ловит» от «не смотрит» без подмены нечем. Здесь разборщику
    подаётся ровно тот исходник, который Фаза 9 могла бы написать по
    невнимательности.
    """
    original = _pages_sources()[SCRATCH_MODULE]
    key = f"{SCRATCH_MODULE}::a_route_with_two_decisions"

    addition = (
        '\n\n@router.post("/profile/a-route-with-two-decisions")\n'
        "async def a_route_with_two_decisions(request: Request, ok: bool):\n"
        "    if ok:\n"
        '        return RedirectResponse(url="/profile", status_code=302)\n'
        '    return await respond(request, redirect="/profile")\n'
    )
    sources = _sources_with(
        tmp_path, _pages_sources(), SCRATCH_MODULE, original + addition
    )

    assert key in _converted(sources), (
        "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ: обработчик не признан переведённым, и "
        "утверждение ниже проверяло бы пустое множество"
    )

    assert key in _converted_with_own_redirect(sources), (
        "G-2 НЕ ЗАМЕТИЛ ВТОРОГО РЕШЕНИЯ О ФОРМЕ ОТВЕТА — обработчик ходит через "
        "слой ответа и строит редирект сам, а какое из двух решений исполнится, "
        "зависит от ветки выполнения"
    )


def test_control_negative_a_second_reading_of_the_header_reddens_the_singleness(
    tmp_path,
):
    """ЧТО ДОКАЗЫВАЕТ: счётчик чтений ловит ВТОРОЕ чтение признака htmx.

    Это тот самый дефект, ради которого критерий 1 фазы и написан: скопированная
    строка чтения заголовка, из-за которой путь со слоем письма и путь без него
    расходятся молча.
    """
    original = _app_sources()[SCRATCH_MODULE]
    addition = (
        '\n\n@router.post("/profile/a-second-reading")\n'
        "async def a_second_reading(request: Request):\n"
        f'    return bool(request.headers.get("{HX_REQUEST_HEADER_NAME}"))\n'
    )
    sources = _sources_with(tmp_path, _app_sources(), SCRATCH_MODULE, original + addition)

    sites = _header_read_sites(sources)
    modules = {module for module, _ in sites}

    assert SCRATCH_MODULE in modules, (
        "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ: второе чтение признака не найдено в модуле, "
        "куда его положили"
    )
    assert len(sites) > HX_HEADER_READS, (
        "СЧЁТЧИК ЧТЕНИЙ НЕ ЗАМЕТИЛ ВТОРОГО ЧТЕНИЯ ПРИЗНАКА — единственность "
        "решения о форме ответа перестала быть утверждением и стала надеждой"
    )


def test_control_negative_a_header_written_from_the_query_string_reddens_the_gate(
    tmp_path,
):
    """ЧТО ДОКАЗЫВАЕТ: G-13 ловит значение заголовка, ПРИШЕДШЕЕ ОТ КЛИЕНТА.

    Это главная угроза правила: строка запроса едет в заголовок ответа, и вместе
    с ней едут инъекция заголовка, кириллица и увод на чужой сайт (T-08-01,
    T-08-02, T-08-05).
    """
    original = _app_sources()[SCRATCH_MODULE]
    addition = (
        '\n\n@router.post("/profile/a-header-from-the-query-string")\n'
        "async def a_header_from_the_query_string(request: Request):\n"
        "    response = Response()\n"
        '    response.headers["HX-Push-Url"] = request.query_params["next"]\n'
        "    return response\n"
    )
    sources = _sources_with(tmp_path, _app_sources(), SCRATCH_MODULE, original + addition)

    written_here = [
        write for write in _header_writes(sources) if write.module == SCRATCH_MODULE
    ]
    assert written_here, (
        "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ: разборщик не увидел добавленного места записи "
        "заголовка, и утверждения ниже доказывали бы промах контроля"
    )

    assert [write.where for write in _writes_touching_the_request(sources)], (
        "ГЕЙТ НЕ ЗАМЕТИЛ, ЧТО ЗНАЧЕНИЕ ЗАГОЛОВКА ПРИШЛО ОТ КЛИЕНТА — правило "
        "закрывает три угрозы запретом на ИСТОЧНИК, и без этой проверки оно не "
        "закрывает ни одной"
    )
    assert [write.where for write in _unsafe_header_writes(sources)], (
        "ГЕЙТ ПРИЗНАЛ ИНДЕКСАЦИЮ СТРОКИ ЗАПРОСА РАЗРЕШЁННОЙ ФОРМОЙ ОПЕРАНДА"
    )


def test_control_negative_a_header_assembled_from_cyrillic_text_reddens_the_gate(
    tmp_path,
):
    """ЧТО ДОКАЗЫВАЕТ: G-13 ловит значение, СОБРАННОЕ КОНКАТЕНАЦИЕЙ с текстом.

    ⚠️ ЭТОТ КОНТРОЛЬ ПРО ДРУГУЮ ПОЛОВИНУ ПРАВИЛА, ЧЕМ ПРЕДЫДУЩИЙ. Там источник
    значения — клиент; здесь источник свой, а беда в ФОРМЕ: кириллица в значении
    заголовка роняет ответ пятисоткой на кодировании в latin-1, и роняет его у
    всех сразу. Поэтому по этому каналу едет КОД уведомления, а не его текст.
    """
    original = _app_sources()[SCRATCH_MODULE]
    addition = (
        '\n\n@router.post("/profile/a-header-assembled-from-text")\n'
        "async def a_header_assembled_from_text(request: Request):\n"
        "    response = Response()\n"
        '    response.headers["HX-Push-Url"] = "/profile?notice=" + "Сохранено"\n'
        "    return response\n"
    )
    sources = _sources_with(tmp_path, _app_sources(), SCRATCH_MODULE, original + addition)

    written_here = [
        write for write in _header_writes(sources) if write.module == SCRATCH_MODULE
    ]
    assert written_here, (
        "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ: разборщик не увидел добавленного места записи"
    )
    assert not _writes_touching_the_request(sources), (
        "КОНТРОЛЬ ПРОВЕРЯЕТ НЕ ТО: значение собрано из литералов и объекта "
        "запроса не касается — красноту обязано давать правило ФОРМЫ, а не "
        "правило источника"
    )

    unsafe = {write.module for write in _unsafe_header_writes(sources)}
    assert SCRATCH_MODULE in unsafe, (
        "ГЕЙТ ПРИЗНАЛ КОНКАТЕНАЦИЮ РАЗРЕШЁННОЙ ФОРМОЙ ОПЕРАНДА — кириллица в "
        "значении заголовка уронит ответ пятисоткой, и увидеть это можно будет "
        "только по проводу"
    )


def test_control_negative_a_third_header_write_reddens_the_counter(tmp_path):
    """ЧТО ДОКАЗЫВАЕТ: счётчик мест записи краснеет САМ ПО СЕБЕ.

    Подменённое место БЕЗОПАСНО по форме (литерал), поэтому правила операнда
    молчат — краснеет только счёт. Без этого различения нельзя было бы сказать,
    есть ли у счётчика собственные зубы или он всегда прячется за правилом
    операнда: появление нового места, где приложение диктует браузеру поведение,
    обязано быть решением, а не следствием.

    ⚠️ ИМЯ КОНТРОЛЯ ПЕРЕЖИЛО СВОЁ ЧИСЛИТЕЛЬНОЕ (план 11-15). С третьей
    настоящей записью (`redirect_external`) подменённое место стало ЧЕТВЁРТЫМ;
    имя не переименовано, потому что предмет контроля — «ещё одно место сверх
    объявленного», а не его порядковый номер.
    """
    original = _app_sources()[SCRATCH_MODULE]
    addition = (
        '\n\n@router.post("/profile/a-third-place-of-writing")\n'
        "async def a_third_place_of_writing(request: Request):\n"
        "    response = Response()\n"
        '    response.headers["HX-Push-Url"] = "/profile"\n'
        "    return response\n"
    )
    sources = _sources_with(tmp_path, _app_sources(), SCRATCH_MODULE, original + addition)

    writes = _header_writes(sources)

    assert any(write.module == SCRATCH_MODULE for write in writes), (
        "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ: третье место записи не найдено"
    )
    assert _unsafe_header_writes(sources) == [], (
        "КОНТРОЛЬ ПРОВЕРЯЕТ НЕ ТО: подменённое место обязано быть БЕЗОПАСНЫМ по "
        "форме, иначе краснота придёт от правила операнда, а не от счётчика"
    )
    assert len(writes) != HX_HEADER_WRITES, (
        "СЧЁТЧИК МЕСТ ЗАПИСИ НЕ ЗАМЕТИЛ ТРЕТЬЕГО МЕСТА — новое место, где "
        "приложение диктует браузеру поведение, появилось бы молча"
    )


# Файл разметки, которого в дереве нет: контроль изъятий по курсору кладёт в
# словарь прочитанной разметки НОВЫЙ файл, а не портит существующий. Список,
# появившийся будущей фазой, — ровно тот случай, ради которого правило и
# написано, и подделывать его правкой живого экрана значило бы проверять другое.
SCRATCH_TEMPLATE = "app/templates/accounts/a_list_some_future_phase_will_add.html"


def test_control_negative_an_undeclared_offset_cursor_list_reddens_the_gate(tmp_path):
    """ЧТО ДОКАЗЫВАЕТ: перечень изъятий краснеет на НЕОБЪЯВЛЕННОМ списке.

    ⚠️ БЕЗ ЭТОГО КОНТРОЛЯ ПРАВИЛО ЧИСЛА ПРОВЕРЯЛО БЫ СОГЛАСОВАННОСТЬ ДВУХ СТРОК
    ОДНОГО ФАЙЛА. Изъятие имеет смысл ровно постольку, поскольку список,
    заведённый будущей фазой на смещённом курсоре и с панелью удаления в строке,
    КРАСНЕЕТ, а не проезжает молча: молча проехавший получит фрагментное
    удаление, и следующая порция начнёт пропускать ровно одну карточку.

    Подмена двухшаговая по форме контролей этого файла: сперва утверждается, что
    она приземлилась (иначе краснота ниже доказывала бы промах контроля), затем
    — что гейт увидел именно её.
    """
    addition = (
        "{% from \"components/modal.html\" import modal %}\n"
        '<div hx-get="/accounts/partial?offset={{ next_offset }}&limit=30"'
        ' hx-trigger="revealed" hx-swap="outerHTML">Загрузка...</div>\n'
        "{{ modal(id='acc-del-' ~ account.id,\n"
        "         title='Удалить аккаунт?',\n"
        "         action='/accounts/' ~ account.id ~ '/delete',\n"
        "         confirm_label='Удалить') }}\n"
    )
    templates = _sources_with(
        tmp_path, _template_sources(), SCRATCH_TEMPLATE, addition
    )

    found = _lists_on_an_offset_cursor(templates)

    assert SCRATCH_TEMPLATE in found, (
        "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ: обход не увидел списка на смещённом курсоре с "
        "панелью удаления в той же разметке — утверждение ниже доказывало бы "
        "промах контроля, а не зубы правила"
    )
    assert found != _declared_offset_cursor_templates(), (
        "ПЕРЕЧЕНЬ ИЗЪЯТИЙ НЕ ЗАМЕТИЛ НЕОБЪЯВЛЕННОГО СПИСКА НА СМЕЩЁННОМ "
        "КУРСОРЕ — правило выродилось в сличение двух строк одного файла, и "
        "список, заведённый будущей фазой, получил бы фрагментное удаление "
        "молча"
    )


def test_control_negative_a_list_without_a_delete_panel_stays_out_of_the_gate(tmp_path):
    """ЧТО ДОКАЗЫВАЕТ: правило требует ПЕРЕСЕЧЕНИЯ двух свойств, а не одного.

    ⚠️ ЭТОТ КОНТРОЛЬ ПРО ГРАНИЦУ, А НЕ ПРО ЗУБЫ, И БЕЗ НЕГО ПРАВИЛО БЫЛО БЫ
    СТРОЖЕ, ЧЕМ ЕГО ПРЕДМЕТ. Списков на смещённом курсоре в дереве больше двух;
    изъятие имеет смысл только там, где фрагментное удаление вообще возможно, то
    есть где строка несёт панель удаления. Правило, краснеющее на любом
    смещённом курсоре, потребовало бы объявлять изъятием историю отправок — и
    настоящее изъятие потерялось бы среди строк, не имеющих к форме ответа
    отношения.
    """
    addition = (
        '<div hx-get="/history/partial?offset={{ next_offset }}&limit=30"'
        ' hx-trigger="revealed" hx-swap="outerHTML">Загрузка...</div>\n'
    )
    templates = _sources_with(
        tmp_path, _template_sources(), SCRATCH_TEMPLATE, addition
    )

    assert SCRATCH_TEMPLATE in templates, "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ"
    assert SCRATCH_TEMPLATE not in _lists_on_an_offset_cursor(templates), (
        "ПРАВИЛО КРАСНЕЕТ НА СПИСКЕ БЕЗ ПАНЕЛИ УДАЛЕНИЯ — оно требует объявлять "
        "изъятием то, у чего изымать нечего, и настоящее изъятие потеряется "
        "среди таких строк"
    )


def test_control_negative_an_undeclared_fragment_handler_reddens_the_gate(tmp_path):
    """ЧТО ДОКАЗЫВАЕТ: второй счёт ловит фрагментный путь, заведённый без записи.

    ⚠️ БЕЗ ЭТОГО КОНТРОЛЯ ВТОРОЙ СЧЁТ БЫЛ БЫ ВАКУУМНО ЗЕЛЁН. Сломанный
    разборщик (переехавшее имя аргумента, псевдоним импорта, опечатка в признаке
    вызова) даёт ПУСТОЕ множество найденных, а пустое множество сходится с
    объявленным числом ровно в тот день, когда число тоже обнулят. Подмена ниже
    подаёт разборщику обработчика, который фрагмент ОТДАЁТ и записью НЕ
    объявлен, и утверждает, что правило числа краснеет именно на нём.
    """
    original = _pages_sources()[SCRATCH_MODULE]
    addition = (
        '\n\n@router.post("/profile/a-fragment-route-some-future-phase-will-add")\n'
        "async def a_fragment_route_some_future_phase_will_add(request: Request):\n"
        "    async def _fragment():\n"
        "        return None\n"
        "\n"
        '    return await respond(request, redirect="/profile", fragment=_fragment)\n'
    )
    sources = _sources_with(
        tmp_path, _pages_sources(), SCRATCH_MODULE, original + addition
    )

    key = f"{SCRATCH_MODULE}::a_fragment_route_some_future_phase_will_add"
    found = _fragment_response_handlers(sources)

    assert key in found, (
        "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ: разборщик не увидел обработчика, передающего "
        "фрагмент, и утверждение ниже доказывало бы не зубы правила, а промах "
        "контроля"
    )
    assert len(found) != FRAGMENT_RESPONSE_HANDLERS_DECLARED, (
        "ПРАВИЛО ЧИСЛА НЕ ЗАМЕТИЛО НЕОБЪЯВЛЕННЫЙ ФРАГМЕНТНЫЙ ПУТЬ — второй счёт "
        "выродился в пустое множество, и фрагмент, заведённый будущей фазой без "
        "записи, пройдёт молча"
    )
    assert key not in set(FRAGMENT_RESPONSE_HANDLERS), (
        "подставленный ключ оказался в ОБЪЯВЛЕННОМ перечне — контроль перестал "
        "быть отрицательным"
    )

    # ⚠️ ПОДМЕНА НЕ ИМЕЕТ ПРАВА ПРОТЕЧЬ В СЛЕДУЮЩИЙ ТЕСТ ЧЕРЕЗ КЭШ ЧТЕНИЯ.
    # Исходники читаются через `lru_cache`, и контроль, оставивший подменённый
    # модуль в кэше, покрасил бы соседние правила причиной, к ним не
    # относящейся. Утверждение исполняется, а не подразумевается.
    assert _fragment_response_handlers(_pages_sources()) == set(
        FRAGMENT_RESPONSE_HANDLERS
    ), (
        "ПОДМЕНА ПРОТЕКЛА ЗА ГРАНИЦУ КОНТРОЛЯ: свежее чтение боевого дерева "
        "вернуло подменённый модуль"
    )


# =============================================================================
# ЗАЯВЛЕННОЕ РАСХОЖДЕНИЕ ФОРМЫ ОТКАЗА ВАЛИДАЦИИ С D-01 — `WR-03`
#
# ⚠️ РАСХОЖДЕНИЕ, А НЕ ИЗЪЯТИЕ, И РАЗНИЦА ЗДЕСЬ НЕ В СЛОВЕ. D-01 —
# ЗАПЕРТОЕ решение владельца («форма ответа выбирается ПО КЛАССУ ДЕЙСТВИЯ»).
# Единственный прецедент изъятия из него, D-08, назван в записи решений фазы
# «ИМЕНОВАННЫМ ИЗЪЯТИЕМ ИЗ D-01» и записан ВЛАДЕЛЬЦЕМ на этапе обсуждения, с
# измеренным основанием. Из ФОРМЫ прецедента следует АВТОРСТВО: изъятие из
# запертого решения чеканит владелец, а не план и не исполнитель. Поэтому
# настоящий перечень объявляет РАСХОЖДЕНИЕ — факт, что форму отказа на семи
# входах выбирает фреймворк, а не слой ответа, — и несёт у каждой записи
# СОСТОЯНИЕ РЕШЕНИЯ «ЖДЁТ ВЛАДЕЛЬЦА». Само решение передано владельцу окном
# реестра `.planning/WINDOWS.md` по форме окон 34 и 47.
#
# ⚠️ МАШИННЫЙ ГЕЙТ ОТ ЭТОГО НЕ СЛАБЕЕТ, И В ЭТОМ ВЕСЬ СМЫСЛ РАЗВЕДЕНИЯ. Ревизия
# четвёртого круга назвала молчаливое умолчание ХУДШИМ из трёх исходов, «потому
# что оно читается как исполненный инвариант». Перечень расхождения запрещает
# молчание ровно так же, как запрещал бы перечень изъятия: вход, у которого
# граница величины стои́т на уровне фреймворка и который здесь не назван,
# краснит прогон с именем. ОТЛОЖЕНО РЕШЕНИЕ О ЛЕГИТИМНОСТИ РАСХОЖДЕНИЯ, А НЕ
# ЕГО ВИДИМОСТЬ.
#
# ⚠️ ГРАНИЦА ВНУТРЬ ОБРАБОТЧИКОВ ЗДЕСЬ НЕ ПЕРЕНОСИТСЯ, И ЭТО ОСНОВАНИЕ, А НЕ
# ОТГОВОРКА. План 10-12 свёл эту границу к ОДНОМУ владельцу на все входы ради
# закрытия блокеров `CR-01` и `CR-02` (летопись имени `ID_MAX` —
# `app/pages/schedules.py:63-72`). Перенос внутрь обработчиков развёл бы одно
# правило на семь мест, то есть закрыл бы находку ценой возврата предмета, ради
# которого предыдущая партия существовала.
#
# ⚠️ ПОКОЛЕНИЕ АБЗАЦА ВЫШЕ (Фаза 11, план 11-02, решение D-07; абзац не
# стирается — идиома D-30/D-32). Основание ОПРОВЕРГНУТО для модуля расписаний:
# граница перенесена внутрь обработчиков, но ЧИСЛО осталось одно — в
# `app/pages/identifiers.py`, — а разведение «на семь мест» не случилось, потому
# что мест проверки ОДНО: помощник `id_in_column`. Семь записей модуля
# расписаний сняты из перечня РАБОТОЙ, и замер их больше не находит.
# =============================================================================


@dataclass(frozen=True)
class _ValidationRefusalDivergence:
    """Одно заявленное РАСХОЖДЕНИЕ формы отказа валидации с D-01.

    Пять полей, и ни одно не служебное: ВХОД (что именно расходится),
    ПСЕВДОНИМ границы (чем расхождение сделано), ОБОСНОВАНИЕ (цена и
    достижимость), УСЛОВИЕ СНЯТИЯ (когда расхождение исчезнет) и СОСТОЯНИЕ
    РЕШЕНИЯ (кто и чем признал расхождение законным — либо что оно ещё никем не
    признано).
    """

    entry: str
    alias: str
    reason: str
    lifting_condition: str
    decision_state: str


# ⚠️ СОСТОЯНИЕ РЕШЕНИЯ ПО УМОЛЧАНИЮ — ЖДУЩЕЕ, И ОНО ЗДЕСЬ ЕДИНСТВЕННОЕ. Строка
# вынесена константой не ради краткости, а ради правила авторства ниже: оно
# сличает состояние записи ИМЕННО с этой строкой, и запись, переведённая в
# «решено» правкой одного поля, обязана назвать, ЧЕМ решена.
DECISION_WAITS_FOR_THE_OWNER = "ЖДЁТ ВЛАДЕЛЬЦА"

# ⚠️ ВТОРОЕ СОСТОЯНИЕ — РЕШЁННОЕ ВЛАДЕЛЬЦЕМ ЛИЧНО, И ОНО ЗАВЕДЕНО НЕ ПЛАНОМ, А
# ПЕРЕПИСАНО ИЗ ЗАПИСИ РЕШЕНИЙ ФАЗЫ (Фаза 11, план 11-12). Решение D-08 Фазы 11
# принято ВЛАДЕЛЬЦЕМ на обсуждении 2026-09-14 — единственное из шестнадцати, не
# делегированное исполнителю обсуждения (`11-CONTEXT.md`, «Как получены
# решения»). Строка называет решение идентификатором `D-08` — ровно той формой,
# которую правило авторства (`_DECISION_REFERENCE`) принимает за ссылку на
# принявшего. Записи, стоящие в этом состоянии, — ТОЛЬКО те, которые D-08
# перечисляет поимённо; присвоить его записи, которой D-08 не называет, значило
# бы дочеканить решение за владельца.
#
# ⚠️ ВТОРОЕ ПОКОЛЕНИЕ ГРАНИЦЫ (Фаза 11, план 11-13). Абзац выше не стёрт: он
# верен, и граница «только записи, которые D-08 называет» остаётся. Уточнено,
# КАКИЕ записи D-08 называет. Его текст дословно: «Голый `Response(status_code=403)`
# на провале `is_same_origin` ОСТАЁТСЯ и объявляется именованным изъятием. К
# девяти записям `OWN_RESPONSE_EXITS` добавляются три обработчика этой фазы». То
# есть предмет решения — ФОРМА отказа по источнику для ВСЕГО реестра: девять
# прежних записей названы им как множество («к девяти записям»), три новых —
