#   23 → 16, Фаза 11, план 11-02, задача 2: семь входов модуля расписаний сняты
#   РАБОТОЙ (D-07), замер их больше не находит. Граница величины уехала внутрь
#   четырёх обработчиков (`id_in_column`, `app/pages/identifiers.py`), псевдонимы
#   модуля стали POST-псевдонимами без `ge=`/`le=`, и
#   `_framework_bounded_post_inputs` перестал их видеть.
#   ⚠️ ЧИСЛО ПОСТАВЛЕНО ПРОГОНОМ ПОКРАСНЕВШИХ ПРАВИЛ, А НЕ ВЫЧИТАНИЕМ В УМЕ. После
#   перевода обработчиков правило полноты
#   `test_every_framework_bounded_input_is_declared_as_a_divergence` предъявило
#   СЕМЬ жалоб «ОБЪЯВЛЕН, НО ЗАМЕРОМ НЕ НАЙДЕН: app/pages/schedules.py::…»
#   (создание — форма `ad_id` и `account_id`; правка — адрес `schedule_id`, форма
#   `ad_id` и `account_id`; тумблер и удаление — адрес `schedule_id`); записи
#   сняты по этим ключам, и правило числа предъявило «расхождений формы отказа
#   валидации стало 16, а объявлено 23» до сдвига.
#   ⚠️ `LIFTING_CONDITION_VALIDATION_REFUSAL` НЕ ПРАВИТСЯ: он называет Фазу 11 и
#   остаётся верным для шестнадцати записей, которые снимут следующие планы фазы.
#
#   16 → 14, Фаза 11, план 11-06, задача 2: ДВА входа модуля ОБЪЯВЛЕНИЙ сняты
#   РАБОТОЙ (D-07) — адрес `ad_id` маршрутов `POST /ads/{ad_id}/edit` и
#   `POST /ads/{ad_id}/delete`. Оба обработчика перешли на `PostIdPath` (без
#   `ge=`/`le=`), первое использование параметра в каждом стало аргументом
#   `id_in_column`, и `_framework_bounded_post_inputs` их больше не видит.
#   Величина вне колонки идёт теперь веткой «объявления нет» — той же, что и
#   несуществующий идентификатор.
#   ⚠️ ЧЕМ ИМЕННО ПОСТАВЛЕНО ЧИСЛО — СКАЗАНО ТОЧНО, ПОТОМУ ЧТО НАПРАВЛЕНИЕ
#   ПОКРАСНЕНИЯ ЗДЕСЬ ОБРАТНОЕ ПРИВЫЧНОМУ. Записи сняты в КРАСНОЙ фазе, когда оба
#   обработчика ещё несли `IdPath`, поэтому правило полноты предъявило две жалобы
#   в направлении «замер нашёл, перечень молчит», дословно:
#   `НАЙДЕН ЗАМЕРОМ, НО НЕ ОБЪЯВЛЕН: app/pages/ads.py::POST /ads/{ad_id}/delete →
#   адрес ad_id (псевдоним IdPath)` и такая же строка для `/edit`. Правило ЧИСЛА
#   на том прогоне было ЗЕЛЕНО и краснеть не могло: перечень и число сдвинуты
#   ОДНИМ движением, и `len()` совпал с объявленным сразу. Значение `14`
#   подтверждено ЗАМЕРОМ после перевода — на зелёном прогоне обе разности
#   «измеренные ↔ объявленные» пусты; выдавать его за поставленное покрасневшим
#   правилом числа значило бы приписать прогону то, чего он не печатал.
#   ⚠️ ОСТАЛОСЬ ЧЕТЫРНАДЦАТЬ, И ЭТО НЕ КОНЕЦ РАБОТЫ: D-07 объявил объёмом ВЕСЬ
#   реестр, а `LIFTING_CONDITION_VALIDATION_REFUSAL` по-прежнему верен для тех,
#   кого снимут следующие планы фазы (`admin` ×6, `account_groups` ×4,
#   `accounts` ×3, `history` ×1).
#
#   14 → 8, Фаза 11, план 11-11, задача 2: ШЕСТЬ входов модуля
#   АДМИНИСТРИРОВАНИЯ сняты РАБОТОЙ (D-07) — адрес `account_id` перезапуска
#   воркера и снятия задачи, адрес `user_id` тумблера бесплатного доступа, входа
#   под пользователем, тумблера блокировки и удаления. Все шесть обработчиков
#   перешли на `PostIdPath`; первое использование параметра в каждом — аргумент
#   `id_in_column`, стоящий ПОСЛЕ сверки источника и ДО первой выборки, и
#   `_framework_bounded_post_inputs` их больше не видит. Величина вне колонки
#   идёт веткой «записи нет» своего обработчика: «пользователя нет» у четырёх
#   пользовательских (переход на `/admin/users`), «аккаунт неизвестен» у
#   перезапуска (`/admin/workers`) и у снятия задачи
#   (`/admin/queue?result=unknown_account` — адрес этой ветки переводит план
#   11-14). Поведение наблюдается строками матрицы
#   `tests/test_pages/test_identifier_bounds.py` (поле `outside`).
#   ⚠️ ЧИСЛО ПОСТАВЛЕНО ПРОГОНОМ ПОКРАСНЕВШЕГО ПРАВИЛА, И НАПРАВЛЕНИЕ
#   ПОКРАСНЕНИЯ — ПРИВЫЧНОЕ, в отличие от строки выше: обработчики переведены
#   ПЕРВЫМИ, при нетронутом перечне, и правило полноты
#   `test_every_framework_bounded_input_is_declared_as_a_divergence` предъявило
#   шесть жалоб дословно — «ОБЪЯВЛЕН, НО ЗАМЕРОМ НЕ НАЙДЕН:
#   app/pages/admin.py::POST /queue/{account_id}/drop → адрес account_id» и
#   такие же для `/users/{user_id}/block`, `/delete`, `/impersonate`,
#   `/unlimited` и `/workers/{account_id}/restart`. Записи сняты по этим ключам,
#   и правило числа на перечне без них, но при прежнем числе, предъявило
#   дословно «расхождений формы отказа валидации стало 8, а объявлено 14» — до
#   сдвига числа.
#   ⚠️ ОСТАЛОСЬ ВОСЕМЬ (`account_groups` ×4, `accounts` ×3, `history` ×1), и
#   `LIFTING_CONDITION_VALIDATION_REFUSAL` верен для них без правки.
#
#   8 → 5, Фаза 11, план 11-17, задача 3: ТРИ входа модуля АККАУНТОВ сняты
#   РАБОТОЙ (D-07) — адрес `account_id` удаления аккаунта, повторной
#   синхронизации и синхронизации групп. Все три обработчика перешли на
#   `PostIdPath`; первое использование параметра в каждом — аргумент
#   `id_in_column`: у удаления ПОСЛЕ сверки источника (она идентификатора не
#   читает), у синхронизации групп ДО занятия внутрипроцессной заявки, у всех —
#   до первой выборки. Величина вне колонки идёт веткой «аккаунта нет» — переход
#   на `/accounts`, тот же, что у несуществующего либо чужого аккаунта.
#   Поведение наблюдается строками матрицы
#   `tests/test_pages/test_identifier_bounds.py` (поле `outside`) и случаем пар
#   «повторная синхронизация — идентификатор вне колонки».
#   ⚠️ ЧИСЛО ПОСТАВЛЕНО ПРОГОНОМ ПОКРАСНЕВШЕГО ПРАВИЛА, направление привычное:
#   обработчики переведены ПЕРВЫМИ, при нетронутом перечне, и правило полноты
#   `test_every_framework_bounded_input_is_declared_as_a_divergence` предъявило
#   три жалобы дословно — «ОБЪЯВЛЕН, НО ЗАМЕРОМ НЕ НАЙДЕН:
#   app/pages/accounts.py::POST /accounts/{account_id}/delete → адрес
#   account_id», такую же для `/sync-groups` и третью (свёрнутую выводом) для
#   `/retry-sync`. Записи сняты по этим ключам, и правило числа на перечне без
#   них, но при прежнем числе, предъявило дословно «расхождений формы отказа
#   валидации стало 5, а объявлено 8» / `assert 5 == 8` — до сдвига числа.
#   ⚠️ ОСТАЛОСЬ ПЯТЬ (`account_groups` ×4, `history` ×1), и
#   `LIFTING_CONDITION_VALIDATION_REFUSAL` верен для них без правки.
#
#   5 → 0, Фаза 11, план 11-19, задача 2: ПОСЛЕДНИЕ ПЯТЬ входов сняты РАБОТОЙ
#   (D-07) — адрес `account_id` и `group_id` тумблера и удаления группы
#   аккаунта (`app/pages/account_groups.py`) и адрес `log_id` повтора отправки
#   (`app/pages/history.py`). Все три обработчика перешли на `PostIdPath`;
#   первое использование каждого идентификатора — аргумент `id_in_column`,
#   стоящий после сверки источника (у удаления и повтора; у тумблера её нет) и
#   ДО первой выборки. Величина вне колонки идёт веткой «нет» своего
#   обработчика: у тумблера и удаления — «тройной `WHERE` не нашёл строки» с
#   адресом, собранным из `account_id` пути (у удаления с живой выдачей —
#   фрагмент снятия из `group_id` пути), у повтора — «записи нет», переход на
#   `/history`. Неотличимость от несуществующей и чужой строки утверждена на
#   ОБОИХ транспортах целиком (статус, заголовок перехода, тело):
#   `tests/test_pages/test_account_groups.py` и
#   `tests/test_pages/test_history_retry.py`, `*_out_of_column_is_indistinguishable_*`.
#   ⚠️ ЧЕМ ПОСТАВЛЕНО ЧИСЛО — СКАЗАНО ТОЧНО. Обработчики и перечень сдвинуты в
#   рабочем дереве одним движением, поэтому оба покраснения сняты ОТДЕЛЬНЫМИ
#   прогонами на переведённом дереве, а не выведены: (1) помощник полноты,
#   поданный ПРЕЖНЕМУ перечню из пяти записей (исходник гейтов коммита
#   `705c782`), предъявил ровно пять жалоб «ОБЪЯВЛЕН, НО ЗАМЕРОМ НЕ НАЙДЕН» —
#   по два ключа `account_id`/`group_id` у `/delete` и `/toggle` и ключ
#   `/history/{log_id}/retry → адрес log_id`; (2) правило числа на пустом
#   перечне при прежнем объявленном `5` предъявило дословно `assert 0 == 5`.
#
#   ⚠️ СВОДНАЯ ЛЕТОПИСЬ ФАЗЫ 11: 23 → 16 (11-02, `schedules`) → 14 (11-06,
#   `ads`) → 8 (11-11, `admin`) → 5 (11-17, `accounts`) → 0 (11-19,
#   `account_groups` и `history`). Расхождение формы отказа окна 51 снято
#   РАБОТОЙ; именованное изъятие из D-01 не чеканилось ни одним планом, и
#   вопрос владельцу о законности расхождения ПОТЕРЯЛ ПРЕДМЕТ.
#
#   ⚠️ ЧИСЛО НОЛЬ САМО ПО СЕБЕ ВАКУУМНО, И ЭТО НАЗВАНО ЗДЕСЬ. «Длина пустого
#   перечня равна нулю» истинно при любом состоянии дерева; содержательно оно
#   ТОЛЬКО вместе с правилом пустоты `test_no_page_post_input_keeps_a_framework_bound`
#   (обход сличён с независимым) и его синтетическим контролем
#   `test_control_a_synthetic_bounded_input_reddens_the_emptiness_rule`.
VALIDATION_REFUSAL_DIVERGENCES_DECLARED = 0


def _framework_bound_scan(
    sources: dict[str, str],
) -> tuple[dict[str, str], set[str]]:
    """Входы POST-обработчиков, чья граница величины стои́т НА УРОВНЕ ФРЕЙМВОРКА.

    Возвращается отображение «ВХОД → ПСЕВДОНИМ (либо `inline`)». Ключ склеен из
    модуля, маршрута, способа передачи и имени параметра: два разных параметра
    одного маршрута — ДВА РАЗНЫХ ВХОДА, и склеивание их в один есть ровно та
    ошибка счёта, которую этот перечень заводился исправить.

    ⚠️ ПРЕДМЕТ ЗАМЕРА — POST-ОБРАБОТЧИКИ, И ГРАНИЦА ОХВАТА НАЗВАНА, А НЕ
    ПОДРАЗУМЕВАЕТСЯ. Обход берёт объявления `Path(...)` и `Form(...)`,
    несущие `ge=` либо `le=`, — в обеих формах записи: через псевдоним
    (`Annotated[int, Form(ge=1, le=ID_MAX)]`, вынесенный в модуль) и ВСТРОЕННУЮ,
    чтобы будущий обработчик, вписавший границу прямо в сигнатуру, попал в
    охват сам, а не ждал, пока о нём вспомнят.
    Постраничные `Query(offset=..., limit=...)` в охват НЕ входят по двум
    названным основаниям: они стоят на GET-маршрутах, а предмет расхождения —
    контракт формы ответа POST-обработчика (G-2); и величина порции не есть
    ИДЕНТИФИКАТОР, отказ по ней ничего не говорит о владении строкой.

    ⚠️ ВТОРОЙ ВОЗВРАТ — МНОЖЕСТВО ОБОЙДЁННЫХ ОБРАБОТЧИКОВ (`модуль::функция`,
    план 11-19). Пустой реестр окна 51 утверждает «границ фреймворка нет», и
    это утверждение неотличимо от «замер ничего не обошёл», пока обход не
    предъявлен. Множество сличается с независимым обходом `_post_handlers`.
    """
    bounders = {"Path", "Form"}

    def bounded_call(node: ast.AST) -> str | None:
        if not isinstance(node, ast.Call):
            return None
        func = node.func
        name = (
            func.id
            if isinstance(func, ast.Name)
            else func.attr
            if isinstance(func, ast.Attribute)
            else None
        )
        if name not in bounders:
            return None
        keywords = {keyword.arg for keyword in node.keywords}
        return name if ("le" in keywords or "ge" in keywords) else None

    def bounded_annotation(annotation: ast.AST | None) -> str | None:
        if not isinstance(annotation, ast.Subscript):
            return None
        if not (
            isinstance(annotation.value, ast.Name)
            and annotation.value.id == "Annotated"
        ):
            return None
        parts = (
            annotation.slice.elts
            if isinstance(annotation.slice, ast.Tuple)
            else [annotation.slice]
        )
        for part in parts:
            found = bounded_call(part)
            if found:
                return found
        return None

    inputs: dict[str, str] = {}
    visited: set[str] = set()

    # ⚠️ ПСЕВДОНИМЫ РАЗРЕШАЮТСЯ ПО ВСЕМУ ДЕРЕВУ `app/`, А НЕ ВНУТРИ ОДНОГО
    # МОДУЛЯ, И ЭТО ЗАМЕР, А НЕ РАСШИРЕНИЕ ОХВАТА. Охват ВХОДОВ не менялся: он
    # по-прежнему есть POST-обработчики поданных исходников. Менялось то, ГДЕ
    # разборщик ищет ОБЪЯВЛЕНИЕ псевдонима, которым вход ограничен.
    #
    # ОСНОВАНИЕ СНЯТО ПРОГОНОМ, А НЕ ВЫВЕДЕНО. Прежняя редакция собирала таблицу
    # псевдонимов ВНУТРИ модуля, и это было верно ровно до тех пор, пока
    # величина объявлялась в том же файле, где стояли её потребители. План 10-24
    # перенёс объявление в нейтральный модуль (`app/pages/identifiers.py`), три
    # псевдонима страничного модуля расписаний стали ИМЕНОВАННЫМИ ПСЕВДОНИМАМИ
    # общих, и замер по прежней редакции дал НОЛЬ входов при семи объявленных:
    # ограничение, приехавшее ВВОЗОМ, разборщик не видел вовсе.
    #
    # ЦЕНА ПРЕЖНЕЙ РЕДАКЦИИ НАЗВАНА ДВУМЯ СЛЕДСТВИЯМИ: (1) семь действующих
    # записей реестра стали бы жалобами «ОБЪЯВЛЕН, НО ЗАМЕРОМ НЕ НАЙДЕН», то
    # есть правило полноты покраснело бы на ВЕРНОМ дереве; (2) что хуже,
    # измеренная вселенная стала бы ПУСТОЙ, и в направлении «найден замером, но
    # не объявлен» правило зеленело бы вакуумом навсегда — любой будущий
    # обработчик, ограниченный общим псевдонимом, остался бы для него невидим.
    alias_sources = {**_app_sources(), **sources}
    trees = {module: _parse(module, text) for module, text in sources.items()}
    alias_trees = {
        module: trees.get(module) or _parse(module, text)
        for module, text in alias_sources.items()
    }

    def module_key(dotted: str) -> str:
        """Точечное имя модуля → ключ охвата (`app.pages.x` → `app/pages/x.py`)."""
        return dotted.replace(".", "/") + ".py"

    aliases_by_module: dict[str, dict[str, str]] = {}
    for module, tree in alias_trees.items():
        local: dict[str, str] = {}
        for node in ast.walk(tree):
            if not isinstance(node, ast.Assign):
                continue
            if len(node.targets) != 1 or not isinstance(node.targets[0], ast.Name):
                continue
            carrier = bounded_annotation(node.value)
            if carrier:
                local[node.targets[0].id] = carrier
        aliases_by_module[module] = local

    # НЕПОДВИЖНАЯ ТОЧКА, А НЕ ОДИН ПРОХОД: ввоз ввезённого имени — законная
    # цепочка (нейтральный модуль → страничный → соседний страничный), и один
    # проход разрешил бы её только при удачном порядке файлов.
    changed = True
    while changed:
        changed = False
        for module, tree in alias_trees.items():
            local = aliases_by_module[module]
            for node in ast.walk(tree):
                if isinstance(node, ast.ImportFrom) and node.module:
                    exported = aliases_by_module.get(module_key(node.module))
                    if not exported:
                        continue
                    for imported in node.names:
                        carrier = exported.get(imported.name)
                        name = imported.asname or imported.name
                        if carrier and local.get(name) != carrier:
                            local[name] = carrier
                            changed = True
                elif isinstance(node, ast.Assign):
                    if len(node.targets) != 1:
                        continue
                    target, value = node.targets[0], node.value
                    if not isinstance(target, ast.Name):
                        continue
                    if not isinstance(value, ast.Name):
                        continue
                    carrier = local.get(value.id)
                    if carrier and local.get(target.id) != carrier:
                        local[target.id] = carrier
                        changed = True

    for module, tree in trees.items():
        aliases = aliases_by_module[module]

        for node in ast.walk(tree):
            if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue

            routes = [
                decorator.args[0].value
                for decorator in node.decorator_list
                if _declares_post(decorator)
                and decorator.args
                and isinstance(decorator.args[0], ast.Constant)
            ]
            if not routes:
                continue
            visited.add(f"{module}::{node.name}")

            arguments = node.args
            positional = list(arguments.posonlyargs) + list(arguments.args)
            every = positional + list(arguments.kwonlyargs)

            defaults: dict[str, ast.AST] = {}
            for argument, default in zip(
                arguments.kwonlyargs, arguments.kw_defaults
            ):
                if default is not None:
                    defaults[argument.arg] = default
            if arguments.defaults:
                for argument, default in zip(
                    positional[len(positional) - len(arguments.defaults) :],
                    arguments.defaults,
                ):
                    defaults[argument.arg] = default

            for argument in every:
                carrier: str | None = None
                alias = "inline"

                annotation = argument.annotation
                if isinstance(annotation, ast.Name) and annotation.id in aliases:
                    carrier, alias = aliases[annotation.id], annotation.id
                elif annotation is not None:
                    carrier = bounded_annotation(annotation)
                if carrier is None and argument.arg in defaults:
                    carrier = bounded_call(defaults[argument.arg])

                if carrier is None:
                    continue

                how = "адрес" if carrier == "Path" else "форма"
                for route in routes:
                    inputs[f"{module}::POST {route} → {how} {argument.arg}"] = alias

    return inputs, visited


def _framework_bounded_post_inputs(sources: dict[str, str]) -> dict[str, str]:
    """Замер окна 51: «ВХОД → ПСЕВДОНИМ» — первый возврат `_framework_bound_scan`."""
    return _framework_bound_scan(sources)[0]


def _framework_bound_visited_handlers(sources: dict[str, str]) -> set[str]:
    """Обработчики, которые замер границ ОБОШЁЛ (`модуль::функция`)."""
    return _framework_bound_scan(sources)[1]


def _framework_bound_complaints(sources: dict[str, str]) -> list[str]:
    """Жалобы правила ПУСТОТЫ: по одной на вход с границей фреймворка.

    Разбор — тот же, что у замера реестра окна 51 (`_framework_bound_scan`), без
    второго разборщика: правило пустоты и правило полноты не могут разойтись в
    том, ЧТО считать границей. Жалоба называет вход поимённо — модуль, маршрут,
    способ передачи, имя параметра — и псевдоним, которым граница сделана.
    """
    return [
        f"ВХОД POST-ОБРАБОТЧИКА НЕСЁТ ГРАНИЦУ ФРЕЙМВОРКА: {entry} (псевдоним "
        f"{alias})"
        for entry, alias in sorted(_framework_bounded_post_inputs(sources).items())
    ]


def _validation_refusal_completeness_complaints(
    divergences: tuple[_ValidationRefusalDivergence, ...],
    sources: dict[str, str] | None = None,
) -> list[str]:
    """Жалобы правила ПОЛНОТЫ — на ПОДАННЫЙ перечень, а не на модульный.

    Перечень приходит параметром ровно затем, чтобы контроль зубов мог подать
    УКОРОЧЕННУЮ копию и увидеть, что правило её заметило. Приём взят у контроля
    перечня осей (`tests/test_pages/test_confirm_delete_transport.py`).
    """
    measured = _framework_bounded_post_inputs(
        _pages_sources() if sources is None else sources
    )
    declared = {divergence.entry: divergence.alias for divergence in divergences}

    complaints: list[str] = []
    for entry in sorted(set(measured) - set(declared)):
        complaints.append(
            f"НАЙДЕН ЗАМЕРОМ, НО НЕ ОБЪЯВЛЕН: {entry} (псевдоним "
            f"{measured[entry]})"
        )
    for entry in sorted(set(declared) - set(measured)):
        complaints.append(f"ОБЪЯВЛЕН, НО ЗАМЕРОМ НЕ НАЙДЕН: {entry}")
    for entry in sorted(set(declared) & set(measured)):
        if declared[entry] != measured[entry]:
            complaints.append(
                f"ПСЕВДОНИМ РАЗОШЁЛСЯ С ЗАМЕРОМ: {entry} объявлен как "
                f"{declared[entry]!r}, а измерен как {measured[entry]!r}"
            )
    return complaints


def _validation_refusal_rationale_complaints(
    divergences: tuple[_ValidationRefusalDivergence, ...],
) -> list[str]:
    """Жалобы правила ОБОСНОВАНИЙ — на ПОДАННЫЙ перечень.

    Перечень без обоснований есть список того, до чего не дошли руки, и
    отличить его от заявленного расхождения нельзя ничем, кроме этих трёх
    непустых полей.
    """
    complaints: list[str] = []

    for divergence in divergences:
        where = divergence.entry or "(запись без входа)"

        if not divergence.entry.strip():
            complaints.append(
                "запись расхождения не называет ВХОДА — обоснование, стоящее "
                "ни на чём, неотличимо от отсутствующего"
            )
        if not divergence.alias.strip():
            complaints.append(
                f"расхождение «{where}» не называет ПСЕВДОНИМА границы: "
                "читатель не найдёт места, которым расхождение сделано"
            )
        if not divergence.reason.strip():
            complaints.append(
                f"расхождение «{where}» объявлено БЕЗ ОБОСНОВАНИЯ — перечень "
                "без обоснований есть список того, до чего не дошли руки"
            )
        if not divergence.decision_state.strip():
            complaints.append(
                f"расхождение «{where}» не несёт СОСТОЯНИЯ РЕШЕНИЯ: молчащее "
                "состояние читается как решённое, а решения не было"
            )
        if not divergence.lifting_condition.strip():
            complaints.append(
                f"расхождение «{where}» не называет УСЛОВИЯ СНЯТИЯ — через "
                "фазу оно станет неотличимо от недоделки"
            )
        elif "Фаза 11" not in divergence.lifting_condition:
            complaints.append(
                f"расхождение «{where}» не называет ФАЗЫ-СНИМАТЕЛЯ. Фаза взята "
                "ИЗ РОАДМАПА (Фаза 11, критерий 3), а не назначена планом; "
                "условие снятия, потерявшее её имя, оставляет перечень без "
                "адресата"
            )
        if _REFUSAL_PRICE.split(":")[0] not in divergence.reason:
            complaints.append(
                f"обоснование расхождения «{where}» не называет ЦЕНЫ ДВУМЯ "
                "СЛЕДСТВИЯМИ: обоснование без цены превращает заявленное "
                "расхождение обратно в умолчание"
            )

    return complaints


_DECISION_REFERENCE = re.compile(r"\bD-\d{2}\b|\bокн[оа]\s+№?\s*\d+")


def _validation_refusal_authorship_complaints(
    divergences: tuple[_ValidationRefusalDivergence, ...],
) -> list[str]:
    """Жалобы правила АВТОРСТВА — на ПОДАННЫЙ перечень.

    Запись, объявившая себя РЕШЁННОЙ, обязана называть, ЧЕМ решена:
    идентификатором решения владельца по форме `D-NN` либо номером закрытого
    окна реестра.
    """
    complaints: list[str] = []

    for divergence in divergences:
        state = divergence.decision_state.strip()
        if not state or state == DECISION_WAITS_FOR_THE_OWNER:
            continue
        if not _DECISION_REFERENCE.search(state):
            complaints.append(
                f"расхождение «{divergence.entry}» объявлено РЕШЁННЫМ "
                f"({state!r}), но не называет, ЧЕМ решено"
            )

    return complaints


def test_the_number_of_validation_refusal_divergences_is_declared():
    """Число расхождений формы отказа равно ОБЪЯВЛЕННОМУ.

    ⚠️ ЧТО ЗНАЧИТ КАЖДОЕ ИЗ ДВУХ НАПРАВЛЕНИЙ РАСХОЖДЕНИЯ, И ПОЧЕМУ ОБА ПЛОХИ.
    Молча ВЫРОСШИЙ перечень означает принятое-но-неназванное расхождение: вход
    добавили, форму отказа ему выбрал фреймворк, и запись об этом появилась
    задним числом — то есть ровно то молчание, которое ревизия назвала худшим
    из трёх исходов. Молча ПОХУДЕВШИЙ означает снятое расхождение при НЕТРОНУТОЙ
    границе: код остался прежним, а запись объявила инвариант исполненным.
    """
    assert (
        len(VALIDATION_REFUSAL_DIVERGENCES)
        == VALIDATION_REFUSAL_DIVERGENCES_DECLARED
    ), (
        f"расхождений формы отказа валидации стало "
        f"{len(VALIDATION_REFUSAL_DIVERGENCES)}, а объявлено "
        f"{VALIDATION_REFUSAL_DIVERGENCES_DECLARED}. Рост означает, что "
        "расхождение приняли, не назвав его решением; падение — что "
        "расхождение сняли, не тронув границы, то есть объявили инвариант "
        "исполненным при неизменившемся коде"
    )


def test_every_framework_bounded_input_is_declared_as_a_divergence():
    """ПОЛНОТА ПО ЗАМЕРУ: каждый вход с границей на уровне фреймворка объявлен.

    ⚠️ БЕЗ ЭТОГО ПРАВИЛА ЧИСЛО ВЫШЕ СЛИЧАЛО БЫ ДВЕ СТРОКИ ОДНОГО ФАЙЛА. Предмет
    даёт числу именно это правило: перечень стои́т на ЗАМЕРЕ страничного слоя, а
    не на памяти читателя и не на отчёте верификации. Вход, заведённый будущей
    фазой с границей на уровне фреймворка и здесь не названный, краснит прогон
    С ИМЕНЕМ — молча проехавший получил бы форму отказа от фреймворка, и
    следующий читатель принял бы молчание за исполненный D-01.
    """
    complaints = _validation_refusal_completeness_complaints(
        VALIDATION_REFUSAL_DIVERGENCES
    )

    assert not complaints, (
        "ПЕРЕЧЕНЬ РАСХОЖДЕНИЙ РАЗОШЁЛСЯ С ЗАМЕРОМ СТРАНИЧНОГО СЛОЯ:\n  "
        + "\n  ".join(complaints)
        + "\n\nВход, у которого граница величины идентификатора стои́т на уровне "
        "фреймворка, обязан быть либо переведён на границу внутри обработчика "
        "с ответом через слой ответа, либо ОБЪЯВЛЕН здесь расхождением — с "
        "ценой, условием снятия и состоянием решения. Ни тем ни другим он "
        "быть не может: молчаливое умолчание читается как исполненный D-01"
    )


def test_no_page_post_input_keeps_a_framework_bound():
    """ПРАВИЛО ПУСТОТЫ: ни один вход POST-обработчика страничного слоя не несёт
    границы фреймворка (Фаза 11, план 11-19, D-07).

    ⚠️ ЧЕМ ЭТО ПРАВИЛО ОТЛИЧАЕТСЯ ОТ ПРАВИЛА ПОЛНОТЫ ВЫШЕ. Полнота сличает замер с
    перечнем, и при пустом перечне она утверждает то же самое — но расхождение,
    объявленное записью, прошло бы её зелёным. Это правило не принимает записей:
    граница фреймворка на POST краснит прогон С ИМЕНЕМ, и выход один — перевести
    вход на POST-псевдоним с проверкой первым использованием.

    ⚠️ НЕ ВАКУУМНО, И ЭТО ПОКАЗАНО, А НЕ ОБЪЯВЛЕНО (память проекта «RED-гейт
    зеленеет вакуумом»). Пустые жалобы значат «границ нет» только вместе с двумя
    доказательствами: (1) синтетический вход с границей краснит тот же помощник
    поимённо — `test_control_a_synthetic_bounded_input_reddens_the_emptiness_rule`;
    (2) замер ОБОШЁЛ всю вселенную — множество обойдённых им обработчиков
    непусто и совпадает с НЕЗАВИСИМЫМ обходом `_post_handlers` (разборщик гейта
    G-1), а число — с объявленным `POST_HANDLERS`. Замер, ослепший на модуле,
    уронил бы второе утверждение, а не прошёл бы первое молча.
    """
    pages = _pages_sources()
    visited = _framework_bound_visited_handlers(pages)
    independent = set(_post_handlers(pages))

    assert visited, (
        "ЗАМЕР ГРАНИЦ НЕ ОБОШЁЛ НИ ОДНОГО POST-ОБРАБОТЧИКА страничного слоя — "
        "пустые жалобы ниже ничего не значили бы"
    )
    assert visited == independent, (
        "ЗАМЕР ГРАНИЦ ОБОШЁЛ НЕ ТУ ВСЕЛЕННУЮ, ЧТО НЕЗАВИСИМЫЙ ОБХОД. Не обойдены: "
        f"{sorted(independent - visited)}; лишние: {sorted(visited - independent)}"
    )
    assert len(visited) == POST_HANDLERS, (
        f"замер границ обошёл {len(visited)} POST-обработчиков, а объявлено "
        f"{POST_HANDLERS}"
    )

    complaints = _framework_bound_complaints(pages)
    assert not complaints, (
        "ГРАНИЦА ВЕЛИЧИНЫ ОСТАЛАСЬ НА УРОВНЕ ФРЕЙМВОРКА:\n  "
        + "\n  ".join(complaints)
        + "\n\nНа POST форму отказа выбирает класс действия (D-01), а не "
        "фреймворк: объявите вход POST-псевдонимом (`PostIdPath`/`PostIdForm`, "
        "`app/pages/identifiers.py`) и сделайте первым его использованием "
        "аргумент `id_in_column`, стоящий до первой выборки; величина вне колонки "
        "идёт веткой «записи нет» обработчика (D-07)"
    )


def test_every_validation_refusal_divergence_carries_a_non_empty_rationale():
    """У КАЖДОГО расхождения непусты все пять полей, и цена названа.

    ⚠️ ПОЧЕМУ ПРОВЕРЯЕТСЯ ИМЕННО НЕПУСТОТА, А НЕ КРАСОТА ТЕКСТА. Перечень,
    записи которого молчат об основании, ничем не отличается от списка «сюда не
    дошли руки»: обе формы зелены, и обе оставляют следующего читателя без
    знания, ПРИНЯТО расхождение или ПРОСМОТРЕНО.

    ФАЗА-СНИМАТЕЛЬ ЗДЕСЬ ТРЕБУЕТСЯ ИМЕНЕМ, ПОТОМУ ЧТО ОНА ЕСТЬ В РОАДМАПЕ.
    Фаза 11 названа критерием 3 роадмапа дословно, и потому правило вправе
    требовать её имени. Требуй оно имени фазы, которой в роадмапе нет, — план
    сочинил бы назначение, а сочинённое назначение хуже отсутствующего: за ним
    никто не придёт, и никто об этом не узнает.
    """
    complaints = _validation_refusal_rationale_complaints(
        VALIDATION_REFUSAL_DIVERGENCES
    )

    assert not complaints, (
        "ЗАПИСЬ РАСХОЖДЕНИЯ ОКАЗАЛАСЬ НЕПОЛНОЙ:\n  " + "\n  ".join(complaints)
    )


def test_no_divergence_claims_a_decision_the_owner_did_not_make():
    """Запись, объявившая себя РЕШЁННОЙ, обязана назвать, ЧЕМ решена.

    ⚠️ ЭТО ПРАВИЛО СТЕРЕЖЁТ НЕ КОД, А ГРАНИЦУ ПОЛНОМОЧИЙ, и оно единственное,
    чем следующий круг не превратит «ЖДЁТ ВЛАДЕЛЬЦА» в «решено» правкой одной
    строки.

    D-01 есть ЗАПЕРТОЕ решение владельца: «форма ответа выбирается ПО КЛАССУ
    ДЕЙСТВИЯ». Единственный прецедент изъятия из него — D-08 — назван в записи
    решений фазы «ИМЕНОВАННЫМ ИЗЪЯТИЕМ ИЗ D-01» и записан ВЛАДЕЛЬЦЕМ на этапе
    обсуждения, с измеренным основанием. Изъятие, дочеканенное планом либо
    исполнителем, есть ПРИСВОЕНИЕ ЧУЖОГО АВТОРСТВА, и следующий читатель принял
    бы его за решение владельца, потому что отличить одно от другого в записи
    было бы нечем.

    Поэтому «решено» принимается ровно двумя формами: идентификатором решения
    владельца (`D-NN`) либо номером ЗАКРЫТОГО окна реестра. Ответ владельца,
    пришедший до исполнения, этой формой записывается и правилом принимается;
    сочинить его за владельца правило не даёт.
    """
    complaints = _validation_refusal_authorship_complaints(
        VALIDATION_REFUSAL_DIVERGENCES
    )

    assert not complaints, (
        "РЕШЕНИЕ ОБЪЯВЛЕНО БЕЗ ССЫЛКИ НА ТОГО, КТО ЕГО ПРИНЯЛ:\n  "
        + "\n  ".join(complaints)
        + f"\n\nСостояние, отличное от {DECISION_WAITS_FOR_THE_OWNER!r}, "
        "обязано называть идентификатор решения владельца по форме `D-NN` "
        "либо номер закрытого окна реестра `.planning/WINDOWS.md`. Изъятие из "
        "запертого D-01 чеканит ВЛАДЕЛЕЦ — прецедент D-08 записан им самим на "
        "этапе обсуждения"
    )


# =============================================================================
# КОНТРОЛИ РЕЕСТРА ОКНА 51 — НА СИНТЕТИЧЕСКИХ ВХОДАХ И ЗАПИСЯХ
#
# ⚠️ ПОКОЛЕНИЕ КОНТРОЛЕЙ (Фаза 11, план 11-19, задача 1; идиома D-30/D-32 —
# прежние редакции не стёрты из летописи, а названы здесь). Контроли полноты
# (укороченный перечень; все записи одного модуля — прежде шесть записей
# административного модуля, после плана 11-11 самый населённый модуль) и
# контроль обоснований ОПИРАЛИСЬ НА БОЕВЫЕ ЗАПИСИ реестра: роняли первую запись,
# записи модуля, опустошали обоснование первой. План 11-19 переводит их на
# СИНТЕТИЧЕСКИЕ входы и записи, потому что реестр пустеет задачей 2: на пустом
# перечне уронить нечего, и контроль в прежней редакции либо упал бы на
# предусловии, либо — хуже — зазеленел бы вакуумом (память проекта «RED-гейт
# зеленеет вакуумом»).
#
# ⚠️ КАЖДЫЙ КОНТРОЛЬ СНАЧАЛА ПРОГОНЯЕТСЯ НА ЗАВЕДОМО ПРАВИЛЬНОЙ СИНТЕТИЧЕСКОЙ
# ПАРЕ, и она обязана молчать. Без этой половины контроль доказывал бы только
# «правило умеет краснеть», а правило, краснеющее всегда, прошло бы его тоже.
#
# ⚠️ СИНТЕТИЧЕСКИЙ МОДУЛЬ ПОДАЁТСЯ ОДИН, БЕЗ БОЕВОГО ДЕРЕВА. Боевое дерево
# читается разборщиком ТОЛЬКО ради разрешения ввезённых псевдонимов
# (`app/pages/identifiers.py`); ни один вход боевого обработчика в замер
# контроля не попадает, и потому ни одна жалоба не может прийти от живой
# записи.
# =============================================================================

SYNTHETIC_BOUND_MODULE = "app/pages/synthetic_window_51.py"
SYNTHETIC_SECOND_MODULE = "app/pages/synthetic_window_51_second.py"
SYNTHETIC_ROUTE = "/synthetic/{thing_id}/act"
SYNTHETIC_PAIR_ROUTE = "/synthetic/{owner_id}/things/{thing_id}/act"


def _synthetic_post_module(route: str, parameters: str) -> str:
    """Текст синтетического страничного модуля с ОДНИМ POST-обработчиком.

    Ввоз псевдонимов идёт тем же путём, что у боевых модулей, — из
    `app.pages.identifiers`: граница, приехавшая ввозом, есть ровно тот случай,
    на котором разборщик уже однажды слеп (план 10-24).
    """
    return (
        "from typing import Annotated\n"
        "\n"
        "from fastapi import APIRouter, Path, Request\n"
        "\n"
        "from app.pages.identifiers import IdPath, PostIdPath\n"
        "\n"
        "router = APIRouter()\n"
        "\n"
        "\n"
        f'@router.post("{route}")\n'
        f"async def synthetic_act(request: Request, {parameters}):\n"
        "    return None\n"
    )


def _synthetic_entry(module: str, route: str, parameter: str) -> str:
    """Ключ входа ровно в той форме, в которой его склеивает замер."""
    return f"{module}::POST {route} → адрес {parameter}"


def _synthetic_divergence(
    entry: str, alias: str, **fields: str
) -> _ValidationRefusalDivergence:
    """ЗАВЕДОМО ПРАВИЛЬНАЯ синтетическая запись — поля подменяются по имени."""
    values = {
        "entry": entry,
        "alias": alias,
        "reason": _REFUSAL_PRICE + ". СИНТЕТИЧЕСКАЯ ЗАПИСЬ КОНТРОЛЯ ЗУБОВ",
        "lifting_condition": LIFTING_CONDITION_VALIDATION_REFUSAL,
        "decision_state": DECISION_WAITS_FOR_THE_OWNER,
    }
    values.update(fields)
    return _ValidationRefusalDivergence(**values)


def _assert_the_synthetic_module_was_walked(sources: dict[str, str]) -> None:
    """ПОДМЕНА ПРИЗЕМЛИЛАСЬ, И ЗАМЕР ЕЁ ОБОШЁЛ — иначе молчание ничего не значит.

    Множество обойдённых замером обработчиков сличается с НЕЗАВИСИМЫМ обходом
    `_post_handlers` (разборщик гейта G-1): замер, ослепший на синтетическом
    модуле, дал бы пустые жалобы по построению, и контроль «жалоб нет» доказывал
    бы промах, а не правило.
    """
    independent = set(_post_handlers(sources))
    visited = _framework_bound_visited_handlers(sources)
    assert independent, (
        "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ: независимый обход не нашёл в синтетическом "
        "модуле ни одного POST-обработчика"
    )
    assert visited == independent, (
        "ЗАМЕР ГРАНИЦ ОБОШЁЛ НЕ ТЕ ОБРАБОТЧИКИ, ЧТО НЕЗАВИСИМЫЙ ОБХОД: "
        f"замер {sorted(visited)}, независимый обход {sorted(independent)}"
    )


def test_control_a_synthetic_bounded_input_reddens_the_emptiness_rule(tmp_path):
    """ЗУБЫ ПРАВИЛА ПУСТОТЫ — СИНТЕТИЧЕСКИМ ВХОДОМ С ГРАНИЦЕЙ, А НЕ ПРОЗОЙ.

    ⚠️ ПРАВИЛО ПУСТОТЫ ЗЕЛЕНО НА ЛЮБОМ ЗАМЕРЕ, ВОЗВРАЩАЮЩЕМ ПУСТО. Этот контроль —
    единственное, что отличает «на страничном слое не осталось границ
    фреймворка» от «замер перестал их видеть». Он подаёт помощнику
    `_framework_bound_complaints` синтетический модуль в ДВУХ записях границы —
    встроенной (`Path(ge=1)`) и ввезённой (GET-псевдоним `IdPath`, поставленный
    на POST, — ровно та ошибка, которую следующий обработчик сделает первой), —
    и показывает, что вход назван ПОИМЁННО: модуль, маршрут, имя параметра,
    псевдоним. Тот же обработчик на `PostIdPath` жалоб не даёт.
    """
    entry = _synthetic_entry(SYNTHETIC_BOUND_MODULE, SYNTHETIC_ROUTE, "thing_id")

    for parameters, alias in (
        ("thing_id: Annotated[int, Path(ge=1)]", "inline"),
        ("thing_id: IdPath", "IdPath"),
    ):
        sources = _sources_with(
            tmp_path,
            {},
            SYNTHETIC_BOUND_MODULE,
            _synthetic_post_module(SYNTHETIC_ROUTE, parameters),
        )
        _assert_the_synthetic_module_was_walked(sources)

        complaints = _framework_bound_complaints(sources)

        assert len(complaints) == 1, (
            f"синтетический вход с границей фреймворка ({parameters}) дал "
            f"{len(complaints)} жалоб вместо одной — правило пустоты его не "
            f"видит, и следующая граница фреймворка на POST проехала бы молча. "
            f"Сказано было: {complaints}"
        )
        assert entry in complaints[0] and f"псевдоним {alias}" in complaints[0], (
            f"правило пустоты покраснело, но НЕ НАЗВАЛО вход «{entry}» с "
            f"псевдонимом {alias!r} поимённо. Сказано было: {complaints}"
        )

    unbounded = _sources_with(
        tmp_path,
        {},
        SYNTHETIC_BOUND_MODULE,
        _synthetic_post_module(SYNTHETIC_ROUTE, "thing_id: PostIdPath"),
    )
    _assert_the_synthetic_module_was_walked(unbounded)
    assert _framework_bound_complaints(unbounded) == [], (
        "синтетический вход БЕЗ границы фреймворка (`PostIdPath`) дал жалобу — "
        "правило пустоты краснеет на правильном обработчике и потому не "
        "отличает нарушение от нормы"
    )


def test_control_a_shortened_exception_list_reddens_the_completeness_rule(tmp_path):
    """ЗУБЫ ПРАВИЛА ПОЛНОТЫ — УКОРОЧЕННЫМ СИНТЕТИЧЕСКИМ ПЕРЕЧНЕМ, В ОБЕ СТОРОНЫ.

    ⚠️ ПОКОЛЕНИЕ (план 11-19): контроль опирался на боевые записи реестра —
    ронял первую из них; план 11-19 переводит его на синтетические, потому что
    реестр пустеет задачей 2. Предмет прежний: правило читает ПОДАННЫЙ перечень
    и называет расхождение поимённо — и в направлении «замер нашёл, перечень
    молчит», и в обратном «перечень называет, замер не находит».
    """
    entry = _synthetic_entry(SYNTHETIC_BOUND_MODULE, SYNTHETIC_ROUTE, "thing_id")
    bounded = _sources_with(
        tmp_path,
        {},
        SYNTHETIC_BOUND_MODULE,
        _synthetic_post_module(SYNTHETIC_ROUTE, "thing_id: IdPath"),
    )
    _assert_the_synthetic_module_was_walked(bounded)
    record = _synthetic_divergence(entry, "IdPath")

    assert _validation_refusal_completeness_complaints((record,), bounded) == [], (
        "АНТИВАКУУМ НЕ ПРОШЁЛ: заведомо правильная пара «вход с границей + его "
        "запись» дала жалобы — правило краснеет на верном перечне"
    )

    missing = _validation_refusal_completeness_complaints((), bounded)
    assert missing and any(
        "НАЙДЕН ЗАМЕРОМ, НО НЕ ОБЪЯВЛЕН" in complaint and entry in complaint
        for complaint in missing
    ), (
        f"перечень БЕЗ записи «{entry}» не вызвал поимённой жалобы — значит "
        f"правило полноты читает НЕ поданный перечень. Сказано было: {missing}"
    )

    unbounded = _sources_with(
        tmp_path,
        {},
        SYNTHETIC_BOUND_MODULE,
        _synthetic_post_module(SYNTHETIC_ROUTE, "thing_id: PostIdPath"),
    )
    stale = _validation_refusal_completeness_complaints((record,), unbounded)
    assert stale and any(
        "ОБЪЯВЛЕН, НО ЗАМЕРОМ НЕ НАЙДЕН" in complaint and entry in complaint
        for complaint in stale
    ), (
        f"запись «{entry}» при снятой границе не вызвала поимённой жалобы — "
        "расхождение, снятое работой, осталось бы в перечне мёртвой записью. "
        f"Сказано было: {stale}"
    )


def test_control_dropping_a_whole_module_reddens_the_completeness_rule(tmp_path):
    """ЗУБЫ ПРАВИЛА ПОЛНОТЫ НА ВСЕХ ЗАПИСЯХ ОДНОГО МОДУЛЯ, А НЕ НА ОДНОЙ.

    ⚠️ ПОКОЛЕНИЕ (план 11-19): контроль опирался на боевые записи реестра —
    сначала на шесть записей административного модуля (план 10-29), затем на
    самый населённый модуль (план 11-11); план 11-19 переводит его на
    синтетические, потому что реестр пустеет задачей 2. Предмет прежний:
    правило, видящее один модуль и слепое к другому, прошло бы контроль одной
    записи молча. Синтетических модулей ДВА; у первого два входа одного
    маршрута (два параметра — два входа), у второго один. Сняты записи первого —
    названы оба его входа, и ни одной жалобы на второй.
    """
    first_owner = _synthetic_entry(
        SYNTHETIC_BOUND_MODULE, SYNTHETIC_PAIR_ROUTE, "owner_id"
    )
    first_thing = _synthetic_entry(
        SYNTHETIC_BOUND_MODULE, SYNTHETIC_PAIR_ROUTE, "thing_id"
    )
    second = _synthetic_entry(SYNTHETIC_SECOND_MODULE, SYNTHETIC_ROUTE, "thing_id")

    sources = _sources_with(
        tmp_path,
        _sources_with(
            tmp_path,
            {},
            SYNTHETIC_BOUND_MODULE,
            _synthetic_post_module(
                SYNTHETIC_PAIR_ROUTE, "owner_id: IdPath, thing_id: IdPath"
            ),
        ),
        SYNTHETIC_SECOND_MODULE,
        _synthetic_post_module(SYNTHETIC_ROUTE, "thing_id: Annotated[int, Path(le=9)]"),
    )
    _assert_the_synthetic_module_was_walked(sources)
    assert len(_framework_bound_visited_handlers(sources)) == 2

    full = (
        _synthetic_divergence(first_owner, "IdPath"),
        _synthetic_divergence(first_thing, "IdPath"),
        _synthetic_divergence(second, "inline"),
    )
    assert _validation_refusal_completeness_complaints(full, sources) == [], (
        "АНТИВАКУУМ НЕ ПРОШЁЛ: полный синтетический перечень двух модулей дал "
        "жалобы — правило краснеет на верном перечне"
    )

    shortened = tuple(
        divergence
        for divergence in full
        if not divergence.entry.startswith(SYNTHETIC_BOUND_MODULE + "::")
    )
    complaints = _validation_refusal_completeness_complaints(shortened, sources)

    unnamed = [
        entry
        for entry in (first_owner, first_thing)
        if not any(entry in complaint for complaint in complaints)
    ]
    assert not unnamed, (
        "правило полноты НЕ НАЗВАЛО поимённо все входы снятого модуля. Не "
        f"названы: {unnamed}. Сказано было: {complaints}"
    )
    assert not any(second in complaint for complaint in complaints), (
        f"правило полноты пожаловалось на вход второго модуля «{second}», чья "
        f"запись на месте. Сказано было: {complaints}"
    )


def test_control_an_empty_rationale_reddens_the_rationale_rule():
    """ЗУБЫ ПРАВИЛА ОБОСНОВАНИЙ — ОПУСТОШЁННЫМ ПОЛЕМ СИНТЕТИЧЕСКОЙ ЗАПИСИ.

    ⚠️ ПОКОЛЕНИЕ (план 11-19): контроль опирался на боевые записи реестра —
    опустошал обоснование первой из них; план 11-19 переводит его на
    синтетические, потому что реестр пустеет задачей 2.
    """
    entry = _synthetic_entry(SYNTHETIC_BOUND_MODULE, SYNTHETIC_ROUTE, "thing_id")
    sound = _synthetic_divergence(entry, "IdPath")

    assert _validation_refusal_rationale_complaints((sound,)) == [], (
        "АНТИВАКУУМ НЕ ПРОШЁЛ: заведомо правильная синтетическая запись дала "
        "жалобы правила обоснований"
    )

    complaints = _validation_refusal_rationale_complaints(
        (_synthetic_divergence(entry, "IdPath", reason="   "),)
    )
    assert any(
        entry in complaint and "БЕЗ ОБОСНОВАНИЯ" in complaint
        for complaint in complaints
    ), (
        f"запись «{entry}» с ПУСТЫМ обоснованием не названа поимённо — список "
        "того, до чего не дошли руки, засчитался бы заявленным расхождением. "
        f"Сказано было: {complaints}"
    )


def test_control_a_self_minted_decision_reddens_the_divergence_authorship_rule():
    """ЗУБЫ ПРАВИЛА АВТОРСТВА — СИНТЕТИЧЕСКОЙ ЗАПИСЬЮ, «РЕШЁННОЙ» БЕЗ ССЫЛКИ.

    Заведён планом 11-19 на синтетической записи: пока реестр нёс только
    записи в состоянии ожидания, правило авторства пропускало их все по
    построению, и его зубы не были показаны ничем.
    """
    entry = _synthetic_entry(SYNTHETIC_BOUND_MODULE, SYNTHETIC_ROUTE, "thing_id")

    for state in (
        DECISION_WAITS_FOR_THE_OWNER,
        DECISION_OWNER_D08,
        "решено: окно 51 закрыто работой",
    ):
        assert _validation_refusal_authorship_complaints(
            (_synthetic_divergence(entry, "IdPath", decision_state=state),)
        ) == [], (
            f"АНТИВАКУУМ НЕ ПРОШЁЛ: состояние {state!r} законной формы дало "
            "жалобу правила авторства"
        )

    complaints = _validation_refusal_authorship_complaints(
        (
            _synthetic_divergence(
                entry, "IdPath", decision_state="решено, форма законна"
            ),
        )
    )
    assert len(complaints) == 1 and entry in complaints[0], (
        f"запись «{entry}», объявившая себя решённой без `D-NN` и без номера "
        f"окна, не названа поимённо. Сказано было: {complaints}"
    )


# =============================================================================
# СОБСТВЕННЫЕ ВЫХОДЫ ПЕРЕВЕДЁННЫХ ОБРАБОТЧИКОВ — НАХОДКА `WR-04` ПЯТОГО КРУГА
#
# ⚠️ ГЕЙТ `G-2` СТЕРЕЖЁТ ОДНУ РАЗНОВИДНОСТЬ ВТОРОГО РЕШЕНИЯ О ФОРМЕ ОТВЕТА —
# РЕДИРЕКТ, — И ЭТОГО ОКАЗАЛОСЬ МАЛО. Шапка слоя ответа
# (`app/pages/htmx.py`) открывается словами «единственное место, где приложение
# решает, ЧЕМ отвечать», и `G-2` существует ровно затем, чтобы это оставалось
# верным у переведённых обработчиков. Его разборщик `_builds_own_redirect`
# узнаёт `RedirectResponse(...)` и статус 302 в обеих формах записи — и НИЧЕГО
# больше. Четвёртая партия дописала в переведённые обработчики сверку источника
# запроса, отвечающую СОБСТВЕННОЙ сборкой `Response(status_code=403)`: это
# второе, независимое решение о форме ответа, и гейт, построенный ради
# единственности, к нему слеп.
#
# ⚠️ УТВЕРЖДЕНИЕ О ЕДИНСТВЕННОСТИ, СТОЯЩЕЕ РЯДОМ С ВЫХОДАМИ, ЕГО ОБХОДЯЩИМИ,
# СТОИТ ДОРОЖЕ ОТСУТСТВИЯ УТВЕРЖДЕНИЯ: читатель верит ему и не ищет. Ровно то
# же ревизия четвёртого круга назвала худшим из трёх исходов у молчаливого
# умолчания — «оно читается как исполненный инвариант».
#
# ⚠️ ИСХОД (2) РЕВИЗИИ — ПРОВЕСТИ ОТКАЗ ПО ПРОИСХОЖДЕНИЮ ЧЕРЕЗ СЛОЙ ОТВЕТА —
# ОТВЕРГНУТ, И ОСНОВАНИЕ ЕСТЬ ТРИ СЛЕДСТВИЯ, НИ ОДНО ИЗ КОТОРЫХ НЕ ЕСТЬ ОЦЕНКА
# ТРУДА. Читатель обязан узнать это ЗДЕСЬ, не выходя из файла:
#   (а) перевод есть решение о ФОРМЕ ОТВЕТА, а форма ответа заперта решением
#       владельца D-01 («форма ответа выбирается ПО КЛАССУ ДЕЙСТВИЯ»);
#       единственный прецедент изъятия, D-08, назван «ИМЕНОВАННЫМ ИЗЪЯТИЕМ ИЗ
#       D-01» и записан ВЛАДЕЛЬЦЕМ на этапе обсуждения. Чеканить изъятие плану
#       и исполнителю запрещено — прецедент окна 51, где четвёртая партия
#       сделала расхождение видимым и решения не приняла;
#   (б) перевод потребовал бы НОВОГО кода реестра уведомлений («источник
#       запроса не подтверждён»), а новых кодов фаза не заводит по D-03 с
#       основанием, записанным вехой в Out of Scope;
#   (в) перевод отменил бы записанное свойство «панель остаётся открытой на
#       отказе», доказанное планом 10-07 на реальной форме события отказа и
#       стоящее отдельным пунктом ручного обхода со своим окном (22).
#
# ⚠️ МАШИННЫЙ ГЕЙТ ОТ ОТКАЗА ОТ ИСХОДА (2) НЕ СЛАБЕЕТ, И В ЭТОМ ВЕСЬ СМЫСЛ
# РАЗВЕДЕНИЯ. Выход, собранный переведённым обработчиком помимо слоя ответа и
# здесь не названный, краснит прогон С ИМЕНЕМ. Отложено РЕШЕНИЕ о форме, а не
# ВИДИМОСТЬ выхода.
#
# ⚠️ САМО РЕШЕНИЕ ПЕРЕДАНО ВЛАДЕЛЬЦУ ОКНОМ 63 РЕЕСТРА `.planning/WINDOWS.md` —
# по форме окна 51, которым четвёртая партия передала владельцу решение о форме
# отказа ВАЛИДАЦИИ. Реестр здесь стережёт ВИДИМОСТЬ выходов; окно несёт вопрос.
# Разведение это не оформление: перечень без окна оставил бы решение висеть в
# суите, где владелец его не увидит, а окно без перечня — вернуло бы молчание в
# дерево.
# =============================================================================


# ⚠️ ПЕРЕЧЕНЬ УЗНАВАЕМЫХ ИМЁН ОБЪЯВЛЕН КОНСТАНТОЙ, А НЕ НАБРАН В ВЫРАЖЕНИИ.
# Перечень внутри выражения нельзя ни сосчитать, ни расширить осознанно: он
# растёт правкой условия, и следующий читатель не отличит «имя не узнаётся» от
# «имени в дереве нет».
#
# ПРИЗНАК ОТБОРА НАЗВАН: сюда входит КАЖДОЕ имя, которым в этом проекте
# СОБИРАЕТСЯ ОБЪЕКТ ОТВЕТА, — базовый `Response` и все сборщики Starlette и
# FastAPI, наследующие ему. Отбор по признаку, а не по наблюдению: имя,
# сегодня в дереве не встречающееся (`FileResponse`, `StreamingResponse`),
# внесено ЗАРАНЕЕ, потому что дописывать перечень в день появления первого
# вхождения — значит на один день остаться слепым ровно к нему.
#
# ⚠️ `RedirectResponse` ВХОДИТ СЮДА, ХОТЯ ЕГО СТЕРЕЖЁТ И `G-2`. Предметы у
# правил РАЗНЫЕ: `G-2` запрещает переведённому обработчику собственный РЕДИРЕКТ
# (и остаётся зелёным), а этот перечень ТРЕБУЕТ ОБЪЯВЛЕНИЯ любого собственного
# выхода. Выпади `RedirectResponse` отсюда — снятие `G-2` будущей фазой
# оставило бы редирект невидимым обоим правилам.
OWN_RESPONSE_CALLABLES = frozenset(
    {
        "Response",
        "HTMLResponse",
        "JSONResponse",
        "ORJSONResponse",
        "UJSONResponse",
        "PlainTextResponse",
        "RedirectResponse",
        "StreamingResponse",
        "FileResponse",
    }
)


# ЧЕТВЁРТЫЙ выход слоя ответа и имена его аргументов-сборщиков (Фаза 11, план
# 11-08). Выход `respond_field_error` обслуживает ОШИБКУ ЗАПОЛНЕНИЯ: он берёт
# ДВА сборщика — страницы и фрагмента — и зовёт РОВНО ОДИН из них, выбирая по
# способу прихода запроса. Имена выписаны здесь, а не рядом с `RESPONSE_CALL`
# выше: их предмет — граница сборщика, и читаются они только этим разбором.
FIELD_ERROR_CALL = "respond_field_error"
FIELD_ERROR_BUILDER_ARGUMENTS = ("page", "fragment")


def _fragment_builder_names(function: ast.AST) -> set[str]:
    """Имена вложенных функций, ПОДАННЫХ слою ответа СБОРЩИКАМИ ответа.

    ⚠️ ЭТО НЕ ПОСЛАБЛЕНИЕ РАЗБОРУ, А ГРАНИЦА ЕГО ПРЕДМЕТА, И РАЗНИЦА
    ИЗМЕРЕНА. Сборщик фрагмента возвращает ответ ПО ТРЕБОВАНИЮ слоя: его зовёт
    сам `respond()`, получив его аргументом `fragment=`. Решение о форме ответа
    здесь принимает слой, а не обработчик, — тело фрагмента есть то, ЧЕМ слой
    отвечает, а не второй ответ на тот же вопрос. Замер: без этой границы
    разбор давал ДВЕНАДЦАТЬ мест у ДЕСЯТИ переведённых обработчиков, из них ТРИ
    (`account_groups.py:593`, `account_groups.py:832`, `schedules.py:1228`) —
    сборка фрагмента внутри вложенного `_fragment`, поданного `respond()`.
    Объявить их «выходами в обход слоя» значило бы назвать расхождением ровно
    тот путь, ради которого слой и заведён.

    ⚠️ ГРАНИЦА РАСШИРЕНА НА ЧЕТВЁРТЫЙ ВЫХОД СЛОЯ — ФАЗА 11, ПЛАН 11-09, И
    ПРЕЖНЯЯ РЕДАКЦИЯ НЕ СТЁРТА, А ПЕРЕЖИТА (идиома D-30/D-32). Она верна для
    дерева, на котором писалась: выход слоя, берущий сборщик, был РОВНО ОДИН.
    Планом 11-08 у слоя появился ЧЕТВЁРТЫЙ выход — `respond_field_error`, — и он
    берёт ДВА сборщика (`page=`, `fragment=`). Разбор, знающий только `respond`,
    объявлял их сборки СОБСТВЕННЫМ ВЫХОДОМ обработчика, то есть требовал записи
    в перечень расхождений ровно для того пути, ради которого слой и заведён, —
    та же ошибка, что и без исходной границы, только у нового выхода.

    ⚠️ ЭТО НЕ ОСЛАБЛЯЕТ ПЕРЕЧЕНЬ, И НАПРАВЛЕНИЕ НАЗЫВАЕТСЯ. Исключается ТОЛЬКО
    сборщик, ПОДАННЫЙ ИМЕНЕМ одному из выходов слоя; собственный ответ, собранный
    в теле обработчика мимо слоя, по-прежнему найден и по-прежнему требует
    записи. ЧЕМ ИЗМЕРЕНО: до расширения правило полноты назвало
    `app/pages/profile.py::profile_post (вид HTMLResponse())` найденным и не
    объявленным — притом что обе его сборки живут во вложенных сборщиках,
    поданных четвёртому выходу.

    Узнаётся ИМЕНОВАННЫЙ аргумент сборщика у вызова выхода слоя, поданный ИМЕНЕМ
    (`fragment=_fragment`, `page=_page`). Лямбда и выражение не узнаются, и
    ошибка здесь безопасна ПО НАПРАВЛЕНИЮ: неузнанный сборщик останется в
    найденном, то есть потребует объявления записью, а не проедет молча.

    ⚠️ ГРАНИЦА РАСШИРЕНА НА ВЫХОД СМЕНЫ ЭКРАНА — ФАЗА 14, ПЛАН 14-02, И ПРЕЖНЯЯ
    РЕДАКЦИЯ НЕ СТЁРТА, А ПЕРЕЖИТА. Абзац о «четвёртом выходе» верен для дерева
    плана 11-09. Планом 14-02 у слоя появился выход `respond_screen` — сестра
    выхода ошибки поля с тем же общим телом, — и он берёт те же ДВА сборщика
    (`FIELD_ERROR_BUILDER_ARGUMENTS`). Без расширения их сборки снова оказались
    бы «собственными выходами» — та же ошибка, что план 11-09 чинил для выхода
    ошибки поля. ЧЕМ ИЗМЕРЕНО: до расширения второй шаг контроля
    `test_control_a_handler_answering_only_by_a_screen_change_is_converted_and_hands_a_fragment`
    краснел дословно: `сборщики, поданные выходу смены экрана именем, объявлены
    собственными выходами обработчика: HTMLResponse()`.
    """
    names: set[str] = set()
    for node in ast.walk(function):
        if not isinstance(node, ast.Call):
            continue
        func = node.func
        called = func.attr if isinstance(func, ast.Attribute) else getattr(func, "id", None)
        if called == RESPONSE_CALL:
            builder_arguments: tuple[str, ...] = (FRAGMENT_ARGUMENT,)
        elif called in (FIELD_ERROR_CALL, SCREEN_CHANGE_CALL):
            builder_arguments = FIELD_ERROR_BUILDER_ARGUMENTS
        else:
            continue
        for keyword in node.keywords:
            if keyword.arg in builder_arguments and isinstance(keyword.value, ast.Name):
                names.add(keyword.value.id)
    return names


def _own_response_builds(function: ast.AST) -> list[tuple[str, int]]:
    """Собственные сборки ответа обработчика — ВИД и СТРОКА, а не «да/нет».

    ⚠️ ФУНКЦИЯ ЗАВЕДЕНА РЯДОМ С `_builds_own_redirect`, А НЕ ВМЕСТО НЕЁ.
    Предмет прежней — РЕДИРЕКТ, и `G-2` в прежней формулировке продолжает его
    стеречь своим разборщиком. Расширить прежнюю функцию значило бы починить
    слепоту ценой потери правила: `G-2` покраснел бы на девяти отказах по
    происхождению, то есть предъявил бы красный вместо измерения.

    ВИД возвращается СТРОКОЙ (`Response(status_code=403)`), а не признаком:
    правило полноты ниже сличает вид объявленный с видом измеренным, и запись,
    у которой сборка сменилась с `403` на `404`, обязана краснеть — иначе
    обоснование записи описывало бы не тот выход, который в дереве.

    Псевдоним импорта не узнаётся — та же названная граница, что у
    `_calls_response_layer` и `_builds_own_redirect`, и та же безопасность по
    направлению: неузнанное имя даёт МЕНЬШЕ найденного, то есть правило числа
    краснеет, а не зеленеет.
    """
    fragments = _fragment_builder_names(function)

    skipped: set[int] = set()
    for node in ast.walk(function):
        if (
            isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
            and node is not function
            and node.name in fragments
        ):
            for inner in ast.walk(node):
                skipped.add(id(inner))

    found: list[tuple[str, int]] = []
    for node in ast.walk(function):
        if not isinstance(node, ast.Call) or id(node) in skipped:
            continue
        func = node.func
        name = func.attr if isinstance(func, ast.Attribute) else getattr(func, "id", None)
        if name not in OWN_RESPONSE_CALLABLES:
            continue

        status: str | None = None
        for keyword in node.keywords:
            if keyword.arg != "status_code":
                continue
            value = keyword.value
            if isinstance(value, ast.Constant):
                status = str(value.value)
            elif isinstance(value, ast.Attribute):
                status = value.attr
            else:
                status = "выражение"
        kind = f"{name}(status_code={status})" if status else f"{name}()"
        found.append((kind, node.lineno))
    return found


def _converted_with_own_response(sources: dict[str, str]) -> dict[str, str]:
    """Переведённые обработчики, несущие СОБСТВЕННУЮ сборку ответа.

    Возвращается отображение «ВХОД → ВИД сборки». Ключ — та же пара «модуль +
    имя обработчика», что у `_post_handlers`: перечень обязан читаться рядом с
    остальными множествами файла и сличаться с ними без перевода.

    ⚠️ ВСЕЛЕННАЯ — ТОЛЬКО ПЕРЕВЕДЁННЫЕ, И ГРАНИЦА НАЗВАНА, А НЕ ПОДРАЗУМЕВАЕТСЯ.
    Обработчик, слоя ответа не знающий, второго решения о форме не несёт: у него
    решение ОДНО, своё, и предмет его — счётчик отставания
    (`NOT_YET_CONVERTED`), а не этот перечень. Собственный отказ у него —
    не расхождение с утверждением слоя, потому что слой о нём ничего не
    утверждает.
    """
    found: dict[str, str] = {}
    for module, text in sources.items():
        tree = _parse(module, text)
        for node in ast.walk(tree):
            if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue
            if not any(_declares_post(decorator) for decorator in node.decorator_list):
                continue
            if not _calls_response_layer(node):
                continue
            builds = _own_response_builds(node)
            if not builds:
                continue
            kinds = sorted({kind for kind, _ in builds})
            found[f"{module}::{node.name}"] = ", ".join(kinds)
    return found


@dataclass(frozen=True)
class _OwnResponseExit:
    """Один СОБСТВЕННЫЙ ВЫХОД переведённого обработчика.

    Пять полей по форме соседнего реестра расхождения формы отказа валидации, и
    ни одно не служебное: ВХОД (какой обработчик), ВИД собственной сборки (чем
    именно выход сделан), ОБОСНОВАНИЕ (что этот выход делает и какова его цена,
    названная СЛЕДСТВИЕМ), УСЛОВИЕ СНЯТИЯ (что именно его снимет) и СОСТОЯНИЕ
    РЕШЕНИЯ (кто и чем признал выход законным — либо что не признал никто).
    """

    entry: str
    kind: str
    reason: str
    lifting_condition: str
    decision_state: str


