#
# ЛЕТОПИСЬ ЧИСЛА:
#   0 → 9, Фаза 10, ПЯТАЯ партия, план 10-31, задача 1: перечень заведён
#   ЗАМЕРОМ, и число поставлено ПРОГОНОМ ПОКРАСНЕВШЕГО ПРАВИЛА — заведомо
#   неверное вписано первым, девять ключей прочитаны из текста отказа.
#   ЧЕМ ИЗМЕРЕНО: разбор дерева `app/pages/**/*.py`; вселенная — ПЕРЕВЕДЁННЫЕ
#   POST-обработчики (`_calls_response_layer`), которых замер даёт ДЕСЯТЬ;
#   найденное — вызовы имён из `OWN_RESPONSE_CALLABLES` в теле обработчика ВНЕ
#   вложенного сборщика фрагмента.
#   ⚠️ ДЕВЯТЬ ИЗ ДЕСЯТИ, А НЕ ДЕСЯТЬ: `account_groups.py::account_groups_toggle`
#   переведён и собственного выхода НЕ НЕСЁТ — его единственная сборка ответа
#   живёт во вложенном `_fragment`, поданном слою. Это и есть встроенный
#   антивакуум перечня: будь разбор слеп к границе сборщика фрагмента, тумблер
#   попал бы сюда десятым, а вместе с ним и два фрагмента соседей.
#   ⚠️ ДЕВЯТЬ ИЗ ТРИНАДЦАТИ ПО ВСЕМУ СТРАНИЧНОМУ СЛОЮ, И ЧЕТЫРЕ ОСТАЛЬНЫХ
#   НАЗВАНЫ ЗДЕСЬ, А НЕ ОСТАВЛЕНЫ ЧИТАТЕЛЮ. Ориентир планировщика — тринадцать
#   мест собственного отказа во всём слое — замером ПОДТВЕРЖДЁН дословно:
#   тринадцать вызовов `Response(status_code=403)` в `app/pages/**/*.py`.
#   Четыре из них стоят в обработчиках, слоя ответа НЕ ЗНАЮЩИХ, и потому во
#   вселенную этого перечня не входят: `admin.py::admin_toggle_free_access`,
#   `admin.py::admin_toggle_block`, `auth.py::stop_impersonation`,
#   `billing.py::subscribe_to_plan`. Их предмет — счётчик отставания
#   (`NOT_YET_CONVERTED`), а не расхождение с утверждением слоя: слой о них
#   ничего не утверждает.
#
#   9 → 10, Фаза 11, план 11-12. ИСТОЧНИК ДВИЖЕНИЯ: БЛОКИРОВКА ПОЛЬЗОВАТЕЛЯ ИЗ
#   ЕГО КАРТОЧКИ переведена на слой ответа и тем самым ВОШЛА во вселенную
#   перечня со своим голым 403 — первой из четырёх, названных абзацем выше.
#   Запись стоит в состоянии `DECISION_OWNER_D08`: голый 403 оставлен решением
#   ВЛАДЕЛЬЦА (D-08 Фазы 11), которое перечисляет этот обработчик поимённо.
#   ⚠️ Имя набрано СЛОВАМИ по той же причине, что в соседних летописях.
#   ⚠️ ЧИСЛО ПОСТАВЛЕНО ПРОГОНОМ ПОКРАСНЕВШЕГО ПРАВИЛА. После перевода, ДО
#   записи, `test_every_own_response_exit_of_a_converted_handler_is_declared`
#   сказал дословно: `НАЙДЕН ЗАМЕРОМ, НО НЕ ОБЪЯВЛЕН: app/pages/admin.py::admin_toggle_block
#   (вид Response(status_code=403))`; после записи
#   `test_the_number_of_own_response_exits_is_declared` — `собственных выходов
#   переведённых обработчиков объявлено 10, а число говорит 9`.
#
#   10 → 11, Фаза 11, план 11-13. ИСТОЧНИК ДВИЖЕНИЯ: ВЫДАЧА И СНЯТИЕ
#   БЕСПЛАТНОГО ДОСТУПА из карточки пользователя переведены на слой ответа и
#   ВОШЛИ во вселенную перечня со своим голым 403 — второй из четырёх,
#   названных в первой записи летописи. ⚠️ Имя набрано СЛОВАМИ.
#   ⚠️ ТЕМ ЖЕ ПЛАНОМ ВСЕ ДЕВЯТЬ ПРЕЖНИХ ЗАПИСЕЙ ПЕРЕВЕДЕНЫ ИЗ «ЖДЁТ ВЛАДЕЛЬЦА» В
#   `DECISION_OWNER_D08`: решение владельца D-08 называет их множеством («к
#   девяти записям `OWN_RESPONSE_EXITS`») и закрывает для всего реестра вопрос о
#   ФОРМЕ отказа по источнику. Число записей от этого не двинулось; двинулось
#   только их состояние. Окно 63 реестра остаётся открытым — D-08 закрывает его
#   часть «решение о форме», а не счёт выходов.
#   ⚠️ ЧИСЛО ПОСТАВЛЕНО ПРОГОНОМ ПОКРАСНЕВШЕГО ПРАВИЛА. После перевода, ДО
#   записи, `test_every_own_response_exit_of_a_converted_handler_is_declared`
#   сказал дословно: `НАЙДЕН ЗАМЕРОМ, НО НЕ ОБЪЯВЛЕН:
#   app/pages/admin.py::admin_toggle_free_access (вид Response(status_code=403))`;
#   после записи `test_the_number_of_own_response_exits_is_declared` —
#   `собственных выходов переведённых обработчиков объявлено 11, а число говорит 10`.
#
#   11 → 12, Фаза 11, план 11-15. ИСТОЧНИК ДВИЖЕНИЯ: ОФОРМЛЕНИЕ ДОСТУПА С УХОДОМ
#   НА СТРАНИЦУ ЮKassa переведено на слой ответа и ВОШЛО во вселенную перечня
#   со своим голым 403 — третьей из четырёх, названных в первой записи
#   летописи; запись стоит в состоянии `DECISION_OWNER_D08`. ⚠️ Имя набрано
#   СЛОВАМИ. Четвёртый из названных — выход из-под чужой личности в разделе
#   входа — остаётся в перечне отставания.
#   ⚠️ ЧИСЛО ПОСТАВЛЕНО ПРОГОНОМ ПОКРАСНЕВШЕГО ПРАВИЛА. После перевода, ДО
#   записи, `test_every_own_response_exit_of_a_converted_handler_is_declared`
#   сказал дословно: `НАЙДЕН ЗАМЕРОМ, НО НЕ ОБЪЯВЛЕН:
#   app/pages/billing.py::subscribe_to_plan (вид Response(status_code=403))`.
#
#   12 → 13, Фаза 12, план 12-10. ИСТОЧНИК ДВИЖЕНИЯ: ЗАГРУЗКА ВЛОЖЕНИЯ
#   ОБЪЯВЛЕНИЯ получила сверку источника решением владельца D-15 и тем самым
#   завела свой голый 403. ⚠️ ЭТО ПЕРВЫЙ РОСТ ПЕРЕЧНЯ НЕ ОТ ПЕРЕВОДА, А ОТ
#   НОВОГО ВЫХОДА У УЖЕ ПЕРЕВЕДЁННОГО ОБРАБОТЧИКА, и разница предметная:
#   двенадцать прежних записей вошли в перечень, когда обработчик, уже имевший
#   собственный отказ, переезжал на слой ответа; тринадцатая — когда обработчик,
#   с рождения живший на слое (Фаза 12, D-01), получил собственный отказ
#   ВПЕРВЫЕ. «Четыре остальных», названные первой записью летописи, от этого не
#   двинулись: их счёт про переводимых, а не про новых.
#   ⚠️ СОСТОЯНИЕ РЕШЕНИЯ У ЗАПИСИ СВОЁ — `DECISION_OWNER_D15`, А НЕ D08, и это
#   соблюдение границы, а не её обход: D-08 называет «девять записей» и «три
#   обработчика этой фазы», а маршрута загрузки в страничном слое в тот день не
#   существовало вовсе. Форма у двух решений совпала; распространением одного на
#   другое совпадение не является.
#   ⚠️ ЧИСЛО ПОСТАВЛЕНО ПРОГОНОМ ПОКРАСНЕВШЕГО ПРАВИЛА. После вызова гарда, ДО
#   записи, `test_every_own_response_exit_of_a_converted_handler_is_declared`
#   сказал дословно: `НАЙДЕН ЗАМЕРОМ, НО НЕ ОБЪЯВЛЕН:
#   app/pages/ads.py::ads_images_upload (вид Response(status_code=403))`.
#
#   13 → 14, Фаза 14, план 14-06. ИСТОЧНИК ДВИЖЕНИЯ: ВОЗВРАТ ИЗ-ПОД ЧУЖОЙ
#   ЛИЧНОСТИ переведён на слой ответа и тем самым ВОШЁЛ во вселенную перечня со
#   своим голым 403 — ЧЕТВЁРТЫЙ И ПОСЛЕДНИЙ из «четырёх остальных», названных
#   первой записью летописи. Три предыдущих сняты планами 11-12, 11-13 и 11-15;
#   этот Фаза 11 оставила Фазе 14 прямым решением (`11-CONTEXT.md:159`).
#   ⚠️ СОСТОЯНИЕ РЕШЕНИЯ У ЗАПИСИ СВОЁ — `DECISION_OWNER_D01_F14`, А НЕ D-08, и
#   это соблюдение границы, а не её обход: абзацы у `DECISION_OWNER_D08` прямо
#   называют `stop_impersonation` обработчиком, которого D-08 не называет ни
#   множеством, ни именем. Форму отказа для него выбрал владелец ОТДЕЛЬНЫМ
#   решением 2026-09-22 (D-01 Фазы 14), сославшись на D-08 как на прецедент.
#   Форма у двух решений совпала; распространением одного на другое совпадение
#   не является — та же граница, которую соблюдала запись Фазы 12.
#   ⚠️ С ЭТОЙ ЗАПИСЬЮ ВСЕ ГОЛЫЕ 403 СТРАНИЧНОГО СЛОЯ ЖИВУТ ВО ВСЕЛЕННОЙ
#   ПЕРЕЧНЯ, И ЭТО ЗАМЕР, А НЕ ВЫВОД: «четыре остальных» первой записи летописи
#   исчерпаны, а счётчик отставания (`NOT_YET_CONVERTED_COUNT`) дошёл до нуля
#   тем же планом — то есть обработчиков, чей собственный отказ виден счётчику
#   отставания, а не этому реестру, в страничном слое не осталось.
#   ⚠️ ЧИСЛО ПОСТАВЛЕНО ПРОГОНОМ ПОКРАСНЕВШЕГО ПРАВИЛА. После перевода, ДО
#   записи, `test_every_own_response_exit_of_a_converted_handler_is_declared`
#   сказал дословно: `НАЙДЕН ЗАМЕРОМ, НО НЕ ОБЪЯВЛЕН:
#   app/pages/auth.py::stop_impersonation (вид Response(status_code=403))`; тем
#   же прогоном покраснел и контроль укороченного перечня
#   (`test_control_a_shortened_own_response_list_reddens_the_completeness_rule`)
#   — той же жалобой, протёкшей за границу контроля.
OWN_RESPONSE_EXITS_DECLARED = 14


def _own_response_completeness_complaints(
    exits: tuple[_OwnResponseExit, ...],
    sources: dict[str, str] | None = None,
) -> list[str]:
    """Жалобы правила ПОЛНОТЫ — на ПОДАННЫЙ перечень, а не на модульный.

    Перечень приходит параметром ровно затем, чтобы контроль зубов мог подать
    УКОРОЧЕННУЮ копию и увидеть, что правило её заметило. Приём взят у
    соседнего реестра расхождения формы отказа валидации.
    """
    measured = _converted_with_own_response(
        _pages_sources() if sources is None else sources
    )
    declared = {item.entry: item.kind for item in exits}

    complaints: list[str] = []
    for entry in sorted(set(measured) - set(declared)):
        complaints.append(
            f"НАЙДЕН ЗАМЕРОМ, НО НЕ ОБЪЯВЛЕН: {entry} (вид {measured[entry]})"
        )
    for entry in sorted(set(declared) - set(measured)):
        complaints.append(f"ОБЪЯВЛЕН, НО ЗАМЕРОМ НЕ НАЙДЕН: {entry}")
    for entry in sorted(set(declared) & set(measured)):
        if declared[entry] != measured[entry]:
            complaints.append(
                f"ВИД СБОРКИ РАЗОШЁЛСЯ С ЗАМЕРОМ: {entry} объявлен как "
                f"{declared[entry]!r}, а измерен как {measured[entry]!r}"
            )
    return complaints


def _own_response_rationale_complaints(
    exits: tuple[_OwnResponseExit, ...],
) -> list[str]:
    """Жалобы правила ОБОСНОВАНИЙ — на ПОДАННЫЙ перечень.

    Перечень без обоснований есть список того, до чего не дошли руки, и
    отличить его от объявленного выхода нельзя ничем, кроме этих пяти непустых
    полей.
    """
    complaints: list[str] = []

    for item in exits:
        where = item.entry or "(запись без входа)"

        if not item.entry.strip():
            complaints.append(
                "запись собственного выхода не называет ВХОДА — обоснование, "
                "стоящее ни на чём, неотличимо от отсутствующего"
            )
        if not item.kind.strip():
            complaints.append(
                f"выход «{where}» не называет ВИДА собственной сборки: читатель "
                "не найдёт места, которым выход сделан"
            )
        if not item.reason.strip():
            complaints.append(
                f"выход «{where}» объявлен БЕЗ ОБОСНОВАНИЯ — перечень без "
                "обоснований есть список того, до чего не дошли руки"
            )
        if not item.decision_state.strip():
            complaints.append(
                f"выход «{where}» не несёт СОСТОЯНИЯ РЕШЕНИЯ: молчащее "
                "состояние читается как решённое, а решения не было"
            )
        if not item.lifting_condition.strip():
            complaints.append(
                f"выход «{where}» не называет УСЛОВИЯ СНЯТИЯ — через фазу он "
                "станет неотличим от недоделки"
            )
        else:
            if "Фаза 11" not in item.lifting_condition:
                complaints.append(
                    f"выход «{where}» не называет ФАЗЫ РАБОТЫ. Фаза взята ИЗ "
                    "РОАДМАПА (Фаза 11, критерий 1), а не назначена планом; "
                    "условие снятия, потерявшее её имя, оставляет перечень без "
                    "адресата работы"
                )
            if "ВЛАДЕЛЬЦУ" not in item.lifting_condition:
                complaints.append(
                    f"выход «{where}» не называет ВЛАДЕЛЬЦА РЕШЕНИЯ О ФОРМЕ. "
                    "Два адресата здесь РАЗНЫЕ: Фаза 11 снимает выход работой, "
                    "а форму ответа выбирает владелец (D-01 заперт). Условие, "
                    "назвавшее только фазу, читалось бы как назначенное "
                    "решение — ровно то присвоение чужого авторства, которое "
                    "запрещает прецедент окна 51"
                )
        if _OWN_RESPONSE_PRICE.split(":")[0] not in item.reason:
            complaints.append(
                f"обоснование выхода «{where}» не называет ЦЕНЫ ТРЕМЯ "
                "СЛЕДСТВИЯМИ: обоснование без цены превращает объявленный "
                "выход обратно в умолчание"
            )

    return complaints


def _own_response_authorship_complaints(
    exits: tuple[_OwnResponseExit, ...],
) -> list[str]:
    """Жалобы правила АВТОРСТВА — на ПОДАННЫЙ перечень.

    Запись, объявившая себя РЕШЁННОЙ, обязана называть, ЧЕМ решена:
    идентификатором решения владельца по форме `D-NN` либо номером закрытого
    окна реестра. Разбор общий с соседним реестром (`_DECISION_REFERENCE`) —
    вторая копия того же выражения разъехалась бы с первой молча.
    """
    complaints: list[str] = []

    for item in exits:
        state = item.decision_state.strip()
        if not state or state == DECISION_WAITS_FOR_THE_OWNER:
            continue
        if not _DECISION_REFERENCE.search(state):
            complaints.append(
                f"собственный выход «{item.entry}» объявлен РЕШЁННЫМ "
                f"({state!r}), но не называет, ЧЕМ решено"
            )

    return complaints


def test_the_number_of_own_response_exits_is_declared():
    """Число собственных выходов равно ОБЪЯВЛЕННОМУ.

    ⚠️ ЧТО ЗНАЧИТ КАЖДОЕ ИЗ ДВУХ НАПРАВЛЕНИЙ. Молча ВЫРОСШИЙ перечень означает,
    что переведённый обработчик получил второе решение о форме ответа, а записи
    об этом никто не сделал, — то самое молчание, которое читается как
    исполненный инвариант единственности. Молча ПОХУДЕВШИЙ означает либо снятый
    выход (и тогда суженное утверждение шапки слоя ответа обязано быть
    исправлено вместе с числом), либо ослепший разбор.
    """
    assert len(OWN_RESPONSE_EXITS) == OWN_RESPONSE_EXITS_DECLARED, (
        f"собственных выходов переведённых обработчиков объявлено "
        f"{len(OWN_RESPONSE_EXITS)}, а число говорит "
        f"{OWN_RESPONSE_EXITS_DECLARED}. Рост означает второе решение о форме "
        "ответа, принятое без записи; падение — снятый выход при неисправленном "
        "утверждении слоя ответа либо ослепший разбор"
    )


def test_every_own_response_exit_of_a_converted_handler_is_declared():
    """ПОЛНОТА ПО ЗАМЕРУ: каждый собственный выход переведённого обработчика назван.

    ⚠️ ЭТО И ЕСТЬ СНЯТИЕ СЛЕПОТЫ ГЕЙТА `G-2`. Прежде переведённый обработчик,
    собравший ответ САМ, оставался невидимым, если сборка не была редиректом.
    Отказ по происхождению `Response(status_code=403)`, дописанный четвёртой
    партией в девять обработчиков, гейт не увидел НИ РАЗУ.

    ⚠️ АНТИВАКУУМ СТОИТ ВНУТРИ ПРАВИЛА, А НЕ РЯДОМ С НИМ. Правило полноты,
    чья вселенная пуста, зелено вечно и не доказывает ничего: утверждение
    «расхождений нет» неотличимо от «разбор сломался». Поэтому непустота
    вселенной переведённых утверждается ПЕРВОЙ, до сличения множеств.
    """
    sources = _pages_sources()
    converted = _converted(sources)

    assert converted, (
        "вселенная правила ПУСТА: переведённых обработчиков не найдено ни "
        "одного. Правило полноты на пустой вселенной зелено вечно — разбирать "
        "надо ЗАМЕР (`_calls_response_layer`), а не перечень"
    )

    complaints = _own_response_completeness_complaints(OWN_RESPONSE_EXITS)

    assert not complaints, (
        "ПЕРЕЧЕНЬ СОБСТВЕННЫХ ВЫХОДОВ РАЗОШЁЛСЯ С ЗАМЕРОМ СТРАНИЧНОГО СЛОЯ:\n  "
        + "\n  ".join(complaints)
        + "\n\nПереведённый обработчик, собирающий ответ ПОМИМО слоя ответа, "
        "обязан быть либо переведён на слой целиком, либо ОБЪЯВЛЕН здесь — с "
        "видом сборки, ценой, условием снятия и состоянием решения. Ни тем ни "
        "другим он быть не может: шапка слоя ответа утверждает, что решение о "
        "форме принимается в ОДНОМ месте, и молча уцелевший выход делает это "
        "утверждение ложным без единого признака"
    )


def test_every_own_response_exit_carries_a_non_empty_rationale():
    """У КАЖДОГО собственного выхода непусты все пять полей, и цена названа.

    ⚠️ ПОЧЕМУ ПРОВЕРЯЕТСЯ ИМЕННО НЕПУСТОТА, А НЕ КРАСОТА ТЕКСТА. Перечень,
    записи которого молчат об основании, ничем не отличается от списка «сюда не
    дошли руки»: обе формы зелены, и обе оставляют следующего читателя без
    знания, ПРИНЯТ выход или ПРОСМОТРЕН.
    """
    complaints = _own_response_rationale_complaints(OWN_RESPONSE_EXITS)

    assert not complaints, (
        "ЗАПИСЬ СОБСТВЕННОГО ВЫХОДА ОКАЗАЛАСЬ НЕПОЛНОЙ:\n  "
        + "\n  ".join(complaints)
    )


def test_no_own_response_exit_claims_a_decision_the_owner_did_not_make():
    """Запись, объявившая себя РЕШЁННОЙ, обязана назвать, ЧЕМ решена.

    ⚠️ ПРАВИЛО СТЕРЕЖЁТ НЕ КОД, А ГРАНИЦУ ПОЛНОМОЧИЙ. D-01 есть ЗАПЕРТОЕ
    решение владельца, и изъятие из него чеканит владелец: единственный
    прецедент, D-08, назван «ИМЕНОВАННЫМ ИЗЪЯТИЕМ ИЗ D-01» и записан ВЛАДЕЛЬЦЕМ
    на этапе обсуждения. Изъятие, дочеканенное планом либо исполнителем, есть
    присвоение чужого авторства, и отличить его от решения владельца в записи
    было бы нечем.
    """
    complaints = _own_response_authorship_complaints(OWN_RESPONSE_EXITS)

    assert not complaints, (
        "РЕШЕНИЕ ОБЪЯВЛЕНО БЕЗ ССЫЛКИ НА ТОГО, КТО ЕГО ПРИНЯЛ:\n  "
        + "\n  ".join(complaints)
        + f"\n\nСостояние, отличное от {DECISION_WAITS_FOR_THE_OWNER!r}, "
        "обязано называть идентификатор решения владельца по форме `D-NN` либо "
        "номер закрытого окна реестра `.planning/WINDOWS.md`"
    )


def test_control_a_shortened_own_response_list_reddens_the_completeness_rule():
    """ЗУБЫ ПРАВИЛА ПОЛНОТЫ — УКОРОЧЕННЫМ ПЕРЕЧНЕМ, А НЕ ПРОЗОЙ.

    ⚠️ БЕЗ ЭТОГО КОНТРОЛЯ ПРАВИЛО ПОЛНОТЫ ЗЕЛЕНЕЛО БЫ И НА ЗАМЕРЕ, ВОЗВРАЩАЮЩЕМ
    ПУСТО. Контроль подаёт правилу КОПИЮ перечня без одной записи и показывает,
    что правило краснеет И НАЗЫВАЕТ пропущенный вход поимённо. Копия живёт в
    памяти; боевой перечень не правится ни на символ.

    ⚠️ КОНТРОЛЬ РОНЯЕТ КАЖДУЮ ЗАПИСЬ ПО ОЧЕРЕДИ, А НЕ ПЕРВУЮ. Ронять одну
    значило бы доказать зубы правила на одном модуле и промолчать об остальных
    пяти — ровно та слепота, которую окно 60 реестра назвало внутриплановым
    долгом соседнего реестра: там долг покраснел ДВА узла, потому что контроль
    зубов нёс его наравне с правилом. Здесь долг нести нечему: перебор ловит
    разбор, ослепший на любом ОДНОМ модуле.
    """
    assert len(OWN_RESPONSE_EXITS) >= 2, (
        "контроль требует минимум двух записей: на одной укорачивать нечего"
    )

    for index, dropped in enumerate(OWN_RESPONSE_EXITS):
        shortened = OWN_RESPONSE_EXITS[:index] + OWN_RESPONSE_EXITS[index + 1 :]
        complaints = _own_response_completeness_complaints(shortened)

        assert complaints, (
            f"перечень БЕЗ записи «{dropped.entry}» не вызвал ни одной жалобы — "
            "значит правило полноты читает НЕ поданный перечень, и оно "
            "зеленело бы на любом"
        )
        assert any(dropped.entry in complaint for complaint in complaints), (
            f"правило полноты покраснело, но НЕ НАЗВАЛО пропущенный вход "
            f"«{dropped.entry}». Отказ, не называющий места, чинится перебором, "
            f"а перебором чинят не то. Сказано было: {complaints}"
        )

    assert not _own_response_completeness_complaints(OWN_RESPONSE_EXITS), (
        "ПОДМЕНА ПРОТЕКЛА ЗА ГРАНИЦУ КОНТРОЛЯ: боевой перечень после контроля "
        "перестал сходиться с замером"
    )


def test_control_an_empty_field_reddens_the_own_response_rationale_rule():
    """ЗУБЫ ПРАВИЛА ОБОСНОВАНИЙ — ОПУСТОШЁННЫМ ПОЛЕМ, А НЕ ПРОЗОЙ.

    ⚠️ БЕЗ ЭТОГО КОНТРОЛЯ ПРАВИЛО ОБОСНОВАНИЙ ЗЕЛЕНЕЛО БЫ НА ПЕРЕЧНЕ, У
    КОТОРОГО ПУСТЫ ВСЕ ПЯТЬ ПОЛЕЙ. Контроль опустошает обоснование ОДНОЙ записи
    копии и показывает, что правило краснеет и называет именно её.
    """
    victim = OWN_RESPONSE_EXITS[0]
    emptied = (
        _OwnResponseExit(
            entry=victim.entry,
            kind=victim.kind,
            reason="   ",
            lifting_condition=victim.lifting_condition,
            decision_state=victim.decision_state,
        ),
    ) + OWN_RESPONSE_EXITS[1:]

    complaints = _own_response_rationale_complaints(emptied)

    assert complaints, (
        f"запись «{victim.entry}» с ПУСТЫМ обоснованием прошла правило "
        "обоснований — значит правило читает не поданный перечень, и список "
        "того, до чего не дошли руки, засчитался бы объявленным выходом"
    )
    assert any(victim.entry in complaint for complaint in complaints), (
        f"правило обоснований покраснело, но НЕ НАЗВАЛО запись «{victim.entry}» "
        f"поимённо. Сказано было: {complaints}"
    )

    assert not _own_response_rationale_complaints(OWN_RESPONSE_EXITS), (
        "ПОДМЕНА ПРОТЕКЛА ЗА ГРАНИЦУ КОНТРОЛЯ: боевой перечень после контроля "
        "перестал проходить правило обоснований"
    )


def test_control_a_self_minted_decision_reddens_the_own_response_authorship_rule():
    """ЗУБЫ ПРАВИЛА АВТОРСТВА — ЗАПИСЬЮ, ОБЪЯВИВШЕЙ СЕБЯ РЕШЁННОЙ БЕЗ ССЫЛКИ.

    ⚠️ БЕЗ ЭТОГО КОНТРОЛЯ ПРАВИЛО АВТОРСТВА ЗЕЛЕНЕЛО БЫ НА ПЕРЕЧНЕ, ГДЕ ВСЕ
    ЗАПИСИ ЖДУТ ВЛАДЕЛЬЦА, — то есть ровно на сегодняшнем, и о завтрашнем не
    сказало бы ничего. Контроль переводит ОДНУ запись копии в «решено» без
    ссылки и показывает, что правило краснеет и называет именно её. Он же
    показывает вторую сторону: то же «решено» СО ССЫЛКОЙ на решение владельца
    правило пропускает — иначе правило запрещало бы владельцу принять решение
    вовсе.
    """
    victim = OWN_RESPONSE_EXITS[0]

    def replaced(state: str) -> tuple[_OwnResponseExit, ...]:
        return (
            _OwnResponseExit(
                entry=victim.entry,
                kind=victim.kind,
                reason=victim.reason,
                lifting_condition=victim.lifting_condition,
                decision_state=state,
            ),
        ) + OWN_RESPONSE_EXITS[1:]

    minted = _own_response_authorship_complaints(replaced("решено, форма законна"))

    assert minted, (
        f"запись «{victim.entry}», объявившая себя решённой БЕЗ ССЫЛКИ, прошла "
        "правило авторства — значит изъятие из запертого D-01 можно дочеканить "
        "правкой одной строки, и следующий читатель принял бы его за решение "
        "владельца"
    )
    assert any(victim.entry in complaint for complaint in minted), (
        f"правило авторства покраснело, но НЕ НАЗВАЛО запись «{victim.entry}» "
        f"поимённо. Сказано было: {minted}"
    )

    assert not _own_response_authorship_complaints(
        replaced("решено ВЛАДЕЛЬЦЕМ: D-08, форма прецедента")
    ), (
        "правило авторства отвергло состояние, НАЗВАВШЕЕ решение владельца "
        "(`D-NN`), — то есть запрещает владельцу принять решение вовсе, а не "
        "запрещает дочеканить его за него"
    )

    assert not _own_response_authorship_complaints(OWN_RESPONSE_EXITS), (
        "ПОДМЕНА ПРОТЕКЛА ЗА ГРАНИЦУ КОНТРОЛЯ: боевой перечень после контроля "
        "перестал проходить правило авторства"
    )


# =============================================================================
# План 11-10: ПЕРЕЧЕНЬ ПРИМЕНЕНИЙ ТОЧЕЧНЫХ ЗАГОЛОВКОВ ОТВЕТА (D-16, FORM-10)
# =============================================================================
#
# ЧТО ЗДЕСЬ УТВЕРЖДАЕТСЯ ОДНОЙ ФРАЗОЙ. Два заголовка ответа, которыми сервер
# ПЕРЕНАЦЕЛИВАЕТ подмену и МЕНЯЕТ ЕЁ СПОСОБ, применяются только поимённо — и
# сегодня не применяются нигде.
#
# ⚠️ ПОЧЕМУ ПЕРЕЧЕНЬ, А НЕ ПРАКТИКА (D-16). Цель подмены объявлена в ШАБЛОНЕ:
# читатель разметки видит, куда приедет ответ. Заголовок отменяет это решение из
# ответа, и в шаблоне не остаётся ни следа — поведение формы перестаёт читаться
# по форме. Одно применение стоит того, чтобы его записали; практика применения
# делает невидимой всю веху.
#
# ⚠️ ПОЧЕМУ ПЕРЕЧЕНЬ БЫЛ ПУСТ, И ЭТО БЫЛ ЗАМЕР, А НЕ НЕДОДЕЛКА (Находка B
# разведки). Кандидатов было два. ПЕРВЫЙ — перерисовка формы на 422 (D-06): она
# НЕ требует перенацеливания, потому что цель ошибки поля совпадает с целью
# успеха. Первый такой маршрут вехи — сохранение профиля (план 11-10): и 200, и
# 422 подменяют СОДЕРЖИМОЕ одной обёртки `#profile-settings`, объявленной
# формой. ВТОРОЙ — ветка «было ноль» создания сущности — решена ПЕРЕХОДОМ
# (D-05), а не заголовком.
#
# ⚠️ ТРЕТИЙ КАНДИДАТ СОСТОЯЛСЯ, И ПЕРЕЧЕНЬ ПЕРЕСТАЛ БЫТЬ ПУСТЫМ (Фаза 12, план
# 12-09). Абзац выше НЕ СТИРАЕТСЯ: два несостоявшихся кандидата остаются
# записью о том, чем эти заголовки НЕ являются. Третий — ответ ветви отказа
# РАЗБОРА составного запроса на загрузке вложений, и разрешился он заголовком
# ровно потому, что оба прежних выхода на нём недоступны. ПЕРЕХОДОМ не
# решается: человек остаётся в редакторе, а увод со страницы потерял бы
# набранный текст объявления. СОВПАДЕНИЕМ ЦЕЛЕЙ не решается тем более —
# СПОСОБ подмены у этой ветви обязан отличаться от способа успеха, а не цель:
# успех ПОДМЕНЯЕТ содержимое полосы, отказ разбора обязан ДОПИСАТЬ строку,
# потому что разбор не состоялся и текущих ключей вложений сервер не знает.
# Способ подмены объявляется единственным механизмом, который у htmx для этого
# есть, — заголовком ответа; в разметке формы он объявлен быть не может, потому
# что зависит от ИСХОДА запроса, а не от формы.
#
# ⚠️ САМА ПУСТОТА БЕЗ ЗУБОВ НИЧЕГО НЕ ЗНАЧИТ, И ИМЕННО ПОЭТОМУ У ЭТОГО ПЕРЕЧНЯ
# ЕСТЬ ОТРИЦАТЕЛЬНЫЙ КОНТРОЛЬ. Пустое множество удовлетворяет правило полноты
# ВСЕГДА — в том числе тогда, когда сканер перестал что-либо находить. Зелёный
# цвет сломанного сканера посимвольно совпадает с зелёным цветом соблюдённого
# правила (D-13 Фазы 8), и отличить их можно только подстановкой: синтетический
# модуль с применением заголовка ОБЯЗАН покрасить правило и назвать место.
#
# ⚠️ ЛИТЕРАЛЫ ИМЁН НИЖЕ НЕ МОГУТ УДОВЛЕТВОРИТЬ СОБСТВЕННЫЙ ПОИСК. Области
# поиска — `app/**/*.py` и `app/templates/**/*.html`; файл лежит в `tests/`.
# Свойство структурное и удерживается раскладкой каталогов, а не осторожностью
# формулировок (см. шапку модуля).
#
# ⚠️ ГРАНИЦА НАЗЫВАЕТСЯ ЧЕСТНО: ВЕНДОРЕННЫЙ РАНТАЙМ НЕ СКАНИРУЕТСЯ. Оба имени
# набраны в `app/static/js/htmx.min.js` — это ИСХОДНИК САМОГО htmx, который их и
# читает. Он не `*.py` и не `*.html`, поэтому в обе области поиска не попадает
# ни одним путём; включив его, правило краснело бы вечно и по неустранимой
# причине, то есть учило бы игнорировать красное.
RETARGET_HEADER = "HX-Retarget"
RESWAP_HEADER = "HX-Reswap"
POINTED_HEADERS = frozenset({RETARGET_HEADER, RESWAP_HEADER})

# Комментарий шаблонизатора: вырезается ДО поиска имён в разметке. Проза,
# объясняющая, почему заголовков в шаблоне нет, удовлетворила бы поиск САМА —
# правило краснело бы на объяснении того, что оно же и охраняет (тот же приём,
# которым `_strip_comments` пользуются гейты разметки).
JINJA_COMMENT = re.compile(r"\{#.*?#\}", re.DOTALL)

# ПЕРЕЧЕНЬ ПРИМЕНЕНИЙ: ключ — `app/pages/<файл>.py::<функция>`, значение —
# ОБОСНОВАНИЕ применения (идиома SP-1, форма `DISABLED_ELT_EXCEPTIONS`).
#
# ⚠️ КЛЮЧ ВЗЯТ ИЗ ПРОГОНА ПОКРАСНЕВШЕГО ПРАВИЛА, А НЕ СОЧИНЁН. Обход ключует по
# функции, ОБЪЕМЛЮЩЕЙ строковую константу, и для заголовка, записанного внутри
# вложенного сборщика фрагмента, ключом становится имя СБОРЩИКА, а не имя
# маршрута (`ads_images_upload`). Записать сюда имя маршрута значило бы оставить
# правило полноты красным при верном по существу решении.
RETARGET_RESWAP_USES: dict[str, str] = {
    "app/pages/ads.py::_parts_refusal_fragment": (
        "Ответ ветви отказа РАЗБОРА составного запроса на загрузке вложений "
        "(Фаза 12, план 12-09, находка ревью WR-06). Разбор не состоялся: ни "
        "одного поля `images` сервер не прочитал, и текущих ключей вложений он "
        "НЕ ЗНАЕТ. Подмена содержимого цели ответила бы полосой ПУСТОЙ, то есть "
        "вынесла бы из документа все скрытые поля ключей и отцепила законные "
        "вложения при следующем автосохранении — тот самый дефект, который "
        "закрывает план 12-06 (находка CR-02). Дописывание строки в конец цели "
        "оставляет и полосу, и её скрытые поля нетронутыми. ⚠️ ПЕРЕНАЦЕЛИВАНИЯ "
        "ЗДЕСЬ НЕТ: цель остаётся объявленной разметкой формы, и читатель "
        "разметки по-прежнему видит, куда приедет ответ. Меняется РОВНО СПОСОБ "
        "подмены, и объявить его в шаблоне нельзя — он зависит от ИСХОДА "
        "запроса, а не от формы."
    )
}

# ЛЕТОПИСЬ ЧИСЛА: 0, Фаза 11, план 11-10: цель 422 совпадает с целью успеха
# (Находка B; профиль — план 11-10, мастер MAX — план 11-18), ветка «было ноль»
# создания решена переходом (D-05).
#
#   0 → 1, Фаза 12, план 12-09. ПЕРВОЕ ПРИМЕНЕНИЕ —
#   `app/pages/ads.py::_parts_refusal_fragment`: способ подмены «дописать в
#   конец» на ветви отказа разбора составного запроса. ИСТОЧНИК ДВИЖЕНИЯ:
#   находка ревью WR-06 — предел числа частей, единственная НОВАЯ защита фазы,
#   уходил человеку сырым JSON-ответом с кодом 400, на котором подмены не
#   происходит вовсе.
#   ⚠️ ПОСТАВЛЕНО ПРОГОНОМ ПОКРАСНЕВШЕГО ПРАВИЛА, А НЕ ВЫЧИТАНИЕМ В УМЕ (идиома
#   D-13). Вывод `test_every_retarget_or_reswap_use_is_declared` после задачи 2,
#   дословно: `применения точечных заголовков разошлись с перечнем: измерено
#   ['app/pages/ads.py::_parts_refusal_fragment'], объявлено [] — либо
#   применение завели, не объявив его решением, и цель подмены перестала
#   читаться по шаблону, либо запись пережила своё применение`. Ключ взят из
#   этой строки дословно.
#
# ⚠️ ЧИСЛО ОБЪЯВЛЕНО ИМЕНОВАННОЙ КОНСТАНТОЙ, ХОТЯ ОНО И БЫЛО НУЛЁМ, — тем же
# основанием, что `HX_TARGETS` и `SERVER_SIDE_VALIDATION_RESPONSES`: иначе
# правило полноты остаётся вакуумно зелёным навсегда, и «применений нет»
# неотличимо от «обход применений не находит». Основание не отпало с первой
# записью: теперь число ловит ВТОРОЕ применение, заведённое молча.
RETARGET_RESWAP_USES_DECLARED = 1


def _retarget_reswap_uses(sources: dict[str, str]) -> dict[str, str]:
    """Применения точечных заголовков — СОБРАНЫ ОБХОДОМ, а не выписаны руками.

    То же свойство, что у `_converted` и `_fragment_response_handlers`: множество
    есть ФАКТ исходника, а перечень выше — ОБЪЯВЛЕНИЕ. Расхождение объявления с
    фактом есть предмет правила полноты; собери оба одним обходом — и правило
    проверяло бы себя.

    Признак — СТРОКОВАЯ КОНСТАНТА, РАВНАЯ имени заголовка, в ЛЮБОМ положении:
    ключом словаря заголовков, индексом подписки, аргументом вызова, значением
    объявленной константы. Положение не сужается намеренно: заголовок,
    записанный любым из этих способов, одинаково перенацеливает подмену, и
    разборщик, знающий одну форму, был бы слеп к остальным.

    ⚠️ РАЗБОР ПО ДЕРЕВУ, А НЕ ГРЕПОМ, И ЭТО НЕ ВКУСОВЩИНА (свойство 2 шапки
    модуля). Оба имени НАЗЫВАЮТСЯ СЛОВАМИ в обосновании слоя ответа
    (`app/pages/htmx.py`), где записано, что применяются они поимённо. Греп
    посчитал бы эту прозу применением и покраснел бы на документации о запрете
    вместо его нарушения. Здесь же сравнивается ЗНАЧЕНИЕ константы целиком:
    докстринг, назвавший заголовок, есть другая строка и в множество не попадает.

    ⚠️ ГРАНИЦА НАЗЫВАЕТСЯ ЧЕСТНО И БЕЗОПАСНА ПО НАПРАВЛЕНИЮ. Обращение к имени
    заголовка ЧЕРЕЗ константу, объявленную в другом модуле, узнано не будет —
    узнаётся литерал, а не связывание импорта (та же граница, что у
    `_calls_response_layer`). Но САМО ОБЪЯВЛЕНИЕ такой константы литерал несёт,
    и найдено будет оно: применение окажется объявленным по месту объявления, а
    не пропущенным молча.
    """
    found: dict[str, str] = {}
    for module, text in sorted(sources.items()):
        tree = _parse(module, text)
        for node in ast.walk(tree):
            if not isinstance(node, ast.Constant):
                continue
            if not isinstance(node.value, str) or node.value not in POINTED_HEADERS:
                continue
            key = f"{module}::{_enclosing_function(tree, node.lineno)}"
            found.setdefault(key, node.value)
    return found


def _markup_naming_a_pointed_header(templates: dict[str, str]) -> dict[str, str]:
    """Шаблоны, называющие точечный заголовок ВНЕ комментария шаблонизатора.

    Сравнение регистронезависимо: заголовки HTTP читаются рантаймом без учёта
    регистра, и правило, знающее одно написание, молчало бы о втором.
    """
    found: dict[str, str] = {}
    for rel, source in sorted(templates.items()):
        body = JINJA_COMMENT.sub("", source).lower()
        for header in sorted(POINTED_HEADERS):
            if header.lower() in body:
                found[rel] = header
    return found


def test_every_retarget_or_reswap_use_is_declared():
    """НЕСУЩЕЕ: каждое применение точечного заголовка объявлено поимённо.

    Утверждений три, и ни одно не выводится из остальных:

    1. множество применений, СОБРАННОЕ обходом `app/**/*.py`, равно множеству
       ключей перечня — забытое применение краснеет, устаревшая запись тоже;
    2. у каждой записи непустое обоснование (идиома SP-1): перечень, у которого
       не написано, почему кто-то в него входит, через фазу превращается в
       «наверное, так надо»;
    3. в РАЗМЕТКЕ этих имён нет вовсе. Заголовок ответа в шаблоне не пишется, но
       имя, попавшее туда прозой или атрибутом, означало бы, что решение о
       перенацеливании принимают в двух местах.
    """
    measured = _retarget_reswap_uses(_app_sources())

    assert set(measured) == set(RETARGET_RESWAP_USES), (
        f"применения точечных заголовков разошлись с перечнем: измерено "
        f"{sorted(measured)}, объявлено {sorted(RETARGET_RESWAP_USES)} — либо "
        f"применение завели, не объявив его решением, и цель подмены перестала "
        f"читаться по шаблону, либо запись пережила своё применение"
    )

    unexplained = sorted(
        key for key, reason in RETARGET_RESWAP_USES.items() if not reason.strip()
    )
    assert not unexplained, (
        f"применение объявлено без обоснования: {unexplained} — читатель через "
        f"фазу не отличит принятое решение от забытой работы"
    )

    in_markup = _markup_naming_a_pointed_header(_template_sources())
    assert not in_markup, (
        f"имя точечного заголовка набрано в разметке: {in_markup} — решение о "
        f"перенацеливании принимается в слое ответа, и второе его место означает "
        f"два расходящихся решения об одной форме"
    )


def test_the_number_of_retarget_or_reswap_uses_is_the_declared_one():
    """Применений ровно ``RETARGET_RESWAP_USES_DECLARED``, и сегодня это НОЛЬ.

    ⚠️ НОЛЬ ОБЪЯВЛЕН ИМЕНОВАННОЙ КОНСТАНТОЙ ИМЕННО ПОТОМУ, ЧТО ОН НОЛЬ. Без неё
    правило полноты выше осталось бы вакуумно зелёным навсегда: пустое множество
    равно пустому перечню при любом состоянии сканера. Прецедент формы —
    `HX_TARGETS` и `SERVER_SIDE_VALIDATION_RESPONSES`, объявлявшиеся нулём до
    появления первого предмета.

    ⚠️ ВЫРОСШЕЕ ЧИСЛО НЕ ЕСТЬ НАРУШЕНИЕ САМО ПО СЕБЕ — оно есть ТРЕБОВАНИЕ
    РЕШЕНИЯ. D-16 не запрещает эти заголовки; он запрещает применять их молча.
    """
    assert len(RETARGET_RESWAP_USES) == RETARGET_RESWAP_USES_DECLARED, (
        f"применений точечных заголовков в перечне {len(RETARGET_RESWAP_USES)}, "
        f"объявлено {RETARGET_RESWAP_USES_DECLARED}: "
        f"{sorted(RETARGET_RESWAP_USES)} — перечень подвинули, а летопись числа "
        f"об этом не знает"
    )


def test_control_an_undeclared_retarget_header_reddens_the_registry(tmp_path):
    """ЗУБЫ ПУСТОГО ПЕРЕЧНЯ: применение без записи краснит прогон И НАЗЫВАЕТ МЕСТО.

    ⚠️ ЭТОТ КОНТРОЛЬ — ЕДИНСТВЕННОЕ, ЧТО ОТЛИЧАЕТ «ПРИМЕНЕНИЙ НЕТ» ОТ «СКАНЕР
    НИЧЕГО НЕ НАХОДИТ». Оба состояния дают пустое множество и зелёное правило
    полноты; в одном из них следующая фаза заведёт перенацеливание, и ни одна
    строка прогона об этом не скажет.

    Утверждений два, и первое даёт второму предмет: сперва сканер ОБЯЗАН найти
    применение в подменённом модуле (иначе доказывалось бы не наличие зубов, а
    промах подстановки), затем правило полноты обязано покраснеть и назвать
    место ключом `модуль::функция` — общий отказ «перечень разошёлся» не сказал
    бы, где искать.
    """
    original = _pages_sources()[SCRATCH_MODULE]
    addition = (
        '\n\n@router.post("/profile/a-route-some-future-phase-will-retarget")\n'
        "async def a_route_some_future_phase_will_retarget(request: Request):\n"
        '    response = HTMLResponse("")\n'
        f'    response.headers["{RETARGET_HEADER}"] = "#somewhere-else"\n'
        "    return response\n"
    )
    sources = _sources_with(
        tmp_path, _pages_sources(), SCRATCH_MODULE, original + addition
    )

    key = f"{SCRATCH_MODULE}::a_route_some_future_phase_will_retarget"
    measured = _retarget_reswap_uses(sources)

    assert key in measured, (
        "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ ЛИБО СКАНЕР СЛЕП: применение точечного "
        "заголовка в подменённом модуле не найдено, и утверждение ниже "
        "доказывало бы не зубы перечня, а промах контроля"
    )
    assert measured[key] == RETARGET_HEADER, (
        f"сканер нашёл применение, но назвал заголовок {measured[key]!r} вместо "
        f"{RETARGET_HEADER!r} — отказ показал бы читателю не тот предмет"
    )

    assert set(measured) != set(RETARGET_RESWAP_USES), (
        "ПЕРЕЧЕНЬ СОШЁЛСЯ С ДЕРЕВОМ, В КОТОРОМ ЕСТЬ НЕОБЪЯВЛЕННОЕ ПРИМЕНЕНИЕ — "
        "правило полноты выродилось и пропустило бы перенацеливание, о котором "
        "решения никто не принимал"
    )

    # ⚠️ ПРЕЖНЯЯ РЕДАКЦИЯ ЭТОГО УТВЕРЖДЕНИЯ НАЗЫВАЕТСЯ, А НЕ СТИРАЕТСЯ (Фаза 12,
    # план 12-09). Здесь стояло `_retarget_reswap_uses(_app_sources()) == {}` —
    # запись, СМЕШАВШАЯ два разных утверждения: «подмена не протекла за границу
    # контроля» и «боевой перечень пуст». Пока перечень был пуст, они совпадали
    # посимвольно; с первым объявленным применением вторая половина стала
    # неправдой, и контроль покраснел бы на ЧУЖОМ предмете — на составе
    # перечня, а не на протечке. Предмет контроля возвращён себе и РАЗДЕЛЁН на
    # две проверки: синтетического ключа в боевом чтении нет, и боевое чтение
    # по-прежнему сходится с объявлением. Ослабления нет: при пустом перечне обе
    # строки вместе дают ровно прежнее `== {}`.
    fresh = _retarget_reswap_uses(_app_sources())
    assert key not in fresh, (
        "ПОДМЕНА ПРОТЕКЛА ЗА ГРАНИЦУ КОНТРОЛЯ: свежее чтение боевого дерева "
        f"вернуло синтетическое применение {key!r}, которого в нём нет"
    )
    assert set(fresh) == set(RETARGET_RESWAP_USES), (
        "свежее чтение боевого дерева разошлось с перечнем ПОСЛЕ контроля: "
        f"измерено {sorted(fresh)}, объявлено {sorted(RETARGET_RESWAP_USES)} — "
        "подстановка оставила след за своей границей"
    )


# =============================================================================
# ГЕЙТ КРИТЕРИЯ 3 ФАЗЫ 14: КТО УХОДИТ ПОЛНОЙ ПЕРЕЗАГРУЗКОЙ И КТО ВЫДАЁТ
# ЗАГОЛОВОК ЧАСТИЧНОГО ПЕРЕХОДА (Фаза 14, план 14-06, D-11)
# =============================================================================
#
# ТЕКСТ КРИТЕРИЯ 3 РОАДМАПА ДОСЛОВНО: «успех авторизации уходит `HX-Redirect`;
# `HX-Location` применяется только для `/impersonation/stop`». Требование —
# SIGN-03. До этого плана оно было НАБЛЮДЕНИЕМ: сверить его можно было только
# чтением модуля, и первый же обработчик, ушедший не тем заголовком, стал бы
# расхождением, о котором никто не узнал бы до ревизии. Здесь оно становится
# ПРАВИЛОМ.
#
# ⚠️ ПРЕДМЕТ ПРАВИЛ НАЗВАН ТОЧНО, И ГРАНИЦА ОБЪЯВЛЕНА ПРЯМО, А НЕ ОСТАВЛЕНА
# ЧИТАТЕЛЮ. Предмет — МОДУЛЬ АВТОРИЗАЦИИ (`app/pages/auth.py`) и выход полной
# перезагрузки СТРАНИЧНОГО СЛОЯ. У буквального текста критерия есть ВТОРОЙ
# ОТПРАВИТЕЛЬ `HX-Location`, и он живёт ВНЕ модуля авторизации: отказ
# зависимости `forbid_when_impersonating` на четырёх шагах восстановления
# пароля уходит `location_response` из обработчика `HtmxRefusal`
# (`app/main.py`, `app/dependencies.py`, `IMPERSONATION_REFUSED_LOCATION`).
# Этим правилом он НЕ ВИДИТСЯ ПО ПОСТРОЕНИЮ — не потому, что его прозевали, а
# потому, что вселенная правила есть модуль авторизации. Решение D-13 Фазы 14
# оставляет отказ как есть; летопись у критерия 3 и SIGN-03 ставит план 14-07
# (RESEARCH Находка 6). Записано это здесь затем, чтобы следующий читатель не
# принял зелёное правило за доказательство более широкого утверждения, чем то,
# которое оно проверяет.

# Имя выхода полной перезагрузки — ОДНО на весь гейт: вторая копия строки
# разъехалась бы с первой молча.
FULL_LOAD_CALL = "redirect_internal"

AUTH_MODULE = "app/pages/auth.py"

# ⚠️ ЧЕТЫРЕ ВЫЗЫВАЮЩИХ, И КАЖДЫЙ НАЗВАН РЕШЕНИЕМ, А НЕ ЗАМЕРОМ. Три первых —
# успехи авторизации, которым D-10 предписал полную загрузку (вход, завершение
# регистрации, новый пароль); четвёртый — единственная ветка возврата, уходящая
# ЧЕРЕЗ ГРАНИЦУ ШЕЛЛОВ (D-12): экран входа живёт во втором шелле, и фрагментом
# смену шелла не отдать. Перечень закрыт: пятый вызывающий означает решение о
# форме ответа, принятое без записи.
FULL_LOAD_HANDLERS = frozenset(
    {
        f"{AUTH_MODULE}::login_submit",
        f"{AUTH_MODULE}::register_complete",
        f"{AUTH_MODULE}::forgot_password_reset",
        f"{AUTH_MODULE}::stop_impersonation",
    }
)

# ⚠️ ЕДИНСТВЕННЫЙ ОТПРАВИТЕЛЬ ЗАГОЛОВКА ЧАСТИЧНОГО ПЕРЕХОДА В МОДУЛЕ
# АВТОРИЗАЦИИ — И ЭТО РОВНО ТО, ЧТО ГОВОРИТ БУКВАЛЬНЫЙ ТЕКСТ КРИТЕРИЯ 3.
AUTH_HX_LOCATION_HANDLERS = frozenset({f"{AUTH_MODULE}::stop_impersonation"})


def _calls_named(node: ast.AST, name: str) -> list[ast.Call]:
    """Вызовы имени `name` внутри узла — голым именем и через модуль.

    Обе формы засчитываются намеренно: `redirect_internal(...)` и
    `htmx.redirect_internal(...)` есть ОДИН И ТОТ ЖЕ выход, и разборщик,
    знающий только первую, ослеп бы ровно на той форме, к которой проект
    перешёл бы при первом конфликте имён.
    """
    found: list[ast.Call] = []
    for child in ast.walk(node):
        if not isinstance(child, ast.Call):
            continue
        func = child.func
        if isinstance(func, ast.Name) and func.id == name:
            found.append(child)
        elif isinstance(func, ast.Attribute) and func.attr == name:
            found.append(child)
    return found


def _full_load_calls(sources: dict[str, str]) -> list[tuple[str, int, ast.Call]]:
    """Все вызовы выхода полной перезагрузки в POST-обработчиках слоя.

    Возвращается тройка «ключ обработчика, строка, узел вызова»: правилу
    литерала нужен САМ узел, а не факт вызова, — иначе адрес, собранный
    переменной, был бы неотличим от литерала.
    """
    found: list[tuple[str, int, ast.Call]] = []
    for module, text in sources.items():
        tree = _parse(module, text)
        for node in ast.walk(tree):
            if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue
            if not any(_declares_post(decorator) for decorator in node.decorator_list):
                continue
            key = f"{module}::{node.name}"
            for call in _calls_named(node, FULL_LOAD_CALL):
                found.append((key, call.lineno, call))
    return found


def _full_load_callers(sources: dict[str, str]) -> set[str]:
    """POST-обработчики страничного слоя, зовущие выход полной перезагрузки."""
    return {key for key, _lineno, _call in _full_load_calls(sources)}


def _hx_location_emitters(
    sources: dict[str, str], module: str = AUTH_MODULE
) -> set[str]:
    """Функции модуля, способные выдать заголовок ЧАСТИЧНОГО перехода.

    ⚠️ ДВЕ ФОРМЫ, И ОБЕ НАЗВАНЫ. Первая — главный выход слоя БЕЗ фрагмента:
    `respond(...)`, которому фрагмент не подан, отвечает на пути htmx
    заголовком `HX-Location`, а с поданным фрагментом — телом, и заголовка не
    пишет вовсе. Именно поэтому предмет здесь — ОТСУТСТВИЕ именованного
    аргумента фрагмента, а не сам вызов выхода. Вторая — прямая сборка
    `location_response(...)`, которой заголовок пишется в одном месте слоя.

    ⚠️ ВСЕЛЕННАЯ — ОДИН МОДУЛЬ, И ЭТО ГРАНИЦА, А НЕ УПУЩЕНИЕ: буквальный текст
    критерия 3 говорит о `/impersonation/stop`, а второй отправитель заголовка
    живёт вне модуля авторизации (шапка группы называет его поимённо).
    """
    text = sources.get(module)
    if text is None:
        return set()

    emitters: set[str] = set()
    tree = _parse(module, text)
    for node in tree.body:
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        for call in _calls_named(node, "respond"):
            if not any(keyword.arg == "fragment" for keyword in call.keywords):
                emitters.add(f"{module}::{node.name}")
        if _calls_named(node, "location_response"):
            emitters.add(f"{module}::{node.name}")
    return emitters


def _local_literal_complaints(sources: dict[str, str]) -> list[str]:
    """Жалобы правила ЛИТЕРАЛА: адрес полной перезагрузки — строка с `/`.

    ⚠️ ПРЕДМЕТ — ОТКРЫТЫЙ РЕДИРЕКТ (T-14-01), А НЕ ОПРЯТНОСТЬ. Адрес,
    приехавший переменной, рантайм-проверка `_local_path` отвергнет уже у
    человека; правило требует, чтобы отвергать было НЕЧЕГО — чтобы негодный
    адрес не собирался как исходник. Один ведущий слеш и не два: `//evil.example`
    есть протокол-относительный адрес чужого сайта.
    """
    complaints: list[str] = []
    for key, lineno, call in _full_load_calls(sources):
        redirect = next(
            (keyword.value for keyword in call.keywords if keyword.arg == "redirect"),
            None,
        )
        where = f"{key} (строка {lineno})"
        if redirect is None:
            complaints.append(
                f"{where}: у вызова выхода полной перезагрузки нет аргумента "
                "`redirect=` — путь деградации не объявлен (FOUND-04)"
            )
            continue
        if not (isinstance(redirect, ast.Constant) and isinstance(redirect.value, str)):
            complaints.append(
                f"{where}: адрес полной перезагрузки собран НЕ ЛИТЕРАЛОМ "
                f"({type(redirect).__name__}) — открытый редирект закрыт только "
                "рантайм-проверкой, то есть уже у человека"
            )
            continue
        value = redirect.value
        if not value.startswith("/") or value.startswith("//"):
            complaints.append(
                f"{where}: адрес {value!r} не есть локальный путь — один ведущий "
                "слеш и не два (`//host` уводит на чужой сайт)"
            )
    return complaints


def test_only_the_named_auth_handlers_leave_by_a_full_load():
    """Выход полной перезагрузки зовут РОВНО четыре названных обработчика.

    ⚠️ РАВЕНСТВО, А НЕ ВКЛЮЧЕНИЕ, И ОБА НАПРАВЛЕНИЯ ЗНАЧАТ РАЗНОЕ. Лишний
    вызывающий означает решение о форме ответа, принятое без записи: обработчик
    уводит человека полной загрузкой там, где фаза объявила переход внутри
    шелла. Пропавший означает обратное — объявленный полной загрузкой успех
    ушёл фрагментом, то есть новая cookie приехала к куску ЧУЖОГО шелла.
    """
    callers = _full_load_callers(_pages_sources())

    assert callers, (
        "вселенная правила ПУСТА: вызывающих выход полной перезагрузки не "
        "найдено ни одного. Правило равенства на пустом замере доказывало бы "
        "поломку разбора, а не исполненный критерий"
    )
    assert callers == set(FULL_LOAD_HANDLERS), (
        "ВЫЗЫВАЮЩИЕ ВЫХОД ПОЛНОЙ ПЕРЕЗАГРУЗКИ РАЗОШЛИСЬ С ОБЪЯВЛЕННЫМИ "
        "(критерий 3, SIGN-03):\n  лишние: "
        + ", ".join(sorted(callers - set(FULL_LOAD_HANDLERS)) or ["—"])
        + "\n  пропавшие: "
        + ", ".join(sorted(set(FULL_LOAD_HANDLERS) - callers) or ["—"])
    )


def test_every_full_load_address_is_a_literal_local_path():
    """Адрес каждой полной перезагрузки — ЛИТЕРАЛ локального пути (T-14-01)."""
    sources = _pages_sources()

    assert _full_load_calls(sources), (
        "вселенная правила ПУСТА: вызовов выхода полной перезагрузки нет — "
        "утверждение об их адресах зелено вакуумно"
    )

    complaints = _local_literal_complaints(sources)

    assert not complaints, (
        "АДРЕС ПОЛНОЙ ПЕРЕЗАГРУЗКИ СОБРАН НЕ ЛИТЕРАЛОМ ЛОКАЛЬНОГО ПУТИ:\n  "
        + "\n  ".join(complaints)
    )


def test_hx_location_in_the_auth_module_belongs_to_the_return_only():
    """`HX-Location` в модуле авторизации выдаёт ТОЛЬКО возврат (критерий 3).

    ⚠️ ЧТО ИМЕННО ЗДЕСЬ СТЕРЕЖЁТСЯ. Успех входа и завершения регистрации ставит
    cookie НОВОЙ ЛИЧНОСТИ; уйди он заголовком частичного перехода, новая cookie
    приехала бы к документу, собранному ЧУЖИМ шеллом, и смена личности осталась
    бы половинчатой. Возврат из-под чужой личности — единственное место модуля,
    где переход внутри основного шелла ВЕРЕН: полоса имперсонации уезжает
    вместе с содержимым `body`, а приземление лежит в том же шелле (D-12).
    """
    emitters = _hx_location_emitters(_pages_sources())

    assert emitters, (
        "вселенная правила ПУСТА: отправителей заголовка частичного перехода в "
        "модуле авторизации не найдено ни одного — правило равенства зелено "
        "вакуумно, и `stop_impersonation` мог потерять свой выход молча"
    )
    assert emitters == set(AUTH_HX_LOCATION_HANDLERS), (
        "ОТПРАВИТЕЛИ `HX-Location` В МОДУЛЕ АВТОРИЗАЦИИ РАЗОШЛИСЬ С "
        "ОБЪЯВЛЕННЫМИ (критерий 3, SIGN-03):\n  лишние: "
        + ", ".join(sorted(emitters - set(AUTH_HX_LOCATION_HANDLERS)) or ["—"])
        + "\n  пропавшие: "
        + ", ".join(sorted(set(AUTH_HX_LOCATION_HANDLERS) - emitters) or ["—"])
        + "\n\nГраница правила названа в шапке группы: второй отправитель "
        "заголовка живёт ВНЕ модуля авторизации (отказ зависимости на шагах "
        "восстановления) и этим правилом не виден по построению"
    )


def test_control_a_fifth_full_load_caller_reddens_the_criterion_three_gate(tmp_path):
    """ЧТО ДОКАЗЫВАЕТ: пятый вызывающий ломает равенство И НАЗЫВАЕТСЯ ПО ИМЕНИ.

    Контроль ДВУХШАГОВЫЙ: сперва утверждается, что на НЕТРОНУТОМ дереве правило
    зелено, и только потом — что подмена его роняет. Без первого шага контроль
    зеленел бы и у правила, которое краснеет всегда.
    """
    untouched = _full_load_callers(_pages_sources())
    assert untouched == set(FULL_LOAD_HANDLERS), (
        "правило краснеет на неизменённом дереве — контроль доказывал бы зубы "
        "сломанного гейта"
    )

    key = f"{AUTH_MODULE}::a_fifth_route_leaving_by_a_full_load"
    addition = (
        '\n\n@router.post("/login/a-fifth-route")\n'
        "async def a_fifth_route_leaving_by_a_full_load(request: Request):\n"
        '    return await redirect_internal(request, redirect="/dashboard")\n'
    )
    sources = _sources_with(
        tmp_path, _pages_sources(), AUTH_MODULE, _pages_sources()[AUTH_MODULE] + addition
    )

    callers = _full_load_callers(sources)

    assert key in callers, (
        "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ: разборщик не увидел синтетического "
        "обработчика, и утверждение ниже проверяло бы нетронутое дерево"
    )
    assert callers != set(FULL_LOAD_HANDLERS), (
        "пятый вызывающий выхода полной перезагрузки НЕ ПОКРАСНИЛ равенства — "
        "решение о форме ответа можно принять без записи"
    )
    assert sorted(callers - set(FULL_LOAD_HANDLERS)) == [key], (
        "отказ не называет ИМЕНИ лишнего вызывающего: читатель отказа узнал бы "
        f"о расхождении, но не о его месте — {sorted(callers - set(FULL_LOAD_HANDLERS))}"
    )


def test_control_a_bare_respond_in_the_login_reddens_the_hx_location_gate(tmp_path):
    """ЧТО ДОКАЗЫВАЕТ: главный выход БЕЗ фрагмента у входа ломает равенство.

    Это самая правдоподобная ошибка исполнения: успех входа отвечает
    `respond(...)` вместо выхода полной перезагрузки — заголовок приезжает,
    переход происходит, и пара, проверяющая только адрес приземления, остаётся
    зелёной. Цена — cookie новой личности, приехавшая к куску чужого шелла.
    """
    assert _hx_location_emitters(_pages_sources()) == set(AUTH_HX_LOCATION_HANDLERS), (
        "правило краснеет на неизменённом дереве"
    )

    original = _pages_sources()[AUTH_MODULE]
    anchor = '    response = await redirect_internal(request, redirect="/dashboard")'
    assert original.count(anchor) >= 1, (
        "якорь подмены исчез из модуля авторизации — контроль подменял бы "
        "ничего"
    )
    patched = original.replace(
        anchor,
        '    await respond(request, redirect="/dashboard")\n' + anchor,
        1,
    )
    sources = _sources_with(tmp_path, _pages_sources(), AUTH_MODULE, patched)

    emitters = _hx_location_emitters(sources)
    key = f"{AUTH_MODULE}::login_submit"

    assert key in emitters, (
        "ПОДМЕНА НЕ ПРИЗЕМЛИЛАСЬ ТУДА, КУДА ЦЕЛИЛАСЬ: голый вызов главного "
        f"выхода не засчитан входу — {sorted(emitters)}"
    )
    assert emitters != set(AUTH_HX_LOCATION_HANDLERS), (
        "множество способных выдать `HX-Location` не выросло — правило слепо к "
        "главному выходу без фрагмента"
    )


def test_control_a_computed_full_load_address_reddens_the_literal_rule(tmp_path):
    """ЧТО ДОКАЗЫВАЕТ: адрес полной перезагрузки ПЕРЕМЕННОЙ краснит правило.

    Открытый редирект начинается ровно здесь: адрес, приехавший параметром
    запроса, доживает до рантайм-проверки и падает уже у человека. Правило
    требует, чтобы падать было нечему.
    """
    assert not _local_literal_complaints(_pages_sources()), (
        "правило литерала краснеет на неизменённом дереве"
    )

    original = _pages_sources()[AUTH_MODULE]
    anchor = 'redirect_internal(request, redirect="/dashboard")'
    assert original.count(anchor) >= 1, "якорь подмены исчез из модуля авторизации"
    patched = original.replace(
        anchor, "redirect_internal(request, redirect=target)", 1
    )
    sources = _sources_with(tmp_path, _pages_sources(), AUTH_MODULE, patched)

    complaints = _local_literal_complaints(sources)

    assert complaints, (
        "адрес, собранный ПЕРЕМЕННОЙ, не покраснил правила литерала — открытый "
        "редирект закрыт только рантайм-проверкой"
    )
    assert any("собран НЕ ЛИТЕРАЛОМ" in complaint for complaint in complaints), (
        f"жалоба не называет ПРИЧИНЫ расхождения: {complaints}"
    )
    assert any("login_submit" in complaint for complaint in complaints), (
        f"жалоба не называет МЕСТА расхождения: {complaints}"
    )


# =============================================================================
# РЕЕСТР РЕШЕНИЙ `hx-push-url`: КОНВЕНЦИЯ ТРЁХ СЛУЧАЕВ ПО КАЖДОМУ МЕСТУ ПИСЬМА
# (Фаза 15, план 15-11, QUAL-04, D-11…D-13)
#
# ⚠️ ДОМ ОПРЕДЕЛЁН ОСНОВАНИЕМ, А НЕ УДОБСТВОМ. Основание записано в этом же
# файле у перечня изъятий смещённого курсора и цитируется дословно: «Предмет
# изъятия — ФОРМА ОТВЕТА обработчика (в какую ветку слоя ответа он уходит), а
# это ровно предмет этого файла. Разметка здесь — УЛИКА, по которой изъятие
# доказывается». У решения о `hx-push-url` предмет тот же: может ли разметка
# формы нести атрибут, решает ветка, которой уходит её обработчик. Разметка —
# улика, поэтому реестр живёт здесь, а не в пакете разметочных гейтов, и
# нового файла под него не заведено.
#
# ПРАВИЛО КЛАССИФИКАЦИИ. Оно объявлено здесь, выше первого числа группы, и
# каждое число ниже снято счётом именно по нему:
#
#   • обработчик, имеющий ПЕРЕХОДНУЮ ВЕТКУ, → СЛУЧАЙ ТРЕТИЙ: решение об адресе
#     принадлежит ветке, то есть СЕРВЕРУ, и адрес приходит заголовком ответа;
#   • обработчик в `FRAGMENT_RESPONSE_HANDLERS` БЕЗ переходной ветки →
#     СЛУЧАЙ ВТОРОЙ: меняются только данные, атрибута нет, и это ЗАПИСАННОЕ
#     решение, а не пробел;
#   • обработчик, меняющий ЧТО показано и не дуальный (ни фрагмента, ни
#     перехода — адрес самого запроса и есть адрес нового экрана), → СЛУЧАЙ
#     ПЕРВЫЙ: `hx-push-url="true"`.
#
#   ⚠️ ДУАЛЬНОСТЬ ПОБЕЖДАЕТ НАЛИЧИЕ ФРАГМЕНТА. `hx-push-url` — СТАТИЧЕСКИЙ
#   атрибут разметки и по ветке ответа не меняется. ДУАЛЬНЫЙ обработчик стои́т
#   в `FRAGMENT_RESPONSE_HANDLERS` И имеет переходную ветку. Его форма с
#   `hx-push-url="true"` сменила бы адрес и во фрагментной ветке, где
#   показанное не менялось. Обоснования перечня фрагментных называют
#   дуальность прямо у четырёх обработчиков: `schedules_delete` («на
#   ПОСЛЕДНЕМ расписании тот же обработчик уходит в ветку перехода»),
#   `schedules_update` («Исходы вне экрана … тот же обработчик отдаёт
#   переходом»), `schedules_create` («„БЫЛО НОЛЬ“ ТОТ ЖЕ ОБРАБОТЧИК ОТДАЁТ
#   ПЕРЕХОДОМ») и `ads_update` («„Объявления нет“ тот же обработчик отдаёт
#   переходом на список»). Классификация по признаку «есть ли у обработчика
#   фрагмент хоть в какой-то ветке» отнесла бы все четыре ко второму случаю.
#
# ПЕРЕХОДНАЯ ВЕТКА — ЭТО ВЫЗОВ, А НЕ ИМЯ. Признак снимается разбором `ast` по
# вызовам выходов слоя ответа в теле обработчика (`TRANSITION_BRANCH_CALLS`):
#   • главный выход `respond(...)` БЕЗ именованного аргумента фрагмента: 204 и
#     заголовок `HX-Location` (слой собирает его в `location_response`);
#   • `redirect_internal(...)`: полная загрузка локального адреса
#     (`HX-Redirect`);
#   • `redirect_external(...)`: уход на внешний адрес оплаты (`HX-Redirect`).
# Греп посчитал бы имя и в комментарии, и в докстринге, и в закомментированном
# коде (свойство 2 шапки модуля).
#
#   ⚠️ ПОПРАВКА К ПЛАНУ, НАЗВАННАЯ, А НЕ СГЛАЖЕННАЯ (идиома D-30/D-32). План
#   15-11 назвал признаком переходной ветки вызовы `respond_screen` и
#   `location_response`. Замер 2026-09-24 опроверг оба имени. `location_response`
#   не зовёт НИ ОДИН POST-обработчик — его зовёт сам главный выход, когда
#   фрагмента нет. `respond_screen` этот же файл засчитывает ПЕРЕДАЧЕЙ
#   ФРАГМЕНТА (`_hands_a_fragment`, план 14-02: «обработчик, отвечающий им,
#   числился бы ветвью перехода, которой он не является»). Признак по букве
#   плана дал бы восемь дуальных, все из модуля авторизации, и ни одного из
#   четырёх названных выше. Признак по вызову даёт девятнадцать, и все четыре
#   среди них.
#
# У ТРЕТЬЕГО СЛУЧАЯ В ДЕРЕВЕ ТРИ ЗАГОЛОВКА, А НЕ ОДИН. Адрес, известный только
# серверу, приезжает одним из них (замер вендоренного htmx 2.0.10):
#   • `HX-Location`: htmx сам ставит `push` в `"true"`, делает GET и
#     ВОЗВРАЩАЕТСЯ до обработки истории исходного запроса. Адрес нового экрана
#     уходит в историю из заголовка, а атрибут формы до этой ветки не доходит;
#   • `HX-Redirect`: полная загрузка, адрес меняет сам браузер;
#   • `HX-Push-Url`: адрес без перехода. Отправитель в `app/` один (ниже).
#
# КЛЮЧ РЕЕСТРА — `путь/файл.py::имя_функции`, та же форма, что у
# `POST_HANDLERS` и `FRAGMENT_RESPONSE_HANDLERS`. Основание записано у перечня
# фрагментных и цитируется: «два счёта считают подмножества ОДНОГО множества
# POST-обработчиков, и разная форма ключа сделала бы правило согласованности
# ниже неисполнимым». Реестр — третий счёт того же множества.
#
# МЕСТО ПИСЬМА ПОЛУЧАЕТ РЕШЕНИЕ СВОЕГО ОБРАБОТЧИКА. 49 мест письма взяты из
# инвентаря плана 15-02 (`tests/test_templates/test_form_inventory.py`, ключ
# `путь#порядковый_номер`). Адрес места (`action`, у сырой формы вдобавок
# `hx-post`) разрешается в POST-обработчик по СКЕЛЕТУ маршрута: каждое
# выражение шаблонизатора и каждый параметр пути заменяются на `{}`. Форма
# панели подтверждения (`components/modal.html#0`) получает адрес ПАРАМЕТРОМ,
# поэтому её обработчики — это обработчики 18 форм-триггеров, которые её
# открывают (связку доказал план 15-10). Порядок строк реестра не несущий:
# ключи сравниваются МНОЖЕСТВАМИ. Два места с посимвольно одинаковым тегом
# различаются порядковым номером и никогда не схлопываются в один ключ.
#
# ⚠️ НОЛЬ АТРИБУТА ЕСТЬ РЕШЕНИЕ, А НЕ ПРОБЕЛ (D-12). `hx-push-url` в
# `app/templates/` — ноль. Порознь это утверждение не отличает «решение
# принято: атрибута нет» от «решение не принималось». Поэтому ноль
# утверждается В ПАРЕ с полнотой реестра, одним правилом
# (`test_push_url_zero_in_markup_is_a_decision_not_a_gap`).
#
# ЛЕТОПИСЬ ЧИСЛА ОТПРАВИТЕЛЕЙ `HX-Push-Url`: 2 → 1 (Фаза 15, план 15-11).
# `15-CONTEXT.md` D-12 говорит: «`HX-Push-Url` в `app/` — 2». ⚠️ ПРОГНОЗ НЕ
# БЫЛ ОШИБКОЙ — ОН УСТАРЕЛ: на момент своей записи он был верным, и правится
# не он, а числа, которые он пережил. Сеть «вхождения имени заголовка»
# посчитала вместе с отправителем прозу. Новое число снято РАЗБОРОМ `ast` ПО
# ПРИСВАИВАНИЯМ, а не грепом по имени заголовка: это обход `_header_writes`
# гейта G-13 с отбором по имени. Реальный отправитель ОДИН —
# `app/pages/ads.py:783`, присваивание
# `response.headers["HX-Push-Url"] = f"/ads/{saved.id}/edit"` в сборщике
# `_fragment`. Упоминаний в ПРОЗЕ два: докстринг `app/pages/htmx.py:694` и
# комментарий шаблона `app/templates/ads/includes/autosave_response.html:146`.
# Запись контекста НЕ ПРАВИТСЯ. Третий случай заголовком `HX-Push-Url`
# применён в дереве ОДИН раз, и от этой базы считается работа фазы.
# Формула оговорки та же, что у летописи 47 → 49 плана 15-02, одной строкой:
# «ПРОГНОЗ НЕ БЫЛ ОШИБКОЙ — ОН УСТАРЕЛ».
#
# ⚠️ ЧЕГО ЭТА ГРУППА НЕ УТВЕРЖДАЕТ (D-16). Зелёный цвет означает: по каждому
# POST-обработчику и каждому месту письма решение ЗАПИСАНО, принадлежит
# объявленному перечню случаев и совпадает с выведенным из формы ответа. Он НЕ
# означает, что решение ВЕРНО: верность конвенции есть человеческое суждение,
# и спорные формы (формы дуальных обработчиков) вынесены владельцу
# (`15-FORM-DECISIONS.md`, задача 3 плана). Он НЕ означает, что адрес
# действительно меняется в браузере и что Back и F5 работают на переведённых
# экранах: это пункт 7 ручного обхода, закрытый Фазой 11 и по D-15
# принимаемый её записью. Чего группа НЕ ВИДИТ:
#   1. переход за псевдонимом импорта выхода (`respond as reply`) — граница
#      унаследована у `_calls_response_layer`;
#   2. фрагмент, поданный распаковкой `**kwargs`: такой вызов засчитан
#      переходом. Ошибка уходит в третий случай, а не в «атрибута нет»;
#   3. ветку ошибки поля (`respond_field_error`, 422 той же формой): в
#      дуальность она не засчитывается, потому что перечень фрагментных её не
#      несёт (решение плана 14-02).
# =============================================================================

PUSH_URL_CASE_ONE = "первый"
PUSH_URL_CASE_TWO = "второй"
PUSH_URL_CASE_THREE = "третий"

# Перечень случаев конвенции — закрытый, с текстом каждого случая.
